using System;
using System.Collections.Generic;

// ATB 턴 큐: Id = 유닛, Priority = 게이지가 가득 차는 틱(ReadyTick)
// A* open list: Id = 노드, Priority = f = g + h
public struct HeapEntry
{
    public int Id;
    public long Priority;
    public long Seq; // Push/Update 순번: Priority 동률일 때의 타이브레이커
}

public sealed class MinHeap
{
    private readonly List<HeapEntry> _heap = new List<HeapEntry>();
    private long _nextSeq;

    public int Count => _heap.Count;

    public void Push(int id, long priority)
    {
        _heap.Add(new HeapEntry { Id = id, Priority = priority, Seq = _nextSeq++ });
        SiftUp(_heap.Count - 1);
    }

    public HeapEntry Pop()
    {
        if (_heap.Count == 0) throw new InvalidOperationException("heap is empty");
        HeapEntry top = _heap[0];
        int last = _heap.Count - 1;
        _heap[0] = _heap[last];
        _heap.RemoveAt(last);
        if (_heap.Count > 1) SiftDown(0);
        return top;
    }

    // 선형 탐색 O(n) + 재정렬 O(log n). 값이 커졌는지 작아졌는지에 따라 방향이 다르다.
    public bool Update(int id, long newPriority)
    {
        for (int i = 0; i < _heap.Count; i++)
        {
            if (_heap[i].Id != id) continue;
            HeapEntry old = _heap[i];
            HeapEntry updated = new HeapEntry { Id = id, Priority = newPriority, Seq = _nextSeq++ };
            _heap[i] = updated;
            if (Less(updated, old)) SiftUp(i);   // 작아졌다 -> 위로
            else SiftDown(i);                    // 커졌다(또는 동률) -> 아래로
            return true;
        }
        return false;
    }

    // (Priority, Seq) 사전식 비교. Seq 는 유일하므로 전순서(total order)가 된다.
    private static bool Less(HeapEntry a, HeapEntry b)
    {
        if (a.Priority != b.Priority) return a.Priority < b.Priority;
        return a.Seq < b.Seq;
    }

    private void SiftUp(int i)
    {
        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (!Less(_heap[i], _heap[parent])) break;
            (_heap[i], _heap[parent]) = (_heap[parent], _heap[i]);
            i = parent;
        }
    }

    private void SiftDown(int i)
    {
        int n = _heap.Count;
        while (true)
        {
            int left = 2 * i + 1;
            if (left >= n) break;
            int right = left + 1;
            // 두 자식 중 더 작은 쪽과 비교해야 한다.
            int smallest = (right < n && Less(_heap[right], _heap[left])) ? right : left;
            if (!Less(_heap[smallest], _heap[i])) break;
            (_heap[i], _heap[smallest]) = (_heap[smallest], _heap[i]);
            i = smallest;
        }
    }
}

