using System;
using System.Collections.Generic;

public static class TilePathfinder
{
    private struct OpenEntry
    {
        public int Id;  // 타일 번호 = y * width + x
        public int G;   // 넣을 당시의 g. 꺼냈을 때 낡은 항목인지 판별하는 데 쓴다
        public int F;   // g + h
        public int H;   // f 동률일 때의 타이브레이커
    }

    // (F, H) 사전식 이진 최소 힙. decrease-key 가 없으므로 같은 타일이 여러 번 들어갈 수 있다.
    private sealed class OpenList
    {
        private OpenEntry[] _a = new OpenEntry[64];
        public int Count { get; private set; }

        private static bool Less(in OpenEntry a, in OpenEntry b)
        {
            if (a.F != b.F) return a.F < b.F;
            return a.H < b.H; // f 가 같으면 목표에 더 가까운 쪽 먼저
        }

        public void Push(OpenEntry e)
        {
            if (Count == _a.Length) Array.Resize(ref _a, Count * 2);
            int i = Count++;
            while (i > 0)
            {
                int parent = (i - 1) / 2;
                if (!Less(e, _a[parent])) break;
                _a[i] = _a[parent];
                i = parent;
            }
            _a[i] = e;
        }

        public OpenEntry Pop()
        {
            OpenEntry top = _a[0];
            OpenEntry last = _a[--Count];
            int i = 0;
            while (true)
            {
                int child = 2 * i + 1;
                if (child >= Count) break;
                if (child + 1 < Count && Less(_a[child + 1], _a[child])) child++;
                if (!Less(_a[child], last)) break;
                _a[i] = _a[child];
                i = child;
            }
            if (Count > 0) _a[i] = last;
            return top;
        }
    }

    private static readonly int[] Dx = { 1, 0, -1, 0 };
    private static readonly int[] Dy = { 0, 1, 0, -1 };

    public static List<(int x, int y)> FindPath(int[,] cost, (int x, int y) start, (int x, int y) goal, out int expanded)
    {
        expanded = 0;
        var path = new List<(int x, int y)>();
        int height = cost.GetLength(0), width = cost.GetLength(1);
        if (!Walkable(cost, width, height, start.x, start.y)) return path;
        if (!Walkable(cost, width, height, goal.x, goal.y)) return path;

        int n = width * height;
        int startId = start.y * width + start.x;
        int goalId = goal.y * width + goal.x;

        var g = new int[n];
        var cameFrom = new int[n];
        for (int i = 0; i < n; i++) { g[i] = int.MaxValue; cameFrom[i] = -1; }

        var open = new OpenList();
        int h0 = Manhattan(start.x, start.y, goal.x, goal.y);
        g[startId] = 0;
        open.Push(new OpenEntry { Id = startId, G = 0, F = h0, H = h0 });

        bool found = false;
        while (open.Count > 0)
        {
            OpenEntry cur = open.Pop();
            if (cur.G != g[cur.Id]) continue; // 더 싼 경로로 다시 들어간 뒤 남은 낡은 항목
            expanded++;
            if (cur.Id == goalId) { found = true; break; } // 넣을 때가 아니라 꺼낼 때 종료한다

            int cx = cur.Id % width, cy = cur.Id / width;
            for (int d = 0; d < 4; d++)
            {
                int nx = cx + Dx[d], ny = cy + Dy[d];
                if (!Walkable(cost, width, height, nx, ny)) continue;
                int next = ny * width + nx;
                int ng = cur.G + cost[ny, nx];
                if (ng >= g[next]) continue; // 더 싸질 때만 갱신한다
                g[next] = ng;
                cameFrom[next] = cur.Id;
                int h = Manhattan(nx, ny, goal.x, goal.y);
                open.Push(new OpenEntry { Id = next, G = ng, F = ng + h, H = h });
            }
        }

        if (!found) return path;
        for (int c = goalId; c != -1; c = cameFrom[c]) path.Add((c % width, c / width));
        path.Reverse(); // goal -> start 순서로 모았으므로 뒤집는다
        return path;
    }

    private static bool Walkable(int[,] cost, int width, int height, int x, int y)
    {
        return x >= 0 && y >= 0 && x < width && y < height && cost[y, x] > 0;
    }

    // 타일 진입 비용의 최솟값이 1 이므로 "1 x 맨해튼 거리"는 실제 비용을 넘지 않는다.
    private static int Manhattan(int x, int y, int gx, int gy)
    {
        return Math.Abs(x - gx) + Math.Abs(y - gy);
    }
}

