        }
        return sb.ToString();
    }

    static string Slots(Inventory inv, int slots, string expected, string when)
    {
        string got = Dump(inv, slots);
        return got == expected ? null : when + ": 슬롯 기대 [" + expected + "] / 결과 [" + got + "]";
    }

    static string Count(Inventory inv, int itemId, int expected, string when)
    {
        int got = inv.CountOf(itemId);
        return got == expected ? null : when + ": CountOf(" + itemId + ") 기대 " + expected + " / 결과 " + got;
    }

    public static void Main()
    {
        Run("add-and-count", () =>
        {
            var inv = new Inventory(4, 5);
            string e = Count(inv, 7, 0, "빈 가방") ?? Slots(inv, 4, "- - - -", "빈 가방");
            if (e != null) return e;
            int left = inv.Add(7, 3);
            if (left != 0) return "Add(7,3) 반환값 기대 0 / 결과 " + left;
            return Count(inv, 7, 3, "Add(7,3) 후") ?? Count(inv, 8, 0, "Add(7,3) 후") ?? Slots(inv, 4, "7x3 - - -", "Add(7,3) 후");
        });

        Run("fill-existing-stack-first", () =>
        {
            var inv = new Inventory(4, 5);
            inv.Add(7, 3); inv.Add(9, 1);
            int left = inv.Add(7, 4); // 기존 스택에 2개, 새 슬롯에 2개
            if (left != 0) return "Add(7,4) 반환값 기대 0 / 결과 " + left;
            string e = Slots(inv, 4, "7x5 9x1 7x2 -", "7x3, 9x1 뒤 Add(7,4)") ?? Count(inv, 7, 7, "Add(7,4) 후");
            if (e != null) return e;
            left = inv.Add(7, 12); // 한 번에 여러 슬롯: 7x2 -> 7x5 (3개), 빈 슬롯 1칸에 5개, 4개는 못 넣음
            if (left != 4) return "Add(7,12) 반환값 기대 4 / 결과 " + left;
            return Slots(inv, 4, "7x5 9x1 7x5 7x5", "Add(7,12) 후") ?? Count(inv, 7, 15, "Add(7,12) 후");
        });

        Run("full-bag-returns-leftover", () =>
        {
            var inv = new Inventory(2, 10);
            int left = inv.Add(1, 25);
            if (left != 5) return "2칸x10 가방에 Add(1,25) 반환값 기대 5 / 결과 " + left;
            string e = Slots(inv, 2, "1x10 1x10", "Add(1,25) 후") ?? Count(inv, 1, 20, "Add(1,25) 후");
            if (e != null) return e;
            left = inv.Add(2, 3);
            if (left != 3) return "가득 찬 가방에 Add(2,3) 반환값 기대 3 / 결과 " + left;
            return Count(inv, 2, 0, "가득 찬 가방에 Add(2,3) 후") ?? Slots(inv, 2, "1x10 1x10", "가득 찬 가방에 Add(2,3) 후");
        });

        Run("remove-is-all-or-nothing", () =>
        {
            var inv = new Inventory(3, 5);
            inv.Add(7, 8); // 7x5 7x3 -
            if (inv.Remove(7, 9)) return "8개 보유 중 Remove(7,9) 가 true 를 반환";
            string e = Slots(inv, 3, "7x5 7x3 -", "실패한 Remove(7,9) 후") ?? Count(inv, 7, 8, "실패한 Remove(7,9) 후");
            if (e != null) return e;
            if (inv.Remove(3, 1)) return "없는 아이템 Remove(3,1) 가 true 를 반환";
            if (!inv.Remove(7, 8)) return "8개 보유 중 Remove(7,8) 가 false 를 반환";
            return Slots(inv, 3, "- - -", "Remove(7,8) 후") ?? Count(inv, 7, 0, "Remove(7,8) 후");
        });

        Run("remove-from-back-and-free-slot", () =>
        {
            var inv = new Inventory(4, 5);
            inv.Add(7, 12); // 7x5 7x5 7x2 -
            if (!inv.Remove(7, 4)) return "Remove(7,4) 가 false 를 반환";
            string e = Slots(inv, 4, "7x5 7x3 - -", "7x5 7x5 7x2 에서 Remove(7,4)") ?? Count(inv, 7, 8, "Remove(7,4) 후");
            if (e != null) return e;
            inv.Add(9, 6); // 비워진 슬롯을 다른 아이템이 다시 쓴다
            e = Slots(inv, 4, "7x5 7x3 9x5 9x1", "Add(9,6) 후") ?? Count(inv, 9, 6, "Add(9,6) 후");
            if (e != null) return e;
            inv.Remove(7, 8);
            inv.Add(9, 2); // 9x1 스택을 먼저 채우고, 남으면 가장 앞의 빈 슬롯으로
            return Slots(inv, 4, "9x2 - 9x5 9x1", "7 을 모두 뺀 뒤 Add(9,2)") == null ? "기존 스택(9x1)을 먼저 채워야 하는데 빈 슬롯부터 채움"
                : Slots(inv, 4, "- - 9x5 9x3", "7 을 모두 뺀 뒤 Add(9,2)") ?? Count(inv, 9, 8, "Add(9,2) 후");
        });

        Run("max-stack-one", () =>
        {
            var inv = new Inventory(3, 1); // 장비처럼 겹치지 않는 아이템
            int left = inv.Add(5, 2);
            if (left != 0) return "Add(5,2) 반환값 기대 0 / 결과 " + left;
            inv.Add(6, 5);
            string e = Slots(inv, 3, "5x1 5x1 6x1", "maxStack 1") ?? Count(inv, 6, 1, "maxStack 1") ?? Count(inv, 5, 2, "maxStack 1");
            if (e != null) return e;
            inv.Remove(5, 1);
            return Slots(inv, 3, "5x1 - 6x1", "Remove(5,1) 후") ?? Count(inv, 5, 1, "Remove(5,1) 후");
        });

        Run("random-vs-reference", () =>
        {
            uint s = 4242u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            for (int run = 0; run < 200; run++)
            {
                int slots = 1 + rnd(8), max = 1 + rnd(6);
                var inv = new Inventory(slots, max);
                var item = new int[slots]; var cnt = new int[slots]; // 기준 모델
                for (int k = 0; k < 60; k++)
                {
                    int id = 1 + rnd(4), amount = 1 + rnd(max * 3);
                    string op;
                    if (rnd(100) < 55)
                    {
                        int rem = amount;
                        for (int i = 0; i < slots && rem > 0; i++) if (item[i] == id) { int p = System.Math.Min(max - cnt[i], rem); cnt[i] += p; rem -= p; }
                        for (int i = 0; i < slots && rem > 0; i++) if (item[i] == 0) { int p = System.Math.Min(max, rem); item[i] = id; cnt[i] = p; rem -= p; }
                        int got = inv.Add(id, amount);
                        op = "Add(" + id + "," + amount + ")";
                        if (got != rem) return "무작위 " + run + "회차 " + op + " 반환값 기대 " + rem + " / 결과 " + got;
                    }
                    else
                    {
                        int have = 0;
                        for (int i = 0; i < slots; i++) if (item[i] == id) have += cnt[i];
                        bool ok = have >= amount;
                        if (ok)
                        {
                            int rem = amount;
                            for (int i = slots - 1; i >= 0 && rem > 0; i--) if (item[i] == id) { int t = System.Math.Min(cnt[i], rem); cnt[i] -= t; rem -= t; if (cnt[i] == 0) item[i] = 0; }
                        }
                        bool got = inv.Remove(id, amount);
                        op = "Remove(" + id + "," + amount + ")";
                        if (got != ok) return "무작위 " + run + "회차 " + op + " 반환값 기대 " + ok + " / 결과 " + got;
                    }
                    var sb = new System.Text.StringBuilder();
                    for (int i = 0; i < slots; i++) { if (i > 0) sb.Append(' '); if (item[i] == 0) sb.Append('-'); else sb.Append(item[i]).Append('x').Append(cnt[i]); }
                    string e = Slots(inv, slots, sb.ToString(), "무작위 " + run + "회차 " + op + " 후");
                    if (e != null) return e;
                    for (int id2 = 1; id2 <= 4; id2++)
                    {
                        int have = 0;
                        for (int i = 0; i < slots; i++) if (item[i] == id2) have += cnt[i];
                        e = Count(inv, id2, have, "무작위 " + run + "회차 " + op + " 후");
                        if (e != null) return e;
                    }
                }
            }
            return null;
        });
    }
}

