using System;

// 난수원: Next() 는 0 .. Range-1 의 정수를 균등하게 낸다.
public interface IRandomSource
{
    int Range { get; }
    int Next();
}

// xorshift32 의 상위 16비트를 쓰는 시드 고정 난수원.
// 같은 seed 로 만든 인스턴스는 항상 같은 수열을 내야 한다(리플레이, 서버 검증).
public sealed class XorShiftSource : IRandomSource
{
    private static uint _state;

    public XorShiftSource(uint seed)
    {
        _state = seed == 0 ? 0x9E3779B9u : seed; // xorshift 의 상태는 0 이면 안 된다
    }

    public int Range => 65536;

    public int Next()
    {
        uint x = _state;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        _state = x;
        return (int)(x >> 16);
    }
}

public sealed class LootTable
{
    private int[] _ids = new int[8];
    private int[] _cumulative = new int[8]; // _cumulative[i] = 0..i 번 항목의 가중치 합
    private int _count;

    public int TotalWeight { get; private set; }

    // weight 0 은 "지금은 드롭하지 않음"을 뜻하며 허용한다. 음수는 예외.
    public void Add(int itemId, int weight)
    {
        if (weight < 0) throw new ArgumentOutOfRangeException(nameof(weight));
        if (_count == _ids.Length)
        {
            Array.Resize(ref _ids, _count * 2);
            Array.Resize(ref _cumulative, _count * 2);
        }
        TotalWeight += weight;
        _ids[_count] = itemId;
        _cumulative[_count] = TotalWeight;
        _count++;
    }

    // roll 은 0 .. TotalWeight-1. 항목 i 는 [앞 항목들의 가중치 합, 그 값 + weight_i) 구간을 가진다.
    public int ItemForRoll(int roll)
    {
        if (roll < 0 || roll >= TotalWeight) throw new ArgumentOutOfRangeException(nameof(roll));
        int i = Array.BinarySearch(_cumulative, 0, _count, roll);
        if (i < 0) i = ~i;
        return _ids[i];
    }

    // rng 에서 값을 뽑아 가중치에 비례하는 확률로 아이템 하나를 고른다.
    public int Pick(IRandomSource rng)
    {
        if (TotalWeight <= 0) throw new InvalidOperationException("loot table has no weight");
        int roll = rng.Next() % TotalWeight;
        return ItemForRoll(roll);
    }
}

