using System;
using System.Collections.Generic;

// 채팅 금칙어 필터. 금칙어는 트라이(Trie)에 넣고, 메시지는 한 글자씩 따라 내려가며 검사한다.
public sealed class ProfanityFilter
{
    private sealed class Node
    {
        public readonly Dictionary<char, Node> Children = new Dictionary<char, Node>();
        public bool IsWord; // 루트에서 이 노드까지 내려온 글자들이 금칙어 하나를 이룬다
    }

    private readonly Node _root = new Node();

    public void AddWord(string word)
    {
        if (string.IsNullOrEmpty(word)) return; // 빈 금칙어는 루트를 "단어 끝"으로 만들어 버리므로 받지 않는다

        Node node = _root;
        for (int i = 0; i < word.Length; i++)
        {
            char c = char.ToLowerInvariant(word[i]); // 넣을 때와 찾을 때 같은 변환을 쓴다
            if (!node.Children.TryGetValue(c, out Node next))
            {
                next = new Node();
                node.Children.Add(c, next);
            }
            node = next;
        }
        node.IsWord = true;
    }

    public string Mask(string message)
    {
        char[] buffer = null; // 가릴 글자가 처음 나올 때만 복사본을 만든다
        int i = 0;
        while (i < message.Length)
        {
            int length = LongestMatchAt(message, i);
            if (length == 0)
            {
                i++; // 이 위치에서 시작하는 금칙어가 없다: 한 글자만 전진
                continue;
            }
            if (buffer == null) buffer = message.ToCharArray();
            for (int k = 0; k < length; k++) buffer[i + k] = '*';
            i += length; // 가린 구간 다음 글자부터 다시 검사
        }
        return buffer == null ? message : new string(buffer);
    }

    // start 에서 시작하는 가장 긴 금칙어의 길이. 없으면 0.
    private int LongestMatchAt(string message, int start)
    {
        Node node = _root;
        int best = 0;
        for (int j = start; j < message.Length; j++)
        {
            if (!node.Children.TryGetValue(char.ToLowerInvariant(message[j]), out node)) break;
            if (node.IsWord) best = j - start + 1; // 더 내려갈 수 있어도 "여기까지는 금칙어"임을 기억해 둔다
        }
        return best;
    }
}

