public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static ProfanityFilter Make(params string[] words)
    {
        var f = new ProfanityFilter();
        foreach (string w in words) f.AddWord(w);
        return f;
    }

    // 금칙어 words 로 message 를 가렸을 때 expected 가 나오는지 본다.
    static string Check(string[] words, string message, string expected)
    {
        string got = Make(words).Mask(message);
        return got == expected ? null
            : "금칙어 [" + string.Join(", ", words) + "], 입력 \"" + message + "\": 기대 \"" + expected + "\" / 결과 \"" + got + "\"";
    }

    // 기준 구현: 각 위치에서 모든 금칙어를 하나씩 대 보고 가장 긴 것을 가린다.
    static string Reference(string[] words, string message)
    {
        var sb = new System.Text.StringBuilder();
        int i = 0;
        while (i < message.Length)
        {
            int best = 0;
            foreach (string w in words)
            {
                if (w.Length <= best || i + w.Length > message.Length) continue;
                bool same = true;
                for (int k = 0; same && k < w.Length; k++)
                    same = char.ToLowerInvariant(w[k]) == char.ToLowerInvariant(message[i + k]);
                if (same) best = w.Length;
            }
            if (best == 0) { sb.Append(message[i]); i++; }
            else { sb.Append('*', best); i += best; }
        }
        return sb.ToString();
    }

    public static void Main()
    {
        Run("basic-mask", () =>
            Check(new[] { "bad", "noob" }, "you are bad noob!", "you are *** ****!")
            ?? Check(new[] { "bad" }, "good game", "good game")
            ?? Check(new[] { "bad" }, "", "")
            ?? Check(new string[0], "nothing is banned", "nothing is banned")
            ?? Check(new[] { "bad" }, "bad", "***")
            ?? Check(new[] { "bad" }, "so bad", "so ***")
            ?? Check(new[] { "bad" }, "badge", "***ge")
            ?? Check(new[] { "bad" }, "ba", "ba"));

        Run("case-insensitive", () =>
            Check(new[] { "NooB" }, "NOOB nOOb noob", "**** **** ****")
            ?? Check(new[] { "lo" }, "HeLLo LOL", "HeL** **L")
            ?? Check(new[] { "gg" }, "GG Well Played", "** Well Played"));

        Run("longest-match-wins", () =>
            Check(new[] { "ab", "abc" }, "abc", "***")
            ?? Check(new[] { "abc", "ab" }, "abc", "***")
            ?? Check(new[] { "ab", "abc" }, "xabcx abx", "x***x **x")
            ?? Check(new[] { "a", "ab", "abc", "abcd" }, "abcde", "****e"));

        Run("fallback-to-shorter-word", () =>
            Check(new[] { "ab", "abcd" }, "abcx", "**cx")
            ?? Check(new[] { "ab", "abcd" }, "abc", "**c")
            ?? Check(new[] { "ab", "abcd" }, "abcd", "****")
            ?? Check(new[] { "a", "abcde" }, "abcdx", "*bcdx"));

        Run("restart-after-partial-match", () =>
            Check(new[] { "aab" }, "aaab", "a***")
            ?? Check(new[] { "abac" }, "ababac", "ab****")
            ?? Check(new[] { "noob" }, "nonoob", "no****"));

        Run("resume-after-masked-span", () =>
            Check(new[] { "ab", "bc" }, "abc", "**c")
            ?? Check(new[] { "aa" }, "aaa", "**a")
            ?? Check(new[] { "aa" }, "aaaa", "****")
            ?? Check(new[] { "ab", "bcd" }, "abcd bcd", "**cd ***"));

        Run("korean-and-symbols", () =>
            Check(new[] { "바보", "멍청이" }, "야 이 바보야! 멍청이", "야 이 **야! ***")
            ?? Check(new[] { "바보" }, "바 보", "바 보")
            ?? Check(new[] { "n00b", "g g" }, "N00B said g g", "**** said ***"));

        Run("random-vs-reference", () =>
        {
            uint s = 20261122u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            const string alphabet = "abcABC";
            for (int run = 0; run < 3000; run++)
            {
                int letters = run % 2 == 0 ? 2 : 6;
                var words = new string[1 + rnd(4)];
                for (int w = 0; w < words.Length; w++)
                {
                    var chars = new char[1 + rnd(4)];
                    for (int k = 0; k < chars.Length; k++) chars[k] = alphabet[rnd(letters)];
                    words[w] = new string(chars);
                }
                var msg = new char[rnd(13)];
                for (int k = 0; k < msg.Length; k++) msg[k] = alphabet[rnd(letters)];
                string message = new string(msg);
                string e = Check(words, message, Reference(words, message));
                if (e != null) return "무작위 " + run + "회차. " + e;
            }
            return null;
        });
    }
}

