using System;
using System.Collections.Generic;

// 기획 시트의 한 줄: 스킬 id 와 선행 스킬 id 목록(전부 배워야 이 스킬을 배울 수 있다).
public sealed class SkillDef
{
    public readonly string Id;
    public readonly string[] Requires;

    public SkillDef(string id, params string[] requires)
    {
        Id = id;
        Requires = requires;
    }
}

public sealed class SkillTreeReport
{
    // 선행으로 적혀 있지만 정의되지 않은 스킬 id. 같은 id 는 한 번만, 순서는 자유.
    public readonly List<string> MissingIds = new List<string>();

    // 순환이 있으면 그 순환 하나를 이루는 스킬 id 를 "선행 → 후행" 순서로 담는다. 없으면 빈 리스트.
    // Cycle[i] 는 Cycle[i + 1] 의 선행이고, 마지막 원소는 Cycle[0] 의 선행이다.
    public readonly List<string> Cycle = new List<string>();

    // 오류가 하나도 없을 때만 채운다: 모든 스킬이 한 번씩, 어떤 스킬이든 자기 선행들보다 뒤에 온다.
    public readonly List<string> LearnOrder = new List<string>();

    public bool IsValid => MissingIds.Count == 0 && Cycle.Count == 0;
}

public static class SkillTreeValidator
{
    private const byte Unvisited = 0, InProgress = 1, Done = 2;

    public static SkillTreeReport Validate(IReadOnlyList<SkillDef> skills)
    {
        var report = new SkillTreeReport();
        int n = skills.Count;

        // 1) id -> 인덱스. 이후로는 문자열 대신 정수 인덱스로만 그래프를 다룬다.
        var indexOf = new Dictionary<string, int>(n);
        for (int i = 0; i < n; i++) indexOf[skills[i].Id] = i;

        // 2) 선행 간선을 만들면서 없는 id 를 모은다. 없는 id 로 가는 간선은 그래프에 넣지 않는다.
        var prereqs = new List<int>[n];
        var missingSeen = new HashSet<string>();
        for (int i = 0; i < n; i++)
        {
            prereqs[i] = new List<int>(skills[i].Requires.Length);
            foreach (string req in skills[i].Requires)
            {
                if (indexOf.TryGetValue(req, out int p)) prereqs[i].Add(p);
                else if (missingSeen.Add(req)) report.MissingIds.Add(req);
            }
        }

        // 3) "스킬 → 선행" 방향으로 DFS. 선행을 전부 끝낸 뒤에 자신을 적으므로(후위 순서)
        //    적힌 순서가 그대로 배울 수 있는 순서다. 재귀 대신 명시적 스택을 써서
        //    선행 사슬이 아무리 길어도 호출 스택이 넘치지 않는다.
        var state = new byte[n];
        var nextEdge = new int[n];        // 스킬별로 다음에 볼 선행의 위치
        var path = new List<int>();       // 지금 내려가고 있는 경로(전부 InProgress)
        var order = new List<int>(n);

        for (int root = 0; root < n; root++)
        {
            if (state[root] != Unvisited) continue;
            state[root] = InProgress;
            path.Add(root);

            while (path.Count > 0)
            {
                int u = path[path.Count - 1];
                if (nextEdge[u] < prereqs[u].Count)
                {
                    int p = prereqs[u][nextEdge[u]++];
                    if (state[p] == Unvisited)
                    {
                        state[p] = InProgress;
                        path.Add(p);
                    }
                    else if (state[p] == InProgress && report.Cycle.Count == 0)
                    {
                        // p 가 아직 경로 위에 있다: 경로의 p 부터 끝(u)까지가 순환이다.
                        // 경로는 "후행 → 선행" 방향이므로 뒤에서부터 읽으면 "선행 → 후행" 이 된다.
                        for (int k = path.Count - 1; ; k--)
                        {
                            report.Cycle.Add(skills[path[k]].Id);
                            if (path[k] == p) break;
                        }
                    }
                }
                else
                {
                    state[u] = Done;
                    path.RemoveAt(path.Count - 1);
                    order.Add(u);
                }
            }
        }

        // 4) 오류가 하나도 없을 때만 순서를 내보낸다.
        if (report.IsValid)
            foreach (int i in order) report.LearnOrder.Add(skills[i].Id);
        return report;
    }
}

