        for (int i = 0; i < order.Count; i++)
        {
            if (order[i] == null || pos.ContainsKey(order[i])) return "LearnOrder 에 '" + order[i] + "' 가 두 번 나옴 " + Show(order);
            pos[order[i]] = i;
        }
        foreach (var s in skills)
        {
            if (!pos.ContainsKey(s.Id)) return "LearnOrder 에 '" + s.Id + "' 가 없음 " + Show(order);
            foreach (string r in s.Requires)
                if (pos.ContainsKey(r) && pos[r] > pos[s.Id]) return "'" + s.Id + "' 가 선행 '" + r + "' 보다 먼저 나옴 " + Show(order);
        }
        return null;
    }

    // Cycle 이 실제 순환인지: 서로 다른 id, Cycle[i] 가 Cycle[i+1] 의 선행, 마지막이 Cycle[0] 의 선행. (어느 순환이든, 어디서 시작하든 통과)
    static string CheckCycle(SkillDef[] skills, System.Collections.Generic.List<string> cycle)
    {
        if (cycle == null || cycle.Count == 0) return "순환이 있는데 Cycle 이 비어 있음";
        var req = new System.Collections.Generic.Dictionary<string, string[]>();
        foreach (var s in skills) req[s.Id] = s.Requires;
        var seen = new System.Collections.Generic.HashSet<string>();
        for (int i = 0; i < cycle.Count; i++)
        {
            string a = cycle[i], b = cycle[(i + 1) % cycle.Count];
            if (a == null || !req.ContainsKey(a)) return "Cycle 에 정의되지 않은 id '" + a + "' " + Show(cycle);
            if (!seen.Add(a)) return "Cycle 에 '" + a + "' 가 두 번 나옴 " + Show(cycle);
            if (b == null || !req.ContainsKey(b) || System.Array.IndexOf(req[b], a) < 0)
                return "Cycle 이 실제 순환이 아님: '" + a + "' 는 '" + b + "' 의 선행이 아님 " + Show(cycle);
        }
        return null;
    }

    // 기대하는 종류(없는 id 집합, 순환 여부)를 주고 보고서 전체를 검사한다.
    static string Check(SkillDef[] skills, string[] expectMissing, bool expectCycle)
    {
        SkillTreeReport r = SkillTreeValidator.Validate(skills);
        if (r == null) return "Validate 가 null 을 반환";
        var miss = r.MissingIds == null ? new System.Collections.Generic.List<string>() : new System.Collections.Generic.List<string>(r.MissingIds);
        miss.Sort(string.CompareOrdinal);
        var exp = new System.Collections.Generic.List<string>(expectMissing);
        exp.Sort(string.CompareOrdinal);
        if (string.Join(",", miss) != string.Join(",", exp)) return "MissingIds 기대 " + Show(exp) + " / 결과 " + Show(miss);
        if (expectCycle)
        {
            string e = CheckCycle(skills, r.Cycle);
            if (e != null) return e;
        }
        else if (r.Cycle == null || r.Cycle.Count != 0) return "순환이 없는데 Cycle 이 " + Show(r.Cycle);
        bool valid = exp.Count == 0 && !expectCycle;
        if (r.IsValid != valid) return "IsValid 기대 " + valid + " / 결과 " + r.IsValid;
        if (valid) return CheckOrder(skills, r.LearnOrder);
        if (r.LearnOrder == null || r.LearnOrder.Count != 0) return "오류가 있는 데이터인데 LearnOrder 가 비어 있지 않음 " + Show(r.LearnOrder);
        return null;
    }

    static readonly string[] None = new string[0];

    public static void Main()
    {
        Run("valid-tree-order", () =>
            Check(new[] { S("meteor", "fireball", "focus"), S("fireball", "ember"), S("focus"), S("ember") }, None, false)
            ?? Check(new[] { S("a"), S("b"), S("c") }, None, false)
            ?? Check(new SkillDef[0], None, false)
            ?? Check(new[] { S("d", "b", "c"), S("c", "a"), S("b", "a"), S("a") }, None, false));

        Run("missing-prerequisite-id", () =>
            Check(new[] { S("fireball", "ember"), S("ember"), S("meteor", "fireball", "focuss") }, new[] { "focuss" }, false)
            ?? Check(new[] { S("a", "x", "y"), S("b", "x"), S("c", "a", "y") }, new[] { "x", "y" }, false)
            ?? Check(new[] { S("a", "ghost", "ghost") }, new[] { "ghost" }, false));

        Run("self-reference", () =>
        {
            var skills = new[] { S("dash"), S("blink", "blink", "dash") };
            string e = Check(skills, None, true);
            if (e != null) return e;
            var c = SkillTreeValidator.Validate(skills).Cycle;
            return c.Count == 1 && c[0] == "blink" ? null : "자기 자신을 선행으로 적은 스킬: Cycle 기대 [blink] / 결과 " + Show(c);
        });

        Run("cycle-ids-only", () =>
        {
            // a -> b -> c -> a 가 순환. tail 은 순환에 매달려 있을 뿐이고 root 는 순환의 선행일 뿐이다.
            var skills = new[] { S("tail2", "tail"), S("tail", "c"), S("root"), S("a", "c", "root"), S("b", "a"), S("c", "b") };
            string e = Check(skills, None, true);
            if (e != null) return e;
            var c = SkillTreeValidator.Validate(skills).Cycle;
            if (c.Count != 3) return "순환은 a, b, c 세 개인데 Cycle 이 " + Show(c);
            return Check(new[] { S("x", "y"), S("y", "x"), S("z") }, None, true);
        });

        Run("duplicate-prerequisite", () =>
            Check(new[] { S("b", "a", "a"), S("a"), S("c", "b", "a", "b") }, None, false));

        Run("missing-and-cycle-together", () =>
            Check(new[] { S("a", "b", "nope"), S("b", "a"), S("c") }, new[] { "nope" }, true));

        Run("reverse-file-order-chain", () =>
        {
            // 시트에 후행 스킬이 먼저 적혀 있는 3,000 단계 사슬: s0 이 s1 을, s1 이 s2 를 ... 요구한다.
            int n = 3000;
            var skills = new SkillDef[n];
            for (int i = 0; i < n; i++) skills[i] = i + 1 < n ? S("s" + i, "s" + (i + 1)) : S("s" + i);
            string e = Check(skills, None, false);
            if (e != null) return e;
            skills[n - 1] = S("s" + (n - 1), "s0"); // 사슬 전체를 하나의 큰 순환으로 만든다
            e = Check(skills, None, true);
            if (e != null) return e;
            int len = SkillTreeValidator.Validate(skills).Cycle.Count;
            return len == n ? null : "스킬 " + n + "개가 모두 하나의 순환인데 Cycle 길이가 " + len;
        });

        Run("random-vs-reference", () =>
        {
            uint s = 31337u;
            System.Func<int, int> rnd = k => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)k); };
            for (int run = 0; run < 1500; run++)
            {
                int n = 1 + rnd(8);
                var skills = new SkillDef[n];
                var missing = new System.Collections.Generic.HashSet<string>();
                var edges = new bool[n, n]; // edges[i, p]: i 가 p 를 선행으로 요구
                for (int i = 0; i < n; i++)
                {
                    var req = new string[rnd(4) == 0 ? 2 + rnd(2) : rnd(2)];
                    for (int k = 0; k < req.Length; k++)
                    {
                        if (rnd(12) == 0) { req[k] = "m" + rnd(2); missing.Add(req[k]); }
                        else
                        {
                            // 절반의 회차는 인덱스가 작은 쪽만 가리켜 순환이 없고, 나머지는 아무 스킬이나 가리킨다
                            int p = run % 2 == 0 ? (i == 0 ? -1 : rnd(i)) : rnd(n);
                            if (p < 0) { req[k] = "m9"; missing.Add("m9"); }
                            else { req[k] = "k" + p; edges[i, p] = true; }
                        }
                    }
                    skills[i] = new SkillDef("k" + i, req);
                }
                // 기준: 선행이 모두 끝난 스킬을 반복해서 지워 나가고, 남는 것이 있으면 순환이 있다
                var done = new bool[n];
                bool progress = true;
                int left = n;
                while (progress)
                {
                    progress = false;
                    for (int i = 0; i < n; i++)
                    {
                        if (done[i]) continue;
                        bool ok = true;
                        for (int p = 0; ok && p < n; p++) if (edges[i, p] && !done[p]) ok = false;
                        if (ok) { done[i] = true; left--; progress = true; }
                    }
                }
                var m = new string[missing.Count];
                missing.CopyTo(m);
                string e = Check(skills, m, left > 0);
                if (e != null)
                {
                    var sb = new System.Text.StringBuilder();
                    foreach (var d in skills) sb.Append(d.Id).Append("<-[").Append(string.Join(",", d.Requires)).Append("] ");
                    return "무작위 " + run + "회차 (" + sb.ToString().TrimEnd() + "): " + e;
                }
            }
            return null;
        });
    }
}

