using System;
using System.Collections.Generic;

// 퀘스트 시트의 한 줄: 퀘스트 id 와 선행 퀘스트 id 목록(전부 완료해야 이 퀘스트가 해금된다).
public sealed class QuestDef
{
    public readonly string Id;
    public readonly string[] Requires;

    public QuestDef(string id, params string[] requires)
    {
        Id = id;
        Requires = requires;
    }
}

public sealed class ResolveResult
{
    // 해금 순서. 해금 가능한 퀘스트가 여럿이면 시트에서 위에 있는 것이 먼저다.
    public readonly List<string> Order = new List<string>();

    // 시트에 없는 선행 id 참조. "퀘스트id->없는id" 형식, 시트에 적힌 순서대로.
    public readonly List<string> MissingRefs = new List<string>();

    // 순환 때문에 영원히 해금되지 않는 퀘스트 id, 시트 순서대로.
    public readonly List<string> Blocked = new List<string>();
}

public static class QuestResolver
{
    // 퀘스트 id 는 서로 다르다고 가정한다.
    public static ResolveResult Resolve(IReadOnlyList<QuestDef> quests)
    {
        var result = new ResolveResult();
        int n = quests.Count;

        var indexOf = new Dictionary<string, int>(n);
        for (int i = 0; i < n; i++) indexOf[quests[i].Id] = i;

        var dependents = new List<int>[n]; // dependents[p] = p 를 선행으로 가진 퀘스트들
        var remaining = new int[n];        // 아직 완료되지 않은 선행의 수
        for (int i = 0; i < n; i++) dependents[i] = new List<int>();

        for (int i = 0; i < n; i++)
        {
            remaining[i] = quests[i].Requires.Length;
            foreach (string req in quests[i].Requires)
            {
                int p = indexOf[req];
                dependents[p].Add(i);

                // 서로를 선행으로 적은 퀘스트는 영원히 해금되지 않는다
                if (Array.IndexOf(quests[p].Requires, quests[i].Id) >= 0 && !result.Blocked.Contains(quests[i].Id))
                    result.Blocked.Add(quests[i].Id);
            }
        }

        var ready = new Stack<int>();
        for (int i = 0; i < n; i++)
            if (remaining[i] == 0) ready.Push(i);

        while (ready.Count > 0)
        {
            int q = ready.Pop();
            result.Order.Add(quests[q].Id);
            foreach (int d in dependents[q])
                if (--remaining[d] == 0) ready.Push(d);
        }

        return result;
    }
}

