public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static QuestDef Q(string id, params string[] requires) { return new QuestDef(id, requires); }

    static string Show(System.Collections.Generic.IEnumerable<string> list)
    {
        return list == null ? "null" : "[" + string.Join(", ", list) + "]";
    }

    static string Sheet(QuestDef[] quests)
    {
        var sb = new System.Text.StringBuilder();
        foreach (var q in quests) sb.Append(q.Id).Append("<-[").Append(string.Join(",", q.Requires)).Append("] ");
        return sb.ToString().TrimEnd();
    }

    // 세 목록을 기대값과 그대로(순서까지) 비교한다. 쉼표로 구분한 문자열로 적는다.
    static string Check(QuestDef[] quests, string order, string missing, string blocked)
    {
        ResolveResult r = QuestResolver.Resolve(quests);
        if (r == null) return "Resolve 가 null 을 반환";
        string e = One("Order", r.Order, order) ?? One("MissingRefs", r.MissingRefs, missing) ?? One("Blocked", r.Blocked, blocked);
        return e == null ? null : "시트 (" + Sheet(quests) + "): " + e;
    }

    static string One(string name, System.Collections.Generic.List<string> got, string expected)
    {
        string g = got == null ? "null" : string.Join(",", got);
        return g == expected ? null : name + " 기대 [" + expected + "] / 결과 [" + g + "]";
    }

    // 기준 구현: 매번 시트를 위에서부터 훑어, 있는 선행이 모두 끝난 첫 퀘스트를 고른다.
    static string CheckAgainstReference(QuestDef[] quests)
    {
        int n = quests.Length;
        var ids = new System.Collections.Generic.HashSet<string>();
        foreach (var q in quests) ids.Add(q.Id);
        var missing = new System.Collections.Generic.List<string>();
        foreach (var q in quests) foreach (string r in q.Requires) if (!ids.Contains(r)) missing.Add(q.Id + "->" + r);
        var done = new System.Collections.Generic.HashSet<string>();
        var order = new System.Collections.Generic.List<string>();
        while (true)
        {
            int pick = -1;
            for (int i = 0; i < n && pick < 0; i++)
            {
                if (done.Contains(quests[i].Id)) continue;
                bool ok = true;
                foreach (string r in quests[i].Requires) if (ids.Contains(r) && !done.Contains(r)) { ok = false; break; }
                if (ok) pick = i;
            }
            if (pick < 0) break;
            done.Add(quests[pick].Id);
            order.Add(quests[pick].Id);
        }
        var blocked = new System.Collections.Generic.List<string>();
        foreach (var q in quests) if (!done.Contains(q.Id)) blocked.Add(q.Id);
        return Check(quests, string.Join(",", order), string.Join(",", missing), string.Join(",", blocked));
    }

    public static void Main()
    {
        Run("sheet-order-on-ties", () =>
            Check(new[] { Q("intro"), Q("herbs"), Q("wolves"), Q("bandits") }, "intro,herbs,wolves,bandits", "", "")
            ?? Check(new[] { Q("intro"), Q("boss", "wolves", "herbs"), Q("herbs", "intro"), Q("wolves", "intro"), Q("fishing") },
                     "intro,herbs,wolves,boss,fishing", "", "")
            ?? Check(new QuestDef[0], "", "", ""));

        Run("newly-unlocked-goes-before-later-rows", () =>
            // b 가 끝나는 순간 a(1행)가 풀린다. 그때 대기 중이던 c(3행)보다 a 가 먼저여야 한다.
            Check(new[] { Q("a", "b"), Q("b"), Q("c") }, "b,a,c", "", "")
            ?? Check(new[] { Q("a", "d"), Q("b", "a"), Q("c"), Q("d"), Q("e") }, "c,d,a,b,e", "", ""));

        Run("missing-reference-is-reported", () =>
            Check(new[] { Q("intro"), Q("wolves", "intro", "wolvs_prologue"), Q("boss", "wolves") }, "intro,wolves,boss", "wolves->wolvs_prologue", "")
            ?? Check(new[] { Q("a", "x"), Q("b", "y", "a"), Q("c", "x") }, "a,b,c", "a->x,b->y,c->x", "")
            ?? Check(new[] { Q("solo", "nowhere") }, "solo", "solo->nowhere", ""));

        Run("three-quest-cycle-is-blocked", () =>
            Check(new[] { Q("a", "c"), Q("b", "a"), Q("c", "b") }, "", "", "a,b,c")
            ?? Check(new[] { Q("free"), Q("a", "c"), Q("b", "a"), Q("c", "b"), Q("free2", "free") }, "free,free2", "", "a,b,c"));

        Run("quests-behind-a-cycle-are-blocked", () =>
            // x <-> y 가 순환이고, after 는 순환에 속하지 않지만 x 를 기다리므로 영원히 풀리지 않는다.
            Check(new[] { Q("after2", "after"), Q("x", "y"), Q("y", "x"), Q("after", "x"), Q("ok") }, "ok", "", "after2,x,y,after")
            ?? Check(new[] { Q("self", "self"), Q("next", "self"), Q("ok") }, "ok", "", "self,next"));

        Run("pair-cycle-and-duplicate-prerequisite", () =>
            Check(new[] { Q("x", "y", "y"), Q("y", "x") }, "", "", "x,y")
            ?? Check(new[] { Q("b", "a", "a"), Q("a"), Q("c", "b", "a", "b") }, "a,b,c", "", ""));

        Run("missing-and-cycle-together", () =>
            Check(new[] { Q("m", "ghost"), Q("p", "q", "ghost2"), Q("q", "r"), Q("r", "p"), Q("z", "m") }, "m,z", "m->ghost,p->ghost2", "p,q,r"));

        Run("random-vs-reference", () =>
        {
            uint s = 77123u;
            System.Func<int, int> rnd = k => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)k); };
            for (int run = 0; run < 2000; run++)
            {
                int n = 1 + rnd(9);
                var quests = new QuestDef[n];
                for (int i = 0; i < n; i++)
                {
                    var req = new string[rnd(3)];
                    for (int k = 0; k < req.Length; k++)
                    {
                        int kind = run % 3; // 0: 순환·누락 없음, 1: 누락만, 2: 전부 섞임. 없는 id 는 한 퀘스트 안에서 겹치지 않게 만든다
                        if (kind >= 1 && rnd(8) == 0) req[k] = "zz" + rnd(3) + (char)('a' + k);
                        else if (kind == 2 && rnd(4) == 0) req[k] = "q" + rnd(n);
                        else
                        {
                            // 순환이 생기지 않도록 "번호가 더 큰" 퀘스트만 가리킨다. 시트 순서와는 무관하다.
                            int hi = n - 1 - i;
                            req[k] = hi == 0 ? (kind >= 1 ? "zz9" + (char)('a' + k) : null) : "q" + (i + 1 + rnd(hi));
                        }
                    }
                    var list = new System.Collections.Generic.List<string>();
                    foreach (string r in req) if (r != null) list.Add(r);
                    quests[i] = new QuestDef("q" + i, list.ToArray());
                }
                // 시트의 행 순서를 섞는다(피셔-예이츠)
                for (int i = n - 1; i > 0; i--) { int j = rnd(i + 1); var t = quests[i]; quests[i] = quests[j]; quests[j] = t; }
                string e = CheckAgainstReference(quests);
                if (e != null) return "무작위 " + run + "회차. " + e;
            }
            return null;
        });
    }
}

