problems.solutionCode:
using System;
using System.Collections.Generic;

// 타일 단위 정수 사각형. 반열린 구간이다: [MinX, MaxX) x [MinY, MaxY).
// MinX < MaxX, MinY < MaxY 인 사각형만 들어온다고 가정한다.
public readonly struct RectI
{
    public readonly int MinX, MinY, MaxX, MaxY;

    public RectI(int minX, int minY, int maxX, int maxY)
    {
        MinX = minX; MinY = minY; MaxX = maxX; MaxY = maxY;
    }
}

// 맵 로딩 때 한 번 채우고 이후에는 질의만 하는 정적 장애물용 쿼드트리.
public sealed class ObstacleQuadTree
{
    private sealed class Node
    {
        public readonly RectI Region;
        public readonly int Depth;
        public readonly List<int> Items = new List<int>(); // _ids / _bounds 의 인덱스
        public Node[] Children;                            // null 이면 잎

        public Node(RectI region, int depth)
        {
            Region = region;
            Depth = depth;
        }
    }

    private readonly Node _root;
    private readonly int _capacity;
    private readonly int _maxDepth;
    private readonly List<int> _ids = new List<int>();
    private readonly List<RectI> _bounds = new List<RectI>();

    public ObstacleQuadTree(int originX, int originY, int size, int capacity, int maxDepth)
    {
        _root = new Node(new RectI(originX, originY, originX + size, originY + size), 0);
        _capacity = capacity;
        _maxDepth = maxDepth;
        NodeCount = 1;
    }

    public int NodeCount { get; private set; }

    public int Depth { get; private set; }

    public void Insert(int id, RectI bounds)
    {
        int item = _ids.Count;
        _ids.Add(id);
        _bounds.Add(bounds);

        // 장애물이 한 자식 안에 통째로 들어가는 동안만 내려간다.
        // 분할선에 걸쳤거나 루트 밖으로 삐져나온 장애물은 그 자리(부모)에 남는다.
        Node node = _root;
        while (node.Children != null)
        {
            Node child = ChildContaining(node, bounds);
            if (child == null) break;
            node = child;
        }

        node.Items.Add(item);
        if (node.Children == null && node.Items.Count > _capacity && node.Depth < _maxDepth)
            Subdivide(node);
    }

    public int Query(RectI area, List<int> results)
    {
        results.Clear();
        Collect(_root, area, results); // 루트는 영역 검사 없이 들어간다: 루트 밖으로 삐져나온 장애물이 루트에 있다
        return results.Count;
    }

    private void Collect(Node node, in RectI area, List<int> results)
    {
        List<int> items = node.Items;
        for (int i = 0; i < items.Count; i++)
        {
            int item = items[i];
            if (Overlaps(_bounds[item], area)) results.Add(_ids[item]);
        }

        Node[] children = node.Children;
        if (children == null) return;
        for (int c = 0; c < 4; c++)
            if (Overlaps(children[c].Region, area)) Collect(children[c], area, results); // 겹치지 않는 가지는 통째로 건너뛴다
    }

    private void Subdivide(Node node)
    {
        RectI r = node.Region;
        int midX = r.MinX + (r.MaxX - r.MinX) / 2;
        int midY = r.MinY + (r.MaxY - r.MinY) / 2;
        int depth = node.Depth + 1;
        node.Children = new[]
        {
            new Node(new RectI(r.MinX, r.MinY, midX, midY), depth),
            new Node(new RectI(midX, r.MinY, r.MaxX, midY), depth),
            new Node(new RectI(r.MinX, midY, midX, r.MaxY), depth),
            new Node(new RectI(midX, midY, r.MaxX, r.MaxY), depth),
        };
        NodeCount += 4;
        if (depth > Depth) Depth = depth;

        // 한 자식 안에 통째로 들어가는 장애물만 내려보내고 나머지는 이 노드에 남긴다.
        List<int> items = node.Items;
        int kept = 0;
        for (int i = 0; i < items.Count; i++)
        {
            Node child = ChildContaining(node, _bounds[items[i]]);
            if (child == null) items[kept++] = items[i];
            else child.Items.Add(items[i]);
        }
        items.RemoveRange(kept, items.Count - kept);

        // 내려간 장애물이 한 자식에 몰렸으면 그 자식도 넘친다. 깊이 제한이 재귀를 끝낸다.
        for (int c = 0; c < 4; c++)
        {
            Node child = node.Children[c];
            if (child.Items.Count > _capacity && child.Depth < _maxDepth) Subdivide(child);
        }
    }

    private static Node ChildContaining(Node node, in RectI b)
    {
        Node[] children = node.Children;
        for (int c = 0; c < 4; c++)
            if (Contains(children[c].Region, b)) return children[c];
        return null;
    }

    // 반열린 구간끼리의 겹침: 변만 맞닿은 사각형은 겹치지 않는다.
    private static bool Overlaps(in RectI a, in RectI b)
    {
        return a.MinX < b.MaxX && b.MinX < a.MaxX && a.MinY < b.MaxY && b.MinY < a.MaxY;
    }

    private static bool Contains(in RectI outer, in RectI inner)
    {
        return outer.MinX <= inner.MinX && inner.MaxX <= outer.MaxX
            && outer.MinY <= inner.MinY && inner.MaxY <= outer.MaxY;
    }
}

