public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static RectI R(int minX, int minY, int maxX, int maxY) { return new RectI(minX, minY, maxX, maxY); }

    static string Str(RectI r) { return "[" + r.MinX + "," + r.MaxX + ")x[" + r.MinY + "," + r.MaxY + ")"; }

    // 트리와, 같은 장애물을 그대로 적어 둔 목록(전수 검사용)을 함께 들고 다닌다.
    sealed class World
    {
        public readonly ObstacleQuadTree T;
        public readonly int MaxDepth;
        readonly System.Collections.Generic.List<RectI> _rects = new System.Collections.Generic.List<RectI>();
        readonly System.Collections.Generic.List<int> _ids = new System.Collections.Generic.List<int>();
        public readonly System.Collections.Generic.List<int> Buf = new System.Collections.Generic.List<int>(4096);

        public World(int ox, int oy, int size, int capacity, int maxDepth)
        {
            T = new ObstacleQuadTree(ox, oy, size, capacity, maxDepth);
            MaxDepth = maxDepth;
        }

        public void Add(int id, RectI r) { T.Insert(id, r); _ids.Add(id); _rects.Add(r); }

        // 전수 검사와 비교한다. 같으면 null.
        public string Query(RectI a)
        {
            Buf.Add(-12345); // 이전 내용이 남아 있으면 안 된다
            int n = T.Query(a, Buf);
            if (n != Buf.Count) return "질의 " + Str(a) + ": 반환값(" + n + ")과 results.Count(" + Buf.Count + ")가 다름";
            var exp = new System.Collections.Generic.List<int>();
            for (int i = 0; i < _rects.Count; i++)
            {
                RectI r = _rects[i];
                if (r.MinX < a.MaxX && a.MinX < r.MaxX && r.MinY < a.MaxY && a.MinY < r.MaxY) exp.Add(_ids[i]);
            }
            exp.Sort();
            Buf.Sort();
            for (int i = 1; i < Buf.Count; i++)
                if (Buf[i] == Buf[i - 1]) return "질의 " + Str(a) + ": id " + Buf[i] + " 가 결과에 두 번 들어 있음";
            bool same = exp.Count == Buf.Count;
            for (int i = 0; same && i < exp.Count; i++) same = exp[i] == Buf[i];
            if (same) return null;
            string es = string.Join(",", exp), gs = string.Join(",", Buf);
            if (es.Length > 70) es = es.Substring(0, 70) + "...";
            if (gs.Length > 70) gs = gs.Substring(0, 70) + "...";
            return "질의 " + Str(a) + ": 기대 [" + es + "] (" + exp.Count + "개) / 결과 [" + gs + "] (" + Buf.Count + "개)";
        }

        public string Shape()
        {
            int nodes = T.NodeCount, depth = T.Depth;
            if (depth < 0 || depth > MaxDepth) return "Depth 가 " + depth + " (maxDepth " + MaxDepth + " 를 넘으면 안 됨)";
            if (nodes < 1 || (nodes - 1) % 4 != 0) return "NodeCount 가 " + nodes + " (노드는 한 번에 4개씩 늘어나므로 1 + 4k 여야 함)";
            if ((depth == 0) != (nodes == 1)) return "NodeCount " + nodes + " 와 Depth " + depth + " 가 서로 맞지 않음";
            return null;
        }
    }

    public static void Main()
    {
        Run("half-open-overlap", () =>
        {
            var w = new World(0, 0, 64, 4, 4);
            string e = w.Query(R(0, 0, 64, 64)) ?? w.Shape();
            if (e != null) return "빈 트리: " + e;
            if (w.T.NodeCount != 1 || w.T.Depth != 0) return "빈 트리의 NodeCount / Depth 기대 1 / 0, 결과 " + w.T.NodeCount + " / " + w.T.Depth;
            w.Add(7, R(40, 42, 44, 44));
            e = w.Query(R(0, 0, 64, 64)) ?? w.Query(R(42, 43, 43, 44)) ?? w.Query(R(2, 2, 9, 9)) ?? w.Query(R(39, 41, 45, 45));
            if (e != null) return e;
            w.Add(1, R(10, 10, 20, 20));
            e = w.Query(R(20, 10, 30, 20)) ?? w.Query(R(0, 10, 10, 20)) ?? w.Query(R(10, 20, 20, 30)) ?? w.Query(R(10, 0, 20, 10));
            if (e != null) return "변만 맞닿은 사각형은 겹치지 않아야 함(반열린 구간). " + e;
            return w.Query(R(19, 19, 20, 20)) ?? w.Query(R(10, 10, 11, 11)) ?? w.Query(R(19, 10, 25, 11)) ?? w.Query(R(0, 0, 64, 64)) ?? w.Query(R(12, 12, 13, 13));
        });

        Run("split-at-capacity", () =>
        {
            var w = new World(0, 0, 64, 4, 4);
            w.Add(0, R(5, 5, 6, 6)); w.Add(1, R(40, 5, 41, 6)); w.Add(2, R(5, 40, 6, 41)); w.Add(3, R(40, 40, 41, 41));
            if (w.T.NodeCount != 1 || w.T.Depth != 0)
                return "capacity 4 에 4개를 넣은 상태: NodeCount / Depth 기대 1 / 0, 결과 " + w.T.NodeCount + " / " + w.T.Depth + " (capacity 를 '넘을' 때 쪼갠다)";
            w.Add(4, R(20, 20, 21, 21));
            if (w.T.NodeCount != 5 || w.T.Depth != 1)
                return "5번째를 넣은 뒤: NodeCount / Depth 기대 5 / 1, 결과 " + w.T.NodeCount + " / " + w.T.Depth;
            string e = w.Query(R(0, 0, 64, 64)) ?? w.Query(R(0, 0, 32, 32)) ?? w.Query(R(32, 0, 64, 32)) ?? w.Query(R(0, 32, 32, 64))
                ?? w.Query(R(32, 32, 64, 64)) ?? w.Query(R(5, 5, 6, 6)) ?? w.Query(R(20, 20, 41, 41));
            return e == null ? null : "쪼갠 뒤 질의가 틀림(기존 장애물을 자식으로 옮기다 잃어버렸는지 확인). " + e;
        });

        Run("straddling-split-lines", () =>
        {
            var w = new World(0, 0, 64, 2, 4);
            // 0~3: 한 사분면에 통째로 들어간다. 10~14: 루트의 분할선(x = 32 또는 y = 32)에 걸친다.
            w.Add(0, R(2, 2, 4, 4)); w.Add(1, R(50, 3, 52, 6)); w.Add(2, R(3, 50, 6, 52)); w.Add(3, R(50, 50, 53, 53));
            w.Add(10, R(30, 30, 34, 34)); w.Add(11, R(31, 2, 33, 4)); w.Add(12, R(2, 31, 4, 33)); w.Add(13, R(0, 0, 64, 64)); w.Add(14, R(16, 31, 48, 32 + 1));
            w.Add(5, R(8, 8, 9, 9)); w.Add(6, R(9, 9, 10, 10)); w.Add(7, R(15, 15, 17, 17)); // 더 깊은 분할선(x = 16, y = 16)에 걸친다
            string e = w.Shape();
            if (e != null) return e;
            e = w.Query(R(0, 0, 32, 32)) ?? w.Query(R(32, 0, 64, 32)) ?? w.Query(R(0, 32, 32, 64)) ?? w.Query(R(32, 32, 64, 64))
                ?? w.Query(R(33, 33, 34, 34)) ?? w.Query(R(30, 30, 31, 31)) ?? w.Query(R(32, 2, 33, 3)) ?? w.Query(R(60, 60, 61, 61))
                ?? w.Query(R(16, 16, 17, 17)) ?? w.Query(R(15, 15, 16, 16)) ?? w.Query(R(40, 31, 41, 32)) ?? w.Query(R(0, 0, 64, 64));
            return e == null ? null : "분할선에 걸친 장애물은 어느 쪽 사분면에서 질의해도 한 번씩 나와야 함. " + e;
        });

        Run("max-depth-limit", () =>
        {
            var w = new World(0, 0, 64, 2, 0); // maxDepth 0: 절대 쪼개지 않는다
            for (int i = 0; i < 40; i++) w.Add(i, R(i, 63 - i, i + 1, 64 - i));
            if (w.T.NodeCount != 1 || w.T.Depth != 0) return "maxDepth 0 인데 NodeCount / Depth 가 " + w.T.NodeCount + " / " + w.T.Depth;
            string e = w.Query(R(0, 0, 64, 64)) ?? w.Query(R(10, 50, 12, 54)) ?? w.Query(R(0, 0, 5, 5));
            if (e != null) return e;
            var w2 = new World(-32, -32, 64, 1, 2);
            for (int i = 0; i < 30; i++) w2.Add(i, R(-32 + i, -32 + i, -31 + i, -31 + i));
            e = w2.Shape();
            if (e != null) return e;
            if (w2.T.Depth != 2) return "capacity 1, maxDepth 2 에 대각선으로 30개: Depth 기대 2 / 결과 " + w2.T.Depth;
            return w2.Query(R(-32, -32, 32, 32)) ?? w2.Query(R(-32, -32, -16, -16)) ?? w2.Query(R(-5, -5, 5, 5)) ?? w2.Query(R(-3, -3, -2, -2));
        });

        Run("negative-coords-and-outside-world", () =>
        {
            var w = new World(-64, -64, 128, 2, 5);
            w.Add(1, R(-60, -60, -58, -58)); w.Add(2, R(-1, -1, 1, 1)); w.Add(3, R(-33, -10, -31, -8)); w.Add(4, R(10, -40, 12, -38));
            w.Add(5, R(-17, -17, -15, -15)); w.Add(6, R(40, 40, 42, 42)); w.Add(7, R(-50, 20, -48, 22));
            w.Add(20, R(60, 0, 70, 4));       // 오른쪽으로 삐져나옴
            w.Add(21, R(100, 100, 110, 110)); // 통째로 월드 밖
            w.Add(22, R(-200, -70, -190, -60));
            w.Add(23, R(-80, -80, 80, 80));   // 월드 전체보다 큼
            string e = w.Shape()
                ?? w.Query(R(-64, -64, 64, 64)) ?? w.Query(R(-64, -64, 0, 0)) ?? w.Query(R(-2, -2, 2, 2)) ?? w.Query(R(-32, -9, -31, -8))
                ?? w.Query(R(62, 1, 63, 2));
            if (e != null) return e;
            e = w.Query(R(66, 1, 68, 3)) ?? w.Query(R(105, 105, 106, 106)) ?? w.Query(R(-300, -300, -150, 300)) ?? w.Query(R(-1000, -1000, 1000, 1000))
                ?? w.Query(R(70, 70, 79, 79)) ?? w.Query(R(200, 200, 300, 300));
            return e == null ? null : "월드 밖에 있거나 밖으로 삐져나온 장애물도 질의에 잡혀야 함. " + e;
        });

        Run("no-alloc-query", () =>
        {
            var w = new World(0, 0, 1024, 8, 6);
            uint s = 99u;
            System.Func<int, int> rnd = k => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)k); };
            for (int i = 0; i < 3000; i++) { int x = rnd(1000), y = rnd(1000); w.Add(i, R(x, y, x + 1 + rnd(20), y + 1 + rnd(20))); }
            var buf = new System.Collections.Generic.List<int>(4096);
            for (int i = 0; i < 300; i++) w.T.Query(R(i * 3, i * 2, i * 3 + 40, i * 2 + 40), buf);
            w.T.Query(R(0, 0, 1024, 1024), buf);
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            for (int i = 0; i < 2000; i++) w.T.Query(R((i * 7) % 900, (i * 13) % 900, (i * 7) % 900 + 60, (i * 13) % 900 + 60), buf);
            long bytes = System.GC.GetAllocatedBytesForCurrentThread() - before;
            return bytes == 0 ? null : "Query 2000회 동안 " + bytes + "바이트 할당됨 (질의 중 할당 금지)";
        });

        Run("random-vs-bruteforce", () =>
        {
            uint s = 4711u;
            System.Func<int, int> rnd = k => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)k); };
            int[] caps = { 1, 2, 4, 8 };
            for (int run = 0; run < 60; run++)
            {
                int size = 16 << rnd(4); // 16, 32, 64, 128
                int maxDepth = rnd(5);   // size >> maxDepth >= 1
                int ox = rnd(3) == 0 ? 0 : -rnd(size), oy = rnd(3) == 0 ? 0 : -rnd(size);
                var w = new World(ox, oy, size, caps[rnd(4)], maxDepth);
                int count = 1 + rnd(120);
                for (int i = 0; i < count; i++)
                {
                    int kind = rnd(10);
                    int wd = kind < 6 ? 1 + rnd(3) : kind < 9 ? 1 + rnd(size / 2) : 1 + rnd(size * 2);
                    int ht = kind < 6 ? 1 + rnd(3) : kind < 9 ? 1 + rnd(size / 2) : 1 + rnd(size * 2);
                    int x = ox - 8 + rnd(size + 16), y = oy - 8 + rnd(size + 16);
                    if (run % 4 == 0) { x = ox + rnd(4); y = oy + rnd(4); } // 한 구석에 몰린 맵
                    w.Add(1000 + i, R(x, y, x + wd, y + ht));
                    if (i % 7 != 0) continue;
                    string e = w.Shape();
                    for (int q = 0; e == null && q < 6; q++)
                    {
                        int qx = ox - 10 + rnd(size + 20), qy = oy - 10 + rnd(size + 20);
                        e = w.Query(R(qx, qy, qx + 1 + rnd(q < 3 ? 4 : size), qy + 1 + rnd(q < 3 ? 4 : size)));
                    }
                    if (e != null) return "무작위 " + run + "회차(size " + size + ", maxDepth " + maxDepth + "), " + (i + 1) + "개 삽입 후: " + e;
                }
            }
            return null;
        });

        // 같은 칸에 장애물이 계속 쌓여도 끝없이 쪼개지면 안 된다. (무한 분할은 프로세스를 죽이므로 맨 마지막에 둔다)
        Run("same-tile-pileup", () =>
        {
            var w = new World(0, 0, 64, 4, 6);
            for (int i = 0; i < 300; i++) w.Add(i, R(5, 5, 6, 6));
            string e = w.Shape();
            if (e != null) return e;
            if (w.T.Depth < 1) return "같은 칸에 300개(capacity 4): 한 번도 쪼개지지 않음";
            if (w.T.NodeCount > 1 + 4 * 6) return "같은 칸에 300개: NodeCount " + w.T.NodeCount + " (한 갈래만 깊어지므로 1 + 4 x maxDepth = 25 이하여야 함)";
            e = w.Query(R(5, 5, 6, 6)) ?? w.Query(R(0, 0, 64, 64)) ?? w.Query(R(6, 5, 7, 6)) ?? w.Query(R(4, 4, 5, 5));
            return e;
        });
    }
}

