using System;

// 새 상태와 새 이벤트는 맨 뒤에 붙인다: 기존 이름의 정수 값이 바뀌지 않는다.
public enum EnemyState { Patrol, Chase, Attack, Stunned }

public enum EnemyEvent { PlayerSeen, PlayerLost, InRange, OutOfRange, Stun, StunEnd }

// 전이 표로 동작하는 상태 기계. 표의 한 칸 = "이 상태에서 이 이벤트가 오면 갈 다음 상태".
public sealed class EnemyFsm
{
    private const int NoTransition = -1;

    // _next[상태, 이벤트] = 다음 상태(int 로 저장), 없으면 NoTransition
    private readonly int[,] _next;

    public EnemyState Current { get; private set; }

    public EnemyFsm(EnemyState initial)
    {
        int states = Enum.GetValues(typeof(EnemyState)).Length;
        int events = Enum.GetValues(typeof(EnemyEvent)).Length;
        _next = new int[states, events];
        for (int s = 0; s < states; s++)
            for (int e = 0; e < events; e++)
                _next[s, e] = NoTransition;
        Current = initial;
    }

    public void AddTransition(EnemyState from, EnemyEvent on, EnemyState to)
    {
        // 한 칸에 다음 상태는 하나뿐이다. 조용히 덮어쓰면 표를 잘못 적은 것을 아무도 모른다.
        if (_next[(int)from, (int)on] != NoTransition)
            throw new InvalidOperationException("전이가 이미 있습니다: " + from + " + " + on);
        _next[(int)from, (int)on] = (int)to;
    }

    public bool Fire(EnemyEvent e)
    {
        int next = _next[(int)Current, (int)e];
        if (next == NoTransition) return false; // 표에 없는 조합은 무시한다
        Current = (EnemyState)next;
        return true;
    }
}

public static class GuardAi
{
    // 경비병 AI 의 전이 표. 기획서의 표를 한 줄씩 옮겨 적은 것이다.
    public static EnemyFsm Build()
    {
        var fsm = new EnemyFsm(EnemyState.Patrol);
        fsm.AddTransition(EnemyState.Patrol, EnemyEvent.PlayerSeen, EnemyState.Chase);
        fsm.AddTransition(EnemyState.Chase, EnemyEvent.PlayerLost, EnemyState.Patrol);
        fsm.AddTransition(EnemyState.Chase, EnemyEvent.InRange, EnemyState.Attack);
        fsm.AddTransition(EnemyState.Attack, EnemyEvent.OutOfRange, EnemyState.Chase);
        fsm.AddTransition(EnemyState.Attack, EnemyEvent.PlayerLost, EnemyState.Patrol);

        // 연습 2: 어느 상태에서든 Stun 이 오면 Stunned 로 간다. 기존 줄은 그대로 두고 줄만 더한다.
        foreach (EnemyState s in Enum.GetValues(typeof(EnemyState)))
            if (s != EnemyState.Stunned) fsm.AddTransition(s, EnemyEvent.Stun, EnemyState.Stunned);
        fsm.AddTransition(EnemyState.Stunned, EnemyEvent.StunEnd, EnemyState.Patrol);

        return fsm;
    }
}

