problems.solutionCode:
using System;
using System.Collections.Generic;

// 아케이드 랭킹 보드: 가장 좋은 기록 K 개만 남긴다.
// 점수가 높을수록 순위가 높고, 점수가 같으면 먼저 제출한 기록이 높다.
public sealed class Leaderboard
{
    private readonly int _k;

    // 최소 힙. 루트는 "보드에서 가장 약한 기록", 곧 커트라인이다.
    // 우선순위 (score, -seq): 점수가 낮을수록, 점수가 같으면 늦게 제출한 기록일수록 약하다.
    private readonly PriorityQueue<string, (int score, long negSeq)> _heap;
    private long _nextSeq; // 제출 순번. 동점일 때 누가 먼저였는지 가린다.

    public Leaderboard(int k)
    {
        _k = k;
        _heap = new PriorityQueue<string, (int score, long negSeq)>(k);
    }

    public bool Submit(string player, int score)
    {
        var entry = (score, negSeq: -_nextSeq);
        _nextSeq++;

        if (_heap.Count < _k)
        {
            _heap.Enqueue(player, entry);
            return true;
        }

        // 가득 찼다면 커트라인(루트)과만 비교한다.
        _heap.TryPeek(out _, out var weakest);
        // 새 기록은 언제나 가장 늦은 제출이므로, 점수가 같으면 커트라인을 넘지 못한다.
        if (score <= weakest.score) return false;

        _heap.Dequeue();              // 가장 약한 기록을 밀어내고
        _heap.Enqueue(player, entry); // 새 기록을 넣는다
        return true;
    }

    public List<(string player, int score)> GetTop()
    {
        // 힙의 내부 배열 순서는 순위가 아니다. K 개를 복사해 순위 기준으로 정렬한다.
        var items = new List<(string player, int score, long negSeq)>(_heap.Count);
        foreach (var (element, priority) in _heap.UnorderedItems)
            items.Add((element, priority.score, priority.negSeq));

        items.Sort((a, b) =>
        {
            int byScore = b.score.CompareTo(a.score);                     // 점수 높은 순
            return byScore != 0 ? byScore : b.negSeq.CompareTo(a.negSeq); // 같으면 먼저 제출한 순
        });

        var top = new List<(string player, int score)>(items.Count);
        foreach (var it in items) top.Add((it.player, it.score));
        return top;
    }

    public int RankOf(string player)
    {
        var top = GetTop();
        for (int i = 0; i < top.Count; i++)
            if (top[i].player == player) return i + 1; // 1위부터 훑으므로 처음 만난 것이 가장 높은 순위
        return 0;
    }
}

