public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 보드를 "kim:90 lee:80" 형태로 만든다.
    static string Dump(System.Collections.Generic.List<(string player, int score)> top)
    {
        if (top == null) return "(null)";
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < top.Count; i++) { if (i > 0) sb.Append(' '); sb.Append(top[i].player).Append(':').Append(top[i].score); }
        return sb.ToString();
    }

    static string Top(Leaderboard b, string expected, string when)
    {
        string got = Dump(b.GetTop());
        return got == expected ? null : when + ": GetTop 기대 [" + expected + "] / 결과 [" + got + "]";
    }

    static string Sub(Leaderboard b, string player, int score, bool expected)
    {
        bool got = b.Submit(player, score);
        return got == expected ? null : "Submit(" + player + "," + score + ") 반환값 기대 " + expected + " / 결과 " + got;
    }

    static string Rank(Leaderboard b, string player, int expected, string when)
    {
        int got = b.RankOf(player);
        return got == expected ? null : when + ": RankOf(" + player + ") 기대 " + expected + " / 결과 " + got;
    }

    // 기준 구현: 모든 제출을 (점수 내림차순, 제출 순번 오름차순)으로 세운 뒤 앞의 k 개.
    static System.Collections.Generic.List<(string player, int score, int seq)> RefTop(System.Collections.Generic.List<(string player, int score, int seq)> all, int k)
    {
        var copy = new System.Collections.Generic.List<(string player, int score, int seq)>(all);
        copy.Sort((a, c) => a.score != c.score ? c.score.CompareTo(a.score) : a.seq.CompareTo(c.seq));
        if (copy.Count > k) copy.RemoveRange(k, copy.Count - k);
        return copy;
    }

    static string Join(System.Collections.Generic.List<(string player, int score, int seq)> want)
    {
        var sb = new System.Text.StringBuilder();
        for (int j = 0; j < want.Count; j++) { if (j > 0) sb.Append(' '); sb.Append(want[j].player).Append(':').Append(want[j].score); }
        return sb.ToString();
    }

    static int RankIn(System.Collections.Generic.List<(string player, int score, int seq)> want, string player)
    {
        for (int j = 0; j < want.Count; j++) if (want[j].player == player) return j + 1;
        return 0;
    }

    public static void Main()
    {
        Run("keeps-best-k", () =>
        {
            var b = new Leaderboard(3);
            return Top(b, "", "빈 보드") ?? Rank(b, "ann", 0, "빈 보드")
                ?? Sub(b, "ann", 100, true) ?? Sub(b, "bob", 300, true) ?? Sub(b, "cat", 200, true)
                ?? Top(b, "bob:300 cat:200 ann:100", "3건 제출 후")
                ?? Sub(b, "dan", 250, true) ?? Top(b, "bob:300 dan:250 cat:200", "dan 250 제출 후")
                ?? Sub(b, "eve", 150, false) ?? Top(b, "bob:300 dan:250 cat:200", "eve 150 제출 후")
                ?? Sub(b, "fay", 999, true) ?? Top(b, "fay:999 bob:300 dan:250", "fay 999 제출 후");
        });

        Run("fewer-than-k-and-k-one", () =>
        {
            var b = new Leaderboard(5);
            string e = Sub(b, "ann", -5, true) ?? Sub(b, "bob", 0, true) ?? Top(b, "bob:0 ann:-5", "5칸 보드에 2건")
                ?? Rank(b, "ann", 2, "5칸 보드에 2건");
            if (e != null) return e;
            var one = new Leaderboard(1);
            return Sub(one, "ann", 10, true) ?? Sub(one, "bob", 5, false) ?? Sub(one, "cat", 10, false) ?? Top(one, "ann:10", "1칸 보드")
                ?? Sub(one, "dan", 11, true) ?? Top(one, "dan:11", "1칸 보드에 dan 11") ?? Rank(one, "ann", 0, "밀려난 뒤");
        });

        Run("equal-scores-earlier-first", () =>
        {
            var b = new Leaderboard(4);
            return Sub(b, "ann", 100, true) ?? Sub(b, "bob", 200, true) ?? Sub(b, "cat", 100, true) ?? Sub(b, "dan", 200, true)
                ?? Top(b, "bob:200 dan:200 ann:100 cat:100", "동점 두 쌍")
                ?? Rank(b, "dan", 2, "동점 두 쌍") ?? Rank(b, "cat", 4, "동점 두 쌍");
        });

        Run("tie-at-cut-line", () =>
        {
            var b = new Leaderboard(2);
