            string[] names = { "ann", "bob", "cat", "dan", "eve", "fay" };
            for (int run = 0; run < 300; run++)
            {
                int k = 1 + rnd(6), range = 2 + rnd(8);
                var b = new Leaderboard(k);
                var all = new System.Collections.Generic.List<(string player, int score, int seq)>();
                for (int i = 0; i < 40; i++)
                {
                    string p = names[rnd(names.Length)]; int sc = rnd(range) * 10;
                    all.Add((p, sc, i));
                    var want = RefTop(all, k);
                    bool entered = false;
                    foreach (var w in want) if (w.seq == i) entered = true;
                    bool got = b.Submit(p, sc);
                    string when = "무작위 " + run + "회차(k=" + k + ") " + (i + 1) + "번째 제출 " + p + ":" + sc;
                    if (got != entered) return when + " 반환값 기대 " + entered + " / 결과 " + got;
                    string e = Top(b, Join(want), when + " 후");
                    if (e != null) return e;
                    foreach (string name in names)
                    {
                        e = Rank(b, name, RankIn(want, name), when + " 후");
                        if (e != null) return e;
                    }
                }
            }
            return null;
        });

        Run("long-stream", () =>
        {
            uint s = 77u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            const int k = 50, n = 100000;
            var b = new Leaderboard(k);
            var all = new System.Collections.Generic.List<(string player, int score, int seq)>(n);
            for (int i = 0; i < n; i++)
            {
                string p = "p" + rnd(500); int sc = rnd(3000);
                all.Add((p, sc, i));
                b.Submit(p, sc);
            }
            var want = RefTop(all, k);
            var got = b.GetTop();
            if (Dump(got) != Join(want)) return "제출 10만 건(k=50) 뒤의 GetTop 이 기준 구현과 다름: 개수 기대 " + want.Count + " / 결과 " + (got == null ? 0 : got.Count) + ", 1위 기대 " + want[0].player + ":" + want[0].score + " / 결과 " + (got != null && got.Count > 0 ? got[0].player + ":" + got[0].score : "(없음)");
            return Rank(b, want[k - 1].player, RankIn(want, want[k - 1].player), "제출 10만 건 뒤");
        });
    }
}

