using System;
using System.Collections.Generic;

// 버프 만료 스케줄러. 시간은 정수 틱이고, 한 유닛은 같은 종류의 버프를 하나만 가진다.
public sealed class BuffScheduler
{
    // 만료 시각이 가장 이른 타이머가 먼저 나온다.
    // 만료 시각이 같으면 유닛 번호, 버프 번호 순으로 꺼내 실행할 때마다 순서가 같게 한다.
    private readonly PriorityQueue<(int unit, int buff), (long at, int unit, int buff)> _timers
        = new PriorityQueue<(int unit, int buff), (long at, int unit, int buff)>();

    // 지금 걸려 있는 버프와 그 만료 시각
    private readonly Dictionary<(int unit, int buff), long> _expireAt = new Dictionary<(int unit, int buff), long>();

    // 해제된 버프. 큐에 남은 타이머를 건너뛰는 데 쓴다.
    private readonly HashSet<(int unit, int buff)> _cancelled = new HashSet<(int unit, int buff)>();

    public int ActiveCount => _expireAt.Count;

    public bool IsActive(int unit, int buff) => _expireAt.ContainsKey((unit, buff));

    // 버프를 건다. 이미 걸려 있으면 갱신한다: 만료 시각이 now + duration 으로 바뀐다. duration 은 1 이상.
    public void Apply(int unit, int buff, long now, long duration)
    {
        var key = (unit, buff);
        long expireAt = now + duration;
        _expireAt[key] = expireAt;
        _timers.Enqueue(key, (expireAt, unit, buff));
    }

    // 버프를 해제한다. 걸려 있었으면 true. 해제된 버프는 만료 이벤트를 내지 않는다.
    public bool Cancel(int unit, int buff)
    {
        var key = (unit, buff);
        if (!_expireAt.Remove(key)) return false;
        _cancelled.Add(key);
        return true;
    }

    // 만료 시각이 now 이하인 버프를 모두 끝내고, 끝난 순서대로 expired 에 추가한다.
    public void Advance(long now, List<(int unit, int buff)> expired)
    {
        while (_timers.TryPeek(out var key, out var due) && due.at <= now)
        {
            _timers.Dequeue();
            if (_cancelled.Contains(key)) continue; // 해제된 버프의 타이머는 버린다
            if (_expireAt.Remove(key)) expired.Add(key);
        }
    }
}

problems.solutionCode:
using System;
using System.Collections.Generic;

// 버프 만료 스케줄러. 시간은 정수 틱이고, 한 유닛은 같은 종류의 버프를 하나만 가진다.
public sealed class BuffScheduler
{
    // 큐의 원소는 "어느 버프의 몇 번째 타이머인가"(stamp)까지 들고 있다.
    // 우선순위는 (만료 시각, stamp): 만료 시각이 같으면 먼저 건 타이머가 먼저 나온다.
    private readonly PriorityQueue<((int unit, int buff) key, long stamp), (long at, long stamp)> _timers
        = new PriorityQueue<((int unit, int buff) key, long stamp), (long at, long stamp)>();

    // 지금 걸려 있는 버프 -> 그 버프의 "유효한 타이머"의 stamp.
    // 큐에서 꺼낸 타이머의 stamp 가 이 값과 다르면 갱신되거나 해제되어 낡은 타이머다.
    private readonly Dictionary<(int unit, int buff), long> _liveStamp = new Dictionary<(int unit, int buff), long>();

    private long _nextStamp; // Apply 가 불릴 때마다 1 씩 증가한다

    public int ActiveCount => _liveStamp.Count;

    public bool IsActive(int unit, int buff) => _liveStamp.ContainsKey((unit, buff));

    // 버프를 건다. 이미 걸려 있으면 갱신한다: 만료 시각이 now + duration 으로 바뀐다. duration 은 1 이상.
    public void Apply(int unit, int buff, long now, long duration)
    {
        var key = (unit, buff);
        long stamp = _nextStamp++;
        _liveStamp[key] = stamp;                             // 이전 타이머는 이 순간 낡은 것이 된다
        _timers.Enqueue((key, stamp), (now + duration, stamp));
    }

    // 버프를 해제한다. 걸려 있었으면 true. 해제된 버프는 만료 이벤트를 내지 않는다.
    public bool Cancel(int unit, int buff)
    {
        // 큐는 건드리지 않는다. 남은 타이머는 꺼낼 때 stamp 가 맞지 않아 버려진다.
        return _liveStamp.Remove((unit, buff));
    }

    // 만료 시각이 now 이하인 버프를 모두 끝내고, 끝난 순서대로 expired 에 추가한다.
    public void Advance(long now, List<(int unit, int buff)> expired)
    {
        while (_timers.TryPeek(out var timer, out var priority) && priority.at <= now)
        {
            _timers.Dequeue();
            // 이 타이머가 그 버프의 "현재" 타이머일 때만 만료시킨다.
            if (_liveStamp.TryGetValue(timer.key, out long live) && live == timer.stamp)
            {
                _liveStamp.Remove(timer.key);
                expired.Add(timer.key);
            }
        }
    }
}

