public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Dump(System.Collections.Generic.List<(int unit, int buff)> list)
    {
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < list.Count; i++) { if (i > 0) sb.Append(' '); sb.Append('u').Append(list[i].unit).Append('b').Append(list[i].buff); }
        return sb.ToString();
    }

    // Advance(now) 가 낸 만료 이벤트를 "u1b7 u2b7" 형태의 기대값과 비교한다.
    static string Adv(BuffScheduler s, long now, string expected)
    {
        var list = new System.Collections.Generic.List<(int unit, int buff)>();
        s.Advance(now, list);
        string got = Dump(list);
        return got == expected ? null : "Advance(" + now + ") 만료 기대 [" + expected + "] / 결과 [" + got + "]";
    }

    static string Active(BuffScheduler s, int unit, int buff, bool expected, string when)
    {
        bool got = s.IsActive(unit, buff);
        return got == expected ? null : when + ": IsActive(" + unit + "," + buff + ") 기대 " + expected + " / 결과 " + got;
    }

    static string Count(BuffScheduler s, int expected, string when)
    {
        int got = s.ActiveCount;
        return got == expected ? null : when + ": ActiveCount 기대 " + expected + " / 결과 " + got;
    }

    static string Can(BuffScheduler s, int unit, int buff, bool expected, string when)
    {
        bool got = s.Cancel(unit, buff);
        return got == expected ? null : when + ": Cancel(" + unit + "," + buff + ") 반환값 기대 " + expected + " / 결과 " + got;
    }

    public static void Main()
