            return Count(s, 0, "10틱") ?? Adv(s, 50, "");
        });

        Run("cancel-fires-no-event", () =>
        {
            var s = new BuffScheduler();
            s.Apply(1, 7, 0, 10);
            s.Apply(2, 7, 0, 10);
            return Can(s, 9, 9, false, "건 적 없는 버프")
