                ?? Can(s, 1, 7, false, "이미 해제한 버프")
                ?? Adv(s, 10, "u2b7") ?? Adv(s, 20, "") ?? Can(s, 2, 7, false, "이미 만료된 버프");
        });

        Run("cancel-then-apply-again", () =>
        {
            var s = new BuffScheduler();
            s.Apply(1, 7, 0, 10);            // 10 에 만료 예정
            string e = Adv(s, 5, "") ?? Can(s, 1, 7, true, "5틱에 해제") ?? Adv(s, 6, "");
            if (e != null) return e;
            s.Apply(1, 7, 6, 10);            // 다시 건다: 16 에 만료
            return Active(s, 1, 7, true, "해제 후 다시 건 직후")
                ?? Adv(s, 10, "") ?? Active(s, 1, 7, true, "5틱에 해제하고 6틱에 다시 건 버프(10틱 지속)의 10틱")
                ?? Adv(s, 15, "") ?? Adv(s, 16, "u1b7") ?? Active(s, 1, 7, false, "16틱") ?? Count(s, 0, "16틱") ?? Adv(s, 100, "");
        });

        Run("random-vs-reference", () =>
        {
            uint seed = 9001u;
            System.Func<int, int> rnd = n => { seed = seed * 1664525u + 1013904223u; return (int)((seed >> 8) % (uint)n); };
            for (int run = 0; run < 300; run++)
            {
                var s = new BuffScheduler();
                // 기준 모델: 걸려 있는 버프의 (만료 시각, 건 순번)을 리스트에 그대로 둔다.
                var live = new System.Collections.Generic.List<(int unit, int buff, long at, int seq)>();
                int seq = 0;
                long now = 0;
                for (int step = 0; step < 60; step++)
                {
                    now += 1 + rnd(3); // 단계마다 새 틱: Advance 를 먼저 부르고 그 틱의 Apply / Cancel 을 처리한다
                    var due = live.FindAll(x => x.at <= now);
                    due.Sort((a, b) => a.at != b.at ? a.at.CompareTo(b.at) : a.seq.CompareTo(b.seq));
                    live.RemoveAll(x => x.at <= now);
                    var sb = new System.Text.StringBuilder();
                    for (int i = 0; i < due.Count; i++) { if (i > 0) sb.Append(' '); sb.Append('u').Append(due[i].unit).Append('b').Append(due[i].buff); }
                    string when = "무작위 " + run + "회차 " + step + "단계";
                    string e = Adv(s, now, sb.ToString());
                    if (e != null) return when + " " + e;
                    int ops = 1 + rnd(3);
                    for (int o = 0; o < ops; o++)
                    {
                        int unit = 1 + rnd(3), buff = 1 + rnd(2);
                        if (rnd(100) < 70)
                        {
                            long dur = 1 + rnd(8);
                            live.RemoveAll(x => x.unit == unit && x.buff == buff);
                            live.Add((unit, buff, now + dur, seq++));
                            s.Apply(unit, buff, now, dur);
                        }
                        else
                        {
                            bool had = live.RemoveAll(x => x.unit == unit && x.buff == buff) > 0;
                            e = Can(s, unit, buff, had, when + " " + now + "틱");
                            if (e != null) return e;
                        }
                    }
                    e = Count(s, live.Count, when + " " + now + "틱");
                    if (e != null) return e;
                    for (int unit = 1; unit <= 3; unit++)
                        for (int buff = 1; buff <= 2; buff++)
                        {
                            e = Active(s, unit, buff, live.Exists(x => x.unit == unit && x.buff == buff), when + " " + now + "틱");
                            if (e != null) return e;
                        }
                }
            }
            return null;
        });
    }
}

