using System;

public static class Sight
{
    // wall[x, y] == true 이면 (x, y) 칸은 시야를 막는 벽이다.
    // (x0, y0) 칸의 중심과 (x1, y1) 칸의 중심을 잇는 시선이 벽에 막히지 않으면 true.
    // 두 좌표는 항상 맵 안에 있다.
    public static bool HasLineOfSight(bool[,] wall, int x0, int y0, int x1, int y1)
    {
        if (wall[x0, y0]) return false; // 양 끝 칸도 "지나는 칸"이다

        int dx = x1 - x0, dy = y1 - y0;
        int nx = Math.Abs(dx), ny = Math.Abs(dy); // 건너야 할 세로 경계선 수, 가로 경계선 수
        int stepX = dx > 0 ? 1 : -1, stepY = dy > 0 ? 1 : -1;

        int x = x0, y = y0;
        int ix = 0, iy = 0; // 지금까지 건넌 세로 / 가로 경계선 수
        while (ix < nx || iy < ny)
        {
            // 다음 세로 경계선은 선분의 (ix + 0.5) / nx 지점, 다음 가로 경계선은 (iy + 0.5) / ny 지점에 있다.
            // 두 분수를 통분해 정수로 비교한다: (1 + 2 ix) * ny  vs  (1 + 2 iy) * nx
            long decision = (long)(1 + 2 * ix) * ny - (long)(1 + 2 * iy) * nx;

            if (decision == 0)
            {
                // 두 경계선을 동시에 만난다 = 꼭짓점을 정확히 지난다.
                // 꼭짓점만 스치는 양옆 두 칸이 모두 벽이면 틈이 없으므로 막힌다.
                if (wall[x + stepX, y] && wall[x, y + stepY]) return false;
                x += stepX; y += stepY;
                ix++; iy++;
            }
            else if (decision < 0)
            {
                x += stepX; ix++; // 세로 경계선을 먼저 만난다: 가로로 한 칸
            }
            else
            {
                y += stepY; iy++; // 가로 경계선을 먼저 만난다: 세로로 한 칸
            }

            if (wall[x, y]) return false;
        }
        return true;
    }
}

