public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // rows[y][x] == '#' 이면 벽. 반환 배열은 wall[x, y].
    static bool[,] Map(params string[] rows)
    {
        var wall = new bool[rows[0].Length, rows.Length];
        for (int y = 0; y < rows.Length; y++)
            for (int x = 0; x < rows[y].Length; x++) wall[x, y] = rows[y][x] == '#';
        return wall;
    }

    static string Text(bool[,] wall)
    {
        var sb = new System.Text.StringBuilder();
        for (int y = 0; y < wall.GetLength(1); y++)
        {
            if (y > 0) sb.Append('/');
            for (int x = 0; x < wall.GetLength(0); x++) sb.Append(wall[x, y] ? '#' : '.');
        }
        return sb.ToString();
    }

    // 양방향을 모두 호출해 기대값과 비교한다.
    static string See(bool[,] wall, int x0, int y0, int x1, int y1, bool expected)
    {
        bool ab = Sight.HasLineOfSight(wall, x0, y0, x1, y1);
        if (ab != expected) return "맵 " + Text(wall) + " 에서 (" + x0 + "," + y0 + ")→(" + x1 + "," + y1 + ") 기대 " + expected + " / 결과 " + ab;
        bool ba = Sight.HasLineOfSight(wall, x1, y1, x0, y0);
        if (ba != expected) return "맵 " + Text(wall) + " 에서 (" + x1 + "," + y1 + ")→(" + x0 + "," + y0 + ") 기대 " + expected + " / 결과 " + ba;
        return null;
    }

    // 기준 구현: 모든 칸에 대해 "선분이 그 칸의 내부를 지나는가"를 정수 연산으로 직접 판정한다.
    // 좌표를 2배로 늘려 칸 (cx, cy) 를 열린 정사각형 (2cx, 2cx+2) x (2cy, 2cy+2), 칸의 중심을 (2cx+1, 2cy+1) 로 둔다.
    static bool Axis(long p, long d, long c, out long lo, out long hi, out long den)
    {
        long a = 2 * c - p, b = 2 * c + 2 - p;
        lo = 0; hi = 0; den = 0;
        if (d == 0) return a < 0 && b > 0;
        if (d > 0) { lo = a; hi = b; den = d; } else { lo = -b; hi = -a; den = -d; }
        return true;
    }

    static bool Crosses(long px, long py, long dx, long dy, int cx, int cy)
    {
        long xlo, xhi, xden, ylo, yhi, yden;
        if (!Axis(px, dx, cx, out xlo, out xhi, out xden)) return false;
        if (!Axis(py, dy, cy, out ylo, out yhi, out yden)) return false;
        if (xden == 0 && yden == 0) return true;
        long lo, hi;
        if (xden == 0) { lo = System.Math.Max(ylo, 0); hi = System.Math.Min(yhi, yden); }
        else if (yden == 0) { lo = System.Math.Max(xlo, 0); hi = System.Math.Min(xhi, xden); }
        else
        {
            lo = System.Math.Max(System.Math.Max(xlo * yden, ylo * xden), 0);
            hi = System.Math.Min(System.Math.Min(xhi * yden, yhi * xden), xden * yden);
        }
        return lo < hi;
    }

    static bool Ref(bool[,] wall, int x0, int y0, int x1, int y1)
    {
        int w = wall.GetLength(0), h = wall.GetLength(1);
        long px = 2L * x0 + 1, py = 2L * y0 + 1, dx = 2L * (x1 - x0), dy = 2L * (y1 - y0);
        var crossed = new bool[w, h];
        for (int cx = 0; cx < w; cx++)
            for (int cy = 0; cy < h; cy++)
            {
                crossed[cx, cy] = Crosses(px, py, dx, dy, cx, cy);
                if (crossed[cx, cy] && wall[cx, cy]) return false;
            }
        if (dx == 0 || dy == 0) return true; // 칸 중심을 잇는 가로·세로 선은 꼭짓점을 지나지 않는다
        for (int i = 1; i < w; i++)
            for (int j = 1; j < h; j++)
            {
                long vx = 2L * i - px, vy = 2L * j - py;
                if (vx * dy - vy * dx != 0) continue;                                    // 꼭짓점이 직선 위에 없다
                if (vx * dx <= 0 || System.Math.Abs(vx) >= System.Math.Abs(dx)) continue; // 선분 밖
                int touched = 0, walls = 0;
                for (int a = i - 1; a <= i; a++)
                    for (int b = j - 1; b <= j; b++)
                        if (!crossed[a, b]) { touched++; if (wall[a, b]) walls++; }
                if (touched == 2 && walls == 2) return false;
            }
        return true;
    }

    public static void Main()
    {
        Run("open-floor-and-same-cell", () =>
        {
            var m = Map(".....", ".....", ".....", ".....");
            return See(m, 0, 0, 4, 3, true) ?? See(m, 4, 0, 0, 3, true) ?? See(m, 2, 1, 2, 1, true)
                ?? See(m, 0, 2, 1, 2, true) ?? See(m, 3, 3, 3, 2, true) ?? See(m, 1, 1, 2, 2, true);
        });

        Run("straight-lines", () =>
        {
            var m = Map("......", "..#...", "......", "......");
            return See(m, 0, 1, 5, 1, false) ?? See(m, 2, 0, 2, 3, false)   // 벽을 가로·세로로 지난다
                ?? See(m, 0, 0, 5, 0, true) ?? See(m, 0, 2, 5, 2, true)      // 벽 옆 줄은 보인다
                ?? See(m, 1, 0, 1, 3, true) ?? See(m, 3, 0, 3, 3, true)
                ?? See(m, 0, 1, 1, 1, true) ?? See(m, 3, 1, 5, 1, true);     // 벽에 닿기 전까지는 보인다
        });

        Run("every-clipped-cell-counts", () =>
        {
            // (0,0)→(2,1) 의 시선은 (0,0) (1,0) (1,1) (2,1) 네 칸의 내부를 지난다.
            string e = See(Map(".#.", "..."), 0, 0, 2, 1, false)
                ?? See(Map("...", ".#."), 0, 0, 2, 1, false)
                ?? See(Map("..#", "#.."), 0, 0, 2, 1, true);
            if (e != null) return e;
            // (0,0)→(1,2) 는 (0,0) (0,1) (1,1) (1,2)
            e = See(Map("..", "#.", ".."), 0, 0, 1, 2, false)
                ?? See(Map("..", ".#", ".."), 0, 0, 1, 2, false)
                ?? See(Map(".#", "..", "#."), 0, 0, 1, 2, true);
            if (e != null) return e;
            // (0,0)→(4,1) 은 (0,0) (1,0) (2,0) (2,1) (3,1) (4,1)
            return See(Map("..#..", "....."), 0, 0, 4, 1, false)
                ?? See(Map(".....", "..#.."), 0, 0, 4, 1, false)
                ?? See(Map("...##", "##..."), 0, 0, 4, 1, true);
        });

        Run("corner-with-one-wall-is-open", () =>
        {
            return See(Map(".#", ".."), 0, 0, 1, 1, true)
                ?? See(Map("..", "#."), 0, 0, 1, 1, true)
                ?? See(Map("#.", ".."), 0, 1, 1, 0, true)
                ?? See(Map("..", ".#"), 0, 1, 1, 0, true)
                // (0,0)→(3,1) 은 (0,0) (1,0) 을 지나 꼭짓점 (2,1) 을 정확히 통과하고 (2,1) (3,1) 로 간다.
                ?? See(Map("..#.", "...."), 0, 0, 3, 1, true)
                ?? See(Map("....", ".#.."), 0, 0, 3, 1, true)
                ?? See(Map("....", "..#.", "...."), 0, 0, 3, 2, false);
        });

        Run("corner-between-two-walls-is-blocked", () =>
        {
            return See(Map(".#", "#."), 0, 0, 1, 1, false)
                ?? See(Map("..#.", ".#.."), 0, 0, 3, 1, false)
                ?? See(Map(".....", ".....", "...#.", "..#..", "....."), 0, 0, 4, 4, false)
                ?? See(Map(".....", ".....", ".#...", "..#..", "....."), 4, 0, 0, 4, false)
                ?? See(Map(".....", ".....", ".#...", "..#..", "....."), 0, 0, 4, 4, true)
                ?? See(Map(".....", "..#..", ".#...", ".....", "....."), 0, 0, 4, 4, false)
                ?? See(Map(".....", "..#..", ".#...", ".....", "....."), 0, 0, 1, 1, true);
        });

        Run("end-cells-are-checked", () =>
        {
            var m = Map("#....", ".....", "....#");
            return See(m, 1, 1, 4, 2, false) ?? See(m, 0, 0, 2, 1, false) ?? See(m, 0, 0, 0, 0, false)
                ?? See(m, 0, 0, 4, 2, false) ?? See(m, 1, 0, 4, 1, true);
        });

        Run("same-answer-both-ways", () =>
        {
            var m = Map(".......", "..#....", "....#..", ".#.....", ".....#.", ".......");
            int w = m.GetLength(0), h = m.GetLength(1);
            for (int a = 0; a < w * h; a++)
                for (int b = a + 1; b < w * h; b++)
                {
                    int x0 = a % w, y0 = a / w, x1 = b % w, y1 = b / w;
                    bool ab = Sight.HasLineOfSight(m, x0, y0, x1, y1), ba = Sight.HasLineOfSight(m, x1, y1, x0, y0);
                    if (ab != ba) return "맵 " + Text(m) + " 에서 (" + x0 + "," + y0 + ")→(" + x1 + "," + y1 + ") 는 " + ab + " 인데 반대 방향은 " + ba;
                }
            return null;
        });

        Run("random-vs-reference", () =>
        {
            uint s = 31337u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            for (int run = 0; run < 400; run++)
            {
                int w = 1 + rnd(9), h = 1 + rnd(9), density = 5 + rnd(30);
                var m = new bool[w, h];
                for (int x = 0; x < w; x++) for (int y = 0; y < h; y++) m[x, y] = rnd(100) < density;
                for (int q = 0; q < 60; q++)
                {
                    int x0 = rnd(w), y0 = rnd(h), x1 = rnd(w), y1 = rnd(h);
                    bool want = Ref(m, x0, y0, x1, y1);
                    bool got = Sight.HasLineOfSight(m, x0, y0, x1, y1);
                    if (got != want) return "무작위 " + run + "회차: 맵 " + Text(m) + " 에서 (" + x0 + "," + y0 + ")→(" + x1 + "," + y1 + ") 기대 " + want + " / 결과 " + got;
                }
            }
            return null;
        });
    }
}

