problems.solutionCode:
using System;
using System.Collections.Generic;

// 전술 RPG 의 이동 범위. 유닛을 선택한 순간 한 번 만들고, 커서가 움직일 때마다 질의한다.
public sealed class MoveRange
{
    public const int Empty = 0; // 유닛이 없는 칸
    public const int Ally = 1;  // 아군이 서 있는 칸: 지나갈 수 있지만 멈출 수 없다
    public const int Enemy = 2; // 적이 서 있는 칸: 지나갈 수 없다

    private const int Unreached = int.MaxValue;
    private static readonly int[] Dx = { 1, -1, 0, 0 };
    private static readonly int[] Dy = { 0, 0, 1, -1 };

    private readonly int _width, _height, _movePoints, _start;
    private readonly int[] _cost;      // 시작 칸에서 그 칸까지 드는 최소 이동력. 이동력 안에 닿지 못하면 Unreached
    private readonly int[] _cameFrom;  // 최소 비용 경로에서 바로 앞 칸. 시작 칸과 닿지 못한 칸은 -1
    private readonly bool[] _canStop;  // 멈출 수 있는 칸인가(닿을 수 있고, 다른 유닛이 없다)

    // terrain[x, y]: 그 칸에 들어갈 때 드는 이동력(1 이상). 0 이면 들어갈 수 없는 지형이다.
    // units[x, y]: Empty / Ally / Enemy. 시작 칸 (startX, startY) 에는 움직이는 유닛 자신이 있다.
    // movePoints: 이번 턴에 쓸 수 있는 이동력(0 이상).
    public MoveRange(int[,] terrain, int[,] units, int startX, int startY, int movePoints)
    {
        _width = terrain.GetLength(0);
        _height = terrain.GetLength(1);
        _movePoints = movePoints;
        _start = startY * _width + startX;

        int n = _width * _height;
        _cost = new int[n];
        _cameFrom = new int[n];
        _canStop = new bool[n];
        for (int i = 0; i < n; i++) { _cost[i] = Unreached; _cameFrom[i] = -1; }

        // 이동력으로 제한한 다익스트라. 큐에는 (칸, 그 칸까지의 비용)을 넣고 비용이 작은 것부터 꺼낸다.
        var frontier = new PriorityQueue<int, int>();
        _cost[_start] = 0;
        frontier.Enqueue(_start, 0);

        while (frontier.TryDequeue(out int cur, out int curCost))
        {
            if (curCost > _cost[cur]) continue; // 더 싼 경로가 이미 처리된 낡은 항목

            int cx = cur % _width, cy = cur / _width;
            for (int d = 0; d < 4; d++)
            {
                int nx = cx + Dx[d], ny = cy + Dy[d];
                if (nx < 0 || ny < 0 || nx >= _width || ny >= _height) continue;
                if (terrain[nx, ny] <= 0) continue;        // 들어갈 수 없는 지형
                if (units[nx, ny] == Enemy) continue;      // 적은 통과할 수 없다
                // 아군 칸은 여기서 막지 않는다: 멈출 수는 없어도 지나갈 수는 있다.

                int next = ny * _width + nx;
                int nextCost = curCost + terrain[nx, ny];  // 들어가는 칸의 비용을 낸다
                if (nextCost > movePoints) continue;       // 이동력을 넘으면 더 볼 필요가 없다
                if (nextCost >= _cost[next]) continue;     // 더 싸질 때만 갱신한다

                _cost[next] = nextCost;
                _cameFrom[next] = cur;
                frontier.Enqueue(next, nextCost);
            }
        }

        // "닿을 수 있다"와 "멈출 수 있다"는 다르다. 탐색이 끝난 뒤에 따로 판정한다.
        for (int i = 0; i < n; i++)
            _canStop[i] = _cost[i] != Unreached && (i == _start || units[i % _width, i / _width] == Empty);
    }

    // (x, y) 에 멈출 수 있으면 true.
    public bool CanStopAt(int x, int y) => _canStop[y * _width + x];

    // (x, y) 에 멈췄을 때 남는 이동력의 최댓값. 멈출 수 없는 칸이면 -1.
    public int RemainingAt(int x, int y)
    {
        int i = y * _width + x;
        return _canStop[i] ? _movePoints - _cost[i] : -1;
    }

    // 시작 칸에서 (x, y) 까지, 남는 이동력이 RemainingAt(x, y) 가 되는 경로. 시작 칸과 도착 칸을 포함한다.
    // 멈출 수 없는 칸이면 빈 리스트.
    public List<(int x, int y)> PathTo(int x, int y)
    {
        var path = new List<(int x, int y)>();
        int i = y * _width + x;
        if (!_canStop[i]) return path;

        // 도착 칸에서 시작 칸까지 "바로 앞 칸"을 거슬러 올라간 뒤 뒤집는다.
        for (int at = i; at != -1; at = _cameFrom[at])
            path.Add((at % _width, at / _width));
        path.Reverse();
        return path;
    }
}

