public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    sealed class Board
    {
        public int[,] Terrain, Units;
        public int W, H, Sx, Sy;
        public string Name;
    }

    // terrain: 행을 '/' 로 구분, 글자는 이동 비용(0 = 들어갈 수 없음).
    // units: 같은 모양, '.' 빈 칸, 'S' 움직이는 유닛(시작 칸), 'A' 아군, 'E' 적.
    static Board Make(string terrain, string units)
    {
        string[] t = terrain.Split('/'), u = units.Split('/');
        var b = new Board { W = t[0].Length, H = t.Length, Name = "지형 " + terrain + " 유닛 " + units };
        b.Terrain = new int[b.W, b.H]; b.Units = new int[b.W, b.H];
        for (int y = 0; y < b.H; y++)
            for (int x = 0; x < b.W; x++)
            {
                b.Terrain[x, y] = t[y][x] - '0';
                char c = u[y][x];
                b.Units[x, y] = c == 'E' ? 2 : (c == 'A' || c == 'S') ? 1 : 0;
                if (c == 'S') { b.Sx = x; b.Sy = y; }
            }
        return b;
    }

    // 기준 구현: 더 줄어드는 칸이 없을 때까지 모든 칸을 반복해서 완화한다(우선순위 큐 없음).
    static int[,] RefCost(Board b, int move)
    {
        const int Inf = int.MaxValue;
        var cost = new int[b.W, b.H];
        for (int x = 0; x < b.W; x++) for (int y = 0; y < b.H; y++) cost[x, y] = Inf;
        cost[b.Sx, b.Sy] = 0;
        int[] dx = { 1, -1, 0, 0 }, dy = { 0, 0, 1, -1 };
        bool changed = true;
        while (changed)
        {
            changed = false;
            for (int x = 0; x < b.W; x++)
                for (int y = 0; y < b.H; y++)
                {
                    if (cost[x, y] == Inf) continue;
                    for (int d = 0; d < 4; d++)
                    {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx < 0 || ny < 0 || nx >= b.W || ny >= b.H) continue;
                        if (b.Terrain[nx, ny] == 0 || b.Units[nx, ny] == 2) continue;
                        int c = cost[x, y] + b.Terrain[nx, ny];
                        if (c <= move && c < cost[nx, ny]) { cost[nx, ny] = c; changed = true; }
                    }
                }
        }
        return cost;
    }

    static int RefRemaining(Board b, int[,] cost, int move, int x, int y)
    {
        if (cost[x, y] == int.MaxValue) return -1;
        if (!(x == b.Sx && y == b.Sy) && b.Units[x, y] != 0) return -1;
        return move - cost[x, y];
    }

    // 남는 이동력 표를 행마다 '/' 로 이어 붙인 문자열로 만든다('-' = 멈출 수 없음).
    static string Grid(Board b, System.Func<int, int, int> remainingAt)
    {
        var sb = new System.Text.StringBuilder();
        for (int y = 0; y < b.H; y++)
        {
            if (y > 0) sb.Append('/');
            for (int x = 0; x < b.W; x++)
            {
                int r = remainingAt(x, y);
                if (r < 0) sb.Append('-'); else if (r > 9) sb.Append('(').Append(r).Append(')'); else sb.Append(r);
            }
        }
        return sb.ToString();
    }

    // RemainingAt 표와 CanStopAt 을 기대값과 비교한다.
    static string Range(Board b, int move, string expected)
    {
        var r = new MoveRange(b.Terrain, b.Units, b.Sx, b.Sy, move);
        string got = Grid(b, (x, y) => r.RemainingAt(x, y));
        if (got != expected) return b.Name + " 이동력 " + move + ": 남는 이동력 기대 [" + expected + "] / 결과 [" + got + "]";
        for (int y = 0; y < b.H; y++)
            for (int x = 0; x < b.W; x++)
            {
                bool want = r.RemainingAt(x, y) >= 0, stop = r.CanStopAt(x, y);
                if (stop != want) return b.Name + " 이동력 " + move + ": CanStopAt(" + x + "," + y + ") 기대 " + want + " / 결과 " + stop;
            }
        return null;
    }

    // 모든 칸의 PathTo 를 규칙으로 검증한다(최소 비용 경로가 여러 개면 어느 것이든 통과).
    static string Paths(Board b, int move)
    {
        var cost = RefCost(b, move);
        var r = new MoveRange(b.Terrain, b.Units, b.Sx, b.Sy, move);
        for (int y = 0; y < b.H; y++)
            for (int x = 0; x < b.W; x++)
            {
                string where = b.Name + " 이동력 " + move + " PathTo(" + x + "," + y + ")";
                var path = r.PathTo(x, y);
                if (path == null) return where + " 가 null 을 반환";
                int remaining = RefRemaining(b, cost, move, x, y);
                if (remaining < 0)
                {
                    if (path.Count != 0) return where + ": 멈출 수 없는 칸인데 길이 " + path.Count + " 인 경로를 반환";
                    continue;
                }
                if (path.Count == 0) return where + ": 멈출 수 있는 칸인데 빈 경로를 반환";
                if (path[0].x != b.Sx || path[0].y != b.Sy) return where + ": 경로가 시작 칸 (" + b.Sx + "," + b.Sy + ") 이 아니라 (" + path[0].x + "," + path[0].y + ") 에서 시작";
                var last = path[path.Count - 1];
                if (last.x != x || last.y != y) return where + ": 경로가 (" + last.x + "," + last.y + ") 에서 끝남";
                int spent = 0;
                for (int i = 1; i < path.Count; i++)
                {
                    int px = path[i].x, py = path[i].y;
                    if (px < 0 || py < 0 || px >= b.W || py >= b.H) return where + ": 맵 밖의 칸 (" + px + "," + py + ") 을 지남";
                    if (System.Math.Abs(px - path[i - 1].x) + System.Math.Abs(py - path[i - 1].y) != 1) return where + ": (" + path[i - 1].x + "," + path[i - 1].y + ") 다음 칸 (" + px + "," + py + ") 이 상하좌우로 붙어 있지 않음";
                    if (b.Terrain[px, py] == 0) return where + ": 들어갈 수 없는 지형 (" + px + "," + py + ") 을 지남";
                    if (b.Units[px, py] == 2) return where + ": 적이 있는 칸 (" + px + "," + py + ") 을 지남";
                    spent += b.Terrain[px, py];
                }
                if (spent != move - remaining) return where + ": 경로의 이동력 합 기대 " + (move - remaining) + " / 결과 " + spent;
            }
        return null;
    }

    public static void Main()
    {
        Run("open-field", () =>
        {
            var b = Make("11111/11111/11111/11111/11111", "...../...../..S../...../.....");
            return Range(b, 2, "--0--/-010-/01210/-010-/--0--")
                ?? Range(b, 1, "-----/--0--/-010-/--0--/-----");
        });

        Run("terrain-cost-beats-step-count", () =>
        {
            // (2,0) 은 숲(5)을 지나면 두 걸음에 6, 아래로 돌아가면 네 걸음에 4.
            var b = Make("151/111", "S../...");
            return Range(b, 5, "501/432") ?? Range(b, 4, "4-0/321")
                ?? Range(b, 6, "612/543")   // 이동력 6 이면 늪 길(비용 6)이 먼저 닿지만 답은 아랫줄 길(비용 4)
                ?? Range(Make("1311/1191/1111", "S.../..../...."), 6, "6321/54-0/4321");
        });

        Run("spending-every-point-is-allowed", () =>
        {
            return Range(Make("11111", "S...."), 3, "3210-")
                ?? Range(Make("1322", "S..."), 4, "41--") ?? Range(Make("1322", "S..."), 5, "520-")
                ?? Range(Make("9123", "S..."), 6, "6530");   // 시작 칸의 비용은 내지 않는다
        });

        Run("allies-can-be-passed-not-stopped-on", () =>
        {
            return Range(Make("11111", "SA.A."), 4, "4-2-0")
                ?? Range(Make("1111", "S..A"), 3, "321-")
                ?? Range(Make("121/111", ".A./S.A"), 3, "2-0/32-");
        });

        Run("enemies-block-the-way", () =>
        {
            return Range(Make("11111", "S.E.."), 4, "43---")
                ?? Range(Make("111/111", "SE./..."), 4, "4-0/321")
                ?? Range(Make("111/111", "SE./.E."), 9, "9--/8--");
        });

        Run("blocked-terrain-and-zero-move", () =>
        {
            return Range(Make("101/101/111", "S../.../..."), 4, "4--/3--/210")
                ?? Range(Make("101/101/111", "S../.../..."), 0, "0--/---/---")
                ?? Range(Make("1", "S"), 3, "3")
                ?? Range(Make("10/01", "S./.."), 5, "5-/--");
        });

        Run("path-is-legal-and-cheapest", () =>
        {
            var one = new MoveRange(Make("111/111", "S../...").Terrain, Make("111/111", "S../...").Units, 0, 0, 3);
            var self = one.PathTo(0, 0);
            if (self == null || self.Count != 1 || self[0].x != 0 || self[0].y != 0) return "PathTo(시작 칸) 은 시작 칸 하나만 담아야 함: 길이 " + (self == null ? -1 : self.Count);
            return Paths(Make("151/111", "S../..."), 5)
                ?? Paths(Make("11111", "SA.A."), 4)
                ?? Paths(Make("111/111", "SE./..."), 4)
                ?? Paths(Make("1311/1191/1111", "S.../.A../...."), 6)
                ?? Paths(Make("12121/10301/11111/21012", "..A../...../..S.E/....."), 7);
        });

        Run("random-vs-reference", () =>
        {
            uint s = 4649u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            for (int run = 0; run < 400; run++)
            {
                int w = 1 + rnd(7), h = 1 + rnd(7);
                var t = new System.Text.StringBuilder(); var u = new System.Text.StringBuilder();
                int sx = rnd(w), sy = rnd(h);
                for (int y = 0; y < h; y++)
                {
                    if (y > 0) { t.Append('/'); u.Append('/'); }
                    for (int x = 0; x < w; x++)
                    {
                        bool start = x == sx && y == sy;
                        int roll = rnd(100);
                        t.Append((char)('0' + (start ? 1 + rnd(4) : roll < 15 ? 0 : 1 + rnd(4))));
                        int who = rnd(100);
                        u.Append(start ? 'S' : who < 12 ? 'A' : who < 22 ? 'E' : '.');
                    }
                }
                var b = Make(t.ToString(), u.ToString());
                int move = rnd(10);
                var cost = RefCost(b, move);
                string e = Range(b, move, Grid(b, (x, y) => RefRemaining(b, cost, move, x, y))) ?? Paths(b, move);
                if (e != null) return "무작위 " + run + "회차: " + e;
            }
            return null;
        });
    }
}

