using System;

// 매치-3 보드 한 단계 처리. board[row, col], row 0 이 맨 위다.
// 0 은 빈칸, 1 이상은 보석 색이다.
public static class Match3
{
    // 가로나 세로로 같은 색이 3개 이상 이어진 칸을 모두 0 으로 바꾸고,
    // 지운 칸의 수(겹치는 칸은 한 번)를 반환한다.
    public static int ClearMatches(int[,] board)
    {
        int rows = board.GetLength(0), cols = board.GetLength(1);

        // 1단계: 지우기 전의 보드에서 모든 줄을 찾아 표시만 한다.
        // 찾는 도중에 지우면 가로 줄과 세로 줄이 겹치는 칸(L·T·+ 모양)에서 세로 줄을 놓친다.
        var marked = new bool[rows, cols];

        for (int r = 0; r < rows; r++)
        {
            int start = 0;                       // 지금 보고 있는 같은 색 구간의 시작 열
            for (int c = 1; c <= cols; c++)
            {
                // 구간이 끝나는 곳: 보드 끝이거나 색이 바뀌었을 때
                if (c < cols && board[r, c] == board[r, start]) continue;
                if (board[r, start] != 0 && c - start >= 3)
                    for (int k = start; k < c; k++) marked[r, k] = true;
                start = c;
            }
        }

        for (int c = 0; c < cols; c++)
        {
            int start = 0;
            for (int r = 1; r <= rows; r++)
            {
                if (r < rows && board[r, c] == board[start, c]) continue;
                if (board[start, c] != 0 && r - start >= 3)
                    for (int k = start; k < r; k++) marked[k, c] = true;
                start = r;
            }
        }

        // 2단계: 표시한 칸을 한 번씩만 지우고 센다.
        int cleared = 0;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (marked[r, c]) { board[r, c] = 0; cleared++; }
        return cleared;
    }

    // 열마다 보석을 아래(row 가 큰 쪽)로 떨어뜨린다. 보석의 위아래 순서는 그대로, 빈칸은 위로 간다.
    public static void ApplyGravity(int[,] board)
    {
        int rows = board.GetLength(0), cols = board.GetLength(1);
        for (int c = 0; c < cols; c++)
        {
            int write = rows - 1;                // 다음 보석이 내려앉을 자리(아래부터 채운다)
            for (int read = rows - 1; read >= 0; read--)
            {
                if (board[read, c] == 0) continue;
                board[write, c] = board[read, c];  // write >= read 이므로 아직 읽지 않은 칸을 덮지 않는다
                write--;
            }
            for (int r = write; r >= 0; r--) board[r, c] = 0; // 남은 위쪽은 빈칸
        }
    }
}

