public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // "122/133/111" 처럼 행을 '/' 로 나눈 숫자열을 보드로 만든다. 맨 앞 행이 row 0(맨 위)이다.
    static int[,] B(string s)
    {
        string[] rows = s.Split('/');
        var b = new int[rows.Length, rows[0].Length];
        for (int r = 0; r < rows.Length; r++)
            for (int c = 0; c < rows[0].Length; c++) b[r, c] = rows[r][c] - '0';
        return b;
    }

    static string D(int[,] b)
    {
        var sb = new System.Text.StringBuilder();
        for (int r = 0; r < b.GetLength(0); r++)
        {
            if (r > 0) sb.Append('/');
            for (int c = 0; c < b.GetLength(1); c++) sb.Append((char)('0' + b[r, c]));
        }
        return sb.ToString();
    }

    // ClearMatches 한 번의 반환값과 그 뒤의 보드를 확인한다.
    static string Clear(string before, int expectedCount, string expectedAfter)
    {
        var b = B(before);
        int got = Match3.ClearMatches(b);
        if (got != expectedCount) return "ClearMatches(" + before + ") 반환값 기대 " + expectedCount + " / 결과 " + got;
        string after = D(b);
        return after == expectedAfter ? null : "ClearMatches(" + before + ") 뒤 보드 기대 " + expectedAfter + " / 결과 " + after;
    }

    static string Drop(string before, string expectedAfter)
    {
        var b = B(before);
        Match3.ApplyGravity(b);
        string after = D(b);
        return after == expectedAfter ? null : "ApplyGravity(" + before + ") 뒤 보드 기대 " + expectedAfter + " / 결과 " + after;
    }

    // 기준 구현: 칸마다 좌우·상하로 같은 색이 몇 칸 이어지는지 직접 센다.
    static int RefClear(int[,] b)
    {
        int rows = b.GetLength(0), cols = b.GetLength(1), n = 0;
        var hit = new bool[rows, cols];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
            {
                int v = b[r, c];
                if (v == 0) continue;
                int h = 1, w = 1;
                for (int k = c - 1; k >= 0 && b[r, k] == v; k--) h++;
                for (int k = c + 1; k < cols && b[r, k] == v; k++) h++;
                for (int k = r - 1; k >= 0 && b[k, c] == v; k--) w++;
                for (int k = r + 1; k < rows && b[k, c] == v; k++) w++;
                hit[r, c] = h >= 3 || w >= 3;
            }
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (hit[r, c]) { b[r, c] = 0; n++; }
        return n;
    }

    static void RefDrop(int[,] b)
    {
        int rows = b.GetLength(0), cols = b.GetLength(1);
        for (int c = 0; c < cols; c++)
        {
            var gems = new System.Collections.Generic.List<int>();
            for (int r = 0; r < rows; r++) if (b[r, c] != 0) gems.Add(b[r, c]);
            for (int r = 0; r < rows; r++)
            {
                int fromBottom = rows - 1 - r;
                b[r, c] = fromBottom < gems.Count ? gems[gems.Count - 1 - fromBottom] : 0;
            }
        }
    }

    public static void Main()
    {
        Run("separate-runs", () =>
            Clear("2134/1114/3234/2324", 7, "2130/0000/3230/2320")
            ?? Clear("1112222/3331333/4545454", 13, "0000000/0001000/4545454"));

        Run("no-match-untouched", () =>
            Clear("121/212/331", 0, "121/212/331")        // 대각선 세 칸과 두 칸짜리 줄
            ?? Clear("11/11", 0, "11/11")                  // 2x2 덩어리
            ?? Clear("12121", 0, "12121"));

        Run("l-t-plus-count-once", () =>
            Clear("122/133/111", 5, "022/033/000")          // L
            ?? Clear("111/213/314", 5, "000/203/304")       // T
            ?? Clear("213/111/415", 5, "203/000/405")       // +
            ?? Clear("32123/11111/42153", 7, "32023/00000/42053"));

        Run("empty-cells-never-match", () =>
            Clear("000/121/000", 0, "000/121/000")
            ?? Clear("0001/0001/2221", 6, "0000/0000/0000"));

        Run("gravity-gaps-keep-order", () =>
            Drop("10/04/20/05/06/30", "00/00/00/14/25/36")
            ?? Drop("102/203/301", "102/203/301")
            ?? Drop("010/000/000", "000/000/010")
            ?? Drop("3/0/0/1/0/2", "0/0/0/3/1/2"));

        Run("one-step-no-cascade", () =>
        {
            var b = B("234/245/111/253");
            int n = Match3.ClearMatches(b);
            if (n != 3 || D(b) != "234/245/000/253") return "첫 ClearMatches 기대 3, 234/245/000/253 / 결과 " + n + ", " + D(b);
            Match3.ApplyGravity(b);
            if (D(b) != "000/234/245/253") return "ApplyGravity 뒤 기대 000/234/245/253(새로 생긴 세로 줄은 그대로 남아야 함) / 결과 " + D(b);
            n = Match3.ClearMatches(b);
            if (n != 3 || D(b) != "000/034/045/053") return "두 번째 ClearMatches 기대 3, 000/034/045/053 / 결과 " + n + ", " + D(b);
            return null;
        });

        Run("random-vs-reference", () =>
        {
            uint s = 31337u;
            System.Func<int, int> rnd = m => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)m); };
            for (int t = 0; t < 2000; t++)
            {
                int rows = 1 + rnd(7), cols = 1 + rnd(7);
                var b = new int[rows, cols];
                for (int r = 0; r < rows; r++)
                    for (int c = 0; c < cols; c++) b[r, c] = rnd(100) < 15 ? 0 : 1 + rnd(3);
                string before = D(b);
                var want = (int[,])b.Clone();
                int wantN = RefClear(want);
                int gotN = Match3.ClearMatches(b);
                if (gotN != wantN || D(b) != D(want)) return "ClearMatches(" + before + ") 기대 " + wantN + ", " + D(want) + " / 결과 " + gotN + ", " + D(b);
                before = D(b);
                RefDrop(want);
                Match3.ApplyGravity(b);
                if (D(b) != D(want)) return "ApplyGravity(" + before + ") 기대 " + D(want) + " / 결과 " + D(b);
            }
            return null;
        });
    }
}

