using System;
using System.Collections.Generic;

// 새 보석의 색을 정하는 시드 고정 난수 생성기(xorshift32). 같은 시드면 같은 색 순서가 나온다.
public sealed class GemRng
{
    private uint _state;

    public GemRng(uint seed) { _state = seed == 0 ? 0x9E3779B9u : seed; } // xorshift 의 상태는 0 이면 안 된다

    // 1 .. colors 중 하나를 돌려준다.
    public int NextColor(int colors)
    {
        uint x = _state;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        _state = x;
        return 1 + (int)(((ulong)x * (ulong)colors) >> 32);
    }
}

// 매치-3 보드. cells[row, col], row 0 이 맨 위다. 0 은 빈칸, 1 .. colors 는 보석 색이다.
public sealed class Match3Board
{
    private readonly int[,] _cells;
    private readonly int _colors;
    private readonly GemRng _rng;   // 보드마다 하나. 시드에서 한 번 만들고 게임 내내 이어서 쓴다
    private readonly bool[,] _marked;

    public Match3Board(int[,] cells, int colors, uint seed)
    {
        _cells = (int[,])cells.Clone();
        _colors = colors;
        _rng = new GemRng(seed);
        _marked = new bool[_cells.GetLength(0), _cells.GetLength(1)];
    }

    public int Rows => _cells.GetLength(0);
    public int Cols => _cells.GetLength(1);
    public int this[int row, int col] => _cells[row, col];

    // 두 칸의 보석을 맞바꾼다. 이웃인지, 매치가 생기는지는 호출하는 쪽이 이미 확인했다.
    public void Swap(int r1, int c1, int r2, int c2)
    {
        int t = _cells[r1, c1];
        _cells[r1, c1] = _cells[r2, c2];
        _cells[r2, c2] = t;
    }

    // 지우기 → 떨어뜨리기 → 채우기를, 지울 줄이 없을 때까지 반복한다.
    // 단계마다 지운 칸의 수를 차례로 담아 돌려준다.
    public List<int> ResolveCascades()
    {
        var perStep = new List<int>();
        while (true)
        {
            int cleared = ClearMatches();
            if (cleared == 0) return perStep;
            perStep.Add(cleared);
            ApplyGravity();
            Refill();
        }
    }

    // 줄에 속한 칸을 표에 표시만 한 뒤, 표시된 칸을 한 번씩 지우고 센다.
    // 가로 줄과 세로 줄이 공유하는 칸도 표에서는 한 칸이므로 한 번만 센다.
    private int ClearMatches()
    {
        Array.Clear(_marked);
        for (int r = 0; r < Rows; r++)
        {
            int start = 0;
            for (int c = 1; c <= Cols; c++)
            {
                if (c < Cols && _cells[r, c] == _cells[r, start]) continue;
                if (_cells[r, start] != 0 && c - start >= 3)
                    for (int k = start; k < c; k++) _marked[r, k] = true;
                start = c;
            }
        }
        for (int c = 0; c < Cols; c++)
        {
            int start = 0;
            for (int r = 1; r <= Rows; r++)
            {
                if (r < Rows && _cells[r, c] == _cells[start, c]) continue;
                if (_cells[start, c] != 0 && r - start >= 3)
                    for (int k = start; k < r; k++) _marked[k, c] = true;
                start = r;
            }
        }

        int cleared = 0;
        for (int r = 0; r < Rows; r++)
            for (int c = 0; c < Cols; c++)
                if (_marked[r, c]) { _cells[r, c] = 0; cleared++; }
        return cleared;
    }

    // 열마다 아래에서 위로 읽으며 보석을 "다음 빈 바닥"에 내려 쓴다. 빈칸이 몇 개 연달아 있어도 한 번에 끝난다.
    private void ApplyGravity()
    {
        for (int c = 0; c < Cols; c++)
        {
            int write = Rows - 1;
            for (int read = Rows - 1; read >= 0; read--)
            {
                if (_cells[read, c] == 0) continue;
                _cells[write, c] = _cells[read, c];
                write--;
            }
            for (int r = write; r >= 0; r--) _cells[r, c] = 0;
        }
    }

    // 열은 왼쪽부터, 한 열 안에서는 아래쪽 빈칸부터 채운다. 난수는 보드의 생성기에서 이어서 뽑는다.
    private void Refill()
    {
        for (int c = 0; c < Cols; c++)
            for (int r = Rows - 1; r >= 0; r--)
                if (_cells[r, c] == 0) _cells[r, c] = _rng.NextColor(_colors);
    }
}

