public static class __Judge
{
    // 케이스마다 별도 스레드에서 돌리고 제한 시간을 둔다. 연쇄가 끝나지 않아도 나머지 케이스는 계속된다.
    static void Run(string id, System.Func<string> body)
    {
        string err = null;
        var t = new System.Threading.Thread(() =>
        {
            try { err = body(); }
            catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        });
        t.IsBackground = true;
        t.Start();
        if (!t.Join(1500)) err = "1.5초 안에 끝나지 않음(연쇄가 멈추지 않는 것으로 보임)";
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static int[,] B(string s)
    {
        string[] rows = s.Split('/');
        var b = new int[rows.Length, rows[0].Length];
        for (int r = 0; r < rows.Length; r++)
            for (int c = 0; c < rows[0].Length; c++) b[r, c] = rows[r][c] - '0';
        return b;
    }

    static string D(Match3Board m)
    {
        var sb = new System.Text.StringBuilder();
        for (int r = 0; r < m.Rows; r++)
        {
            if (r > 0) sb.Append('/');
            for (int c = 0; c < m.Cols; c++) sb.Append((char)('0' + m[r, c]));
        }
        return sb.ToString();
    }

    static string L(System.Collections.Generic.List<int> steps) => steps == null ? "null" : "[" + string.Join(",", steps) + "]";

    // ResolveCascades 한 번의 단계별 지운 수와 그 뒤의 보드를 확인한다.
    static string Resolve(Match3Board m, string when, string expectedSteps, string expectedBoard)
    {
        string before = D(m);
        string steps = L(m.ResolveCascades()), after = D(m);
        if (steps != expectedSteps) return when + " 보드 " + before + " 의 ResolveCascades 단계별 지운 수 기대 " + expectedSteps + " / 결과 " + steps;
        return after == expectedBoard ? null : when + " 보드 " + before + " 의 ResolveCascades 뒤 보드 기대 " + expectedBoard + " / 결과 " + after;
    }

    // 기준 구현: 칸마다 이어진 길이를 직접 세어 표시 → 리스트로 열을 다시 쌓기 → 같은 xorshift 로 채우기.
    sealed class Ref
    {
        public int[,] Cells; public int Colors; public uint State;
        public int Next() { uint x = State; x ^= x << 13; x ^= x >> 17; x ^= x << 5; State = x; return 1 + (int)(((ulong)x * (ulong)Colors) >> 32); }
        public string Resolve()
        {
            int rows = Cells.GetLength(0), cols = Cells.GetLength(1);
            var steps = new System.Collections.Generic.List<int>();
            while (true)
            {
                var hit = new bool[rows, cols]; int n = 0;
                for (int r = 0; r < rows; r++)
                    for (int c = 0; c < cols; c++)
                    {
                        int v = Cells[r, c]; if (v == 0) continue;
                        int h = 1, w = 1;
                        for (int k = c - 1; k >= 0 && Cells[r, k] == v; k--) h++;
                        for (int k = c + 1; k < cols && Cells[r, k] == v; k++) h++;
                        for (int k = r - 1; k >= 0 && Cells[k, c] == v; k--) w++;
                        for (int k = r + 1; k < rows && Cells[k, c] == v; k++) w++;
                        if (h >= 3 || w >= 3) { hit[r, c] = true; n++; }
                    }
                if (n == 0) return L(steps);
                steps.Add(n);
                for (int c = 0; c < cols; c++)
                {
                    var gems = new System.Collections.Generic.List<int>();
                    for (int r = 0; r < rows; r++) if (!hit[r, c]) gems.Add(Cells[r, c]);
                    int empty = rows - gems.Count;
                    for (int r = 0; r < rows; r++) Cells[r, c] = r < empty ? 0 : gems[r - empty];
                    for (int r = empty - 1; r >= 0; r--) Cells[r, c] = Next();
                }
            }
        }
    }

    public static void Main()
    {
        Run("l-t-plus-score-once", () =>
            Resolve(new Match3Board(B("1112/1234/1342/2423"), 4, 20261122u), "L 모양", "[5]", "3322/4234/1342/2423")
            ?? Resolve(new Match3Board(B("3331/1324/2341/4123"), 4, 20261122u), "T 모양", "[5]", "1321/1324/2441/4123")
            ?? Resolve(new Match3Board(B("1243/2221/3214/4132"), 4, 20261122u), "+ 모양", "[5]", "1323/1341/3414/4132"));

        Run("vertical-clear-falls-to-bottom", () =>
            Resolve(new Match3Board(B("213/324/132/143/124"), 4, 20261122u), "맨 아래 세로 줄", "[3]", "313/424/132/243/324"));

        Run("refill-sequence-continues", () =>
        {
            var m = new Match3Board(B("1121/2342/3423/4244"), 4, 20261122u);
            string e = Resolve(m, "줄이 없는 처음", "[]", "1121/2342/3423/4244");
            if (e != null) return e;
            m.Swap(0, 2, 0, 3);
            e = Resolve(m, "첫 수 (0,2)<->(0,3) 뒤", "[3]", "1432/2342/3423/4244");
            if (e != null) return e;
            m.Swap(2, 1, 3, 1);
            return Resolve(m, "두 번째 수 (2,1)<->(3,1) 뒤(두 번째 채우기는 색 순서를 이어서 써야 함)", "[4]", "3243/1432/2342/3223");
        });

        Run("same-seed-same-replay", () =>
        {
            var a = new Match3Board(B("1121/2342/3423/4244"), 4, 777u);
            var b = new Match3Board(B("1121/2342/3423/4244"), 4, 777u);
            a.Swap(0, 2, 0, 3); b.Swap(0, 2, 0, 3);
            string sa = L(a.ResolveCascades()), sb = L(b.ResolveCascades());
            return sa == sb && D(a) == D(b) ? null : "같은 시드 · 같은 수인데 결과가 다름: " + sa + " " + D(a) + " / " + sb + " " + D(b);
        });

        Run("cascade-ends", () =>
            Resolve(new Match3Board(B("11123/23412/34124/41231/12342"), 4, 20267013u), "시드 20267013(처음 세 색이 3,3,3)", "[3,3]", "11323/23412/34124/41231/12342"));

        Run("random-vs-reference", () =>
        {
            uint s = 4242u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            for (int t = 0; t < 400; t++)
            {
                int rows = 3 + rnd(5), cols = 3 + rnd(5);
                var cells = new int[rows, cols];
                for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) cells[r, c] = 1 + rnd(4);
                uint seed = 1u + (uint)rnd(1000000);
                var m = new Match3Board(cells, 4, seed);
                var re = new Ref { Cells = (int[,])cells.Clone(), Colors = 4, State = seed };
                for (int move = 0; move < 4; move++)
                {
                    string before = D(m);
                    string want = re.Resolve(), got = L(m.ResolveCascades());
                    var wb = new System.Text.StringBuilder();
                    for (int r = 0; r < rows; r++) { if (r > 0) wb.Append('/'); for (int c = 0; c < cols; c++) wb.Append((char)('0' + re.Cells[r, c])); }
                    if (got != want || D(m) != wb.ToString())
                        return "무작위 " + t + "번(시드 " + seed + ") " + move + "번째 수, 보드 " + before + ": 기대 " + want + " " + wb + " / 결과 " + got + " " + D(m);
                    int r1 = rnd(rows), c1 = rnd(cols - 1);   // 가로로 이웃한 두 칸을 맞바꾼다
                    m.Swap(r1, c1, r1, c1 + 1);
                    int tmp = re.Cells[r1, c1]; re.Cells[r1, c1] = re.Cells[r1, c1 + 1]; re.Cells[r1, c1 + 1] = tmp;
                }
            }
            return null;
        });
    }
}

