using System;

// xorshift32: 시프트 13, 17, 5. 상태가 0 이 되면 영원히 0 만 나오므로 시드 0 은 다른 값으로 바꾼다.
public sealed class XorShift32
{
    private uint _state;

    public XorShift32(uint seed) { _state = seed != 0 ? seed : 0x6D2B79F5u; }

    public uint NextUInt()
    {
        uint x = _state;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        return _state = x;
    }

    // 0 .. n-1. 나머지 대신 곱셈으로 범위를 줄인다(상위 비트를 쓴다).
    public int NextInt(int n) => (int)(((ulong)NextUInt() * (ulong)n) >> 32);
}

// SplitMix64: 상태에 Gamma 를 더한 뒤 Mix 로 섞은 값이 다음 출력이다.
public static class SplitMix64
{
    public const ulong Gamma = 0x9E3779B97F4A7C15UL;

    // 곱셈은 2^64 를 넘치며 계산해야 하므로 unchecked 로 감싼다(프로젝트에서 넘침 검사를 켜도 같은 결과).
    public static ulong Mix(ulong z)
    {
        unchecked
        {
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            return z ^ (z >> 31);
        }
    }
}

// 로그라이크 런 하나의 던전 생성기.
// 같은 런 시드라면 어떤 층을 어떤 순서로, 몇 번 만들든 같은 층은 같은 모양이어야 한다.
public sealed class DungeonRun
{
    private readonly ulong _runSeed;

    public DungeonRun(ulong runSeed) { _runSeed = runSeed; }

    // floor 층(1 이상)의 시드: runSeed 로 시작한 SplitMix64 수열의 floor 번째 출력(1부터)의 상위 32비트.
    // SplitMix64 의 상태는 출력마다 Gamma 씩 늘어날 뿐이므로, floor 번째 상태는 앞의 출력을 만들지 않고도
    // runSeed + floor * Gamma 로 바로 구할 수 있다(2^64 를 법으로 넘치며 계산한다).
    public uint FloorSeed(int floor)
    {
        ulong state = unchecked(_runSeed + (ulong)floor * SplitMix64.Gamma);
        return (uint)(SplitMix64.Mix(state) >> 32);
    }

    // floor 층 첫 줄의 타일 width 개.
    // 그 층 전용 XorShift32(FloorSeed(floor)) 에서 왼쪽 칸부터 NextInt(100) 을 하나씩 뽑아 바꾼다.
    // 0..59 '.'(바닥), 60..84 '#'(벽), 85..94 'm'(몬스터), 95..99 '$'(보물)
    public string GenerateRow(int floor, int width)
    {
        var rng = new XorShift32(FloorSeed(floor)); // 층마다 새 생성기: 다른 층에서 난수를 몇 개 썼는지와 무관하다
        var tiles = new char[width];
        for (int x = 0; x < width; x++)
        {
            int roll = rng.NextInt(100);             // 칸마다 정확히 한 번, 왼쪽부터
            tiles[x] = roll < 60 ? '.' : roll < 85 ? '#' : roll < 95 ? 'm' : '$';
        }
        return new string(tiles);
    }
}

