using System;
using System.Collections.Generic;

// 개발자 콘솔의 명령 자동 완성. 입력한 접두사로 시작하는 명령을 많이 쓴 순서로 추천한다.
public sealed class CommandAutocomplete
{
    // 이름은 서수 오름차순으로 정렬해 둔다. 그러면 같은 접두사로 시작하는 이름들이 연속 구간을 이룬다.
    private readonly string[] _names;
    private readonly int[] _uses;                       // _uses[i] = _names[i] 의 사용 횟수(바뀌는 값)
    private readonly Dictionary<string, int> _indexOf;  // 이름 -> 정렬된 위치

    public CommandAutocomplete(string[] names, int[] uses)
    {
        _names = (string[])names.Clone();               // 호출한 쪽 배열은 건드리지 않는다
        _uses = (int[])uses.Clone();
        Array.Sort(_names, _uses, StringComparer.Ordinal); // 기본 비교자는 현재 문화권 규칙이므로 서수 비교자를 명시한다
        _indexOf = new Dictionary<string, int>(_names.Length, StringComparer.Ordinal);
        for (int i = 0; i < _names.Length; i++) _indexOf.Add(_names[i], i);
    }

    public bool RecordUse(string name)
    {
        if (!_indexOf.TryGetValue(name, out int i)) return false;
        _uses[i]++;                                     // 정렬 순서는 이름만 보므로 횟수가 바뀌어도 그대로다
        return true;
    }

    public int CountWithPrefix(string prefix)
    {
        FindRange(prefix, out int lo, out int hi);
        return hi - lo;
    }

    public List<string> Suggest(string prefix, int n)
    {
        var result = new List<string>();
        if (n <= 0) return result;
        FindRange(prefix, out int lo, out int hi);

        // 크기 n 의 최소 힙. 루트 = 지금까지 고른 후보 중 가장 약한 것.
        // 우선순위 (사용 횟수, -위치): 횟수가 적을수록, 같으면 위치가 뒤일수록(= 이름이 서수로 클수록) 약하다.
        // 위치가 모두 다르므로 동률이 없고, PriorityQueue 의 동률 처리에 기대지 않는다.
        var heap = new PriorityQueue<int, (int uses, int negIndex)>(Math.Min(n, hi - lo) + 1);
        for (int i = lo; i < hi; i++)
        {
            var p = (_uses[i], -i);
            if (heap.Count < n) { heap.Enqueue(i, p); continue; }
            heap.TryPeek(out _, out var weakest);
            if (p.CompareTo(weakest) > 0) heap.EnqueueDequeue(i, p); // 더 강하면 가장 약한 것과 바꾼다
        }

        // 약한 것부터 나오므로 뒤에서부터 채운다.
        var picked = new string[heap.Count];
        for (int k = picked.Length - 1; k >= 0; k--) picked[k] = _names[heap.Dequeue()];
        result.AddRange(picked);
        return result;
    }

    // [lo, hi) = prefix 로 시작하는 이름의 구간. 이분 탐색 두 번.
    private void FindRange(string prefix, out int lo, out int hi)
    {
        lo = FirstIndex(prefix, strict: false); // ComparePrefix >= 0 인 첫 위치
        hi = FirstIndex(prefix, strict: true);  // ComparePrefix > 0 인 첫 위치
    }

    private int FirstIndex(string prefix, bool strict)
    {
        int lo = 0, hi = _names.Length;         // 답은 [lo, hi] 안에 있다(hi = "없음")
        while (lo < hi)
        {
            int mid = lo + (hi - lo) / 2;
            int c = ComparePrefix(_names[mid], prefix);
            if (strict ? c > 0 : c >= 0) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    // name 의 앞 prefix.Length 글자를 prefix 와 글자(UTF-16 코드 단위) 단위로 비교한다.
    // 음수: name 이 구간보다 앞, 0: name 이 prefix 로 시작, 양수: 구간보다 뒤.
    // 이름이 서수로 정렬되어 있으면 이 값은 앞에서 뒤로 줄어들지 않으므로 이분 탐색할 수 있다.
    private static int ComparePrefix(string name, string prefix)
    {
        for (int i = 0; i < prefix.Length; i++)
        {
            if (i == name.Length) return -1;   // name 이 prefix 의 앞부분이다: prefix 보다 앞
            if (name[i] != prefix[i]) return name[i] < prefix[i] ? -1 : 1;
        }
        return 0;
    }
}

