public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string J(System.Collections.Generic.List<string> list) => list == null ? "null" : "[" + string.Join(" ", list) + "]";

    static string Sug(CommandAutocomplete a, string prefix, int n, string expected)
    {
        string got = J(a.Suggest(prefix, n));
        return got == expected ? null : "Suggest(\"" + prefix + "\", " + n + ") 기대 " + expected + " / 결과 " + got;
    }

    static string Cnt(CommandAutocomplete a, string prefix, int expected)
    {
        int got = a.CountWithPrefix(prefix);
        return got == expected ? null : "CountWithPrefix(\"" + prefix + "\") 기대 " + expected + " / 결과 " + got;
    }

    static string Use(CommandAutocomplete a, string name, bool expected)
    {
        bool got = a.RecordUse(name);
        return got == expected ? null : "RecordUse(\"" + name + "\") 기대 " + expected + " / 결과 " + got;
    }

    static readonly string[] Names = { "speed", "give", "god", "give_all", "help", "spawn_boss", "goto", "give.gold", "heal", "spawn", "gravity", "spawn.wave" };
    static readonly int[] Uses = { 1, 5, 9, 2, 4, 0, 0, 5, 4, 7, 1, 3 };
    static CommandAutocomplete Console12() => new CommandAutocomplete((string[])Names.Clone(), (int[])Uses.Clone());

    // 기준 구현: 전부 훑어 접두사가 맞는 이름을 모으고 (횟수 내림차순, 서수 오름차순)으로 정렬한다.
    static string RefSuggest(string[] names, int[] uses, string prefix, int n)
    {
        var hits = new System.Collections.Generic.List<int>();
        for (int i = 0; i < names.Length; i++) if (names[i].StartsWith(prefix, System.StringComparison.Ordinal)) hits.Add(i);
        hits.Sort((x, y) => uses[x] != uses[y] ? uses[y].CompareTo(uses[x]) : string.CompareOrdinal(names[x], names[y]));
        var top = new System.Collections.Generic.List<string>();
        for (int k = 0; k < hits.Count && k < n; k++) top.Add(names[hits[k]]);
        return J(top);
    }

    static int RefCount(string[] names, string prefix)
    {
        int c = 0;
        foreach (var s in names) if (s.StartsWith(prefix, System.StringComparison.Ordinal)) c++;
        return c;
    }

    public static void Main()
    {
        // 채점 결과가 채점기의 문화권 설정에 좌우되지 않도록 현재 문화권을 en-US 로 고정한다.
        // 문화권 데이터를 쓸 수 없는 환경(세계화 고정 모드)이면 고정 문화권(InvariantCulture)을 쓴다.
        try { System.Globalization.CultureInfo.CurrentCulture = new System.Globalization.CultureInfo("en-US"); }
        catch (System.Globalization.CultureNotFoundException) { System.Globalization.CultureInfo.CurrentCulture = System.Globalization.CultureInfo.InvariantCulture; }

        Run("prefix-and-ranking", () =>
        {
            var a = Console12();
            return Sug(a, "g", 3, "[god give give.gold]") ?? Sug(a, "give", 5, "[give give.gold give_all]")
                ?? Sug(a, "sp", 10, "[spawn spawn.wave speed spawn_boss]") ?? Sug(a, "he", 1, "[heal]")
                ?? Sug(a, "", 4, "[god spawn give give.gold]");
        });

        Run("ties-by-ordinal-name", () =>
        {
            var a = new CommandAutocomplete(new[] { "tphome", "tp_home", "tp2", "tp", "tp.home", "tq" }, new[] { 1, 1, 1, 1, 1, 1 });
            return Sug(a, "tp", 10, "[tp tp.home tp2 tp_home tphome]") ?? Sug(a, "tp", 2, "[tp tp.home]") ?? Sug(a, "t", 6, "[tp tp.home tp2 tp_home tphome tq]");
        });

        Run("edge-prefixes-and-n", () =>
        {
            var a = Console12();
            string e = Sug(a, "help", 3, "[help]") ?? Sug(a, "helpme", 3, "[]") ?? Sug(a, "x", 3, "[]") ?? Sug(a, "a", 3, "[]")
                ?? Sug(a, "zz", 3, "[]") ?? Sug(a, "g", 0, "[]") ?? Sug(a, "gr", 99, "[gravity]");
            if (e != null) return e;
            var empty = new CommandAutocomplete(new string[0], new int[0]);
            return Sug(empty, "", 5, "[]") ?? Cnt(empty, "", 0) ?? Use(empty, "god", false);
        });

        Run("count-with-prefix", () =>
        {
            var a = Console12();
            return Cnt(a, "", 12) ?? Cnt(a, "g", 6) ?? Cnt(a, "give", 3) ?? Cnt(a, "spawn", 3) ?? Cnt(a, "h", 2)
                ?? Cnt(a, "spawn_boss_x", 0) ?? Cnt(a, "a", 0) ?? Cnt(a, "zz", 0) ?? Cnt(a, "speed", 1);
        });

        Run("record-use-reorders", () =>
        {
            var a = Console12();
            for (int i = 0; i < 10; i++) { string e0 = Use(a, "goto", true); if (e0 != null) return e0; }
            return Sug(a, "g", 3, "[goto god give]") ?? Use(a, "nope", false) ?? Use(a, "go", false)
                ?? Cnt(a, "go", 2) ?? Use(a, "give_all", true) ?? Use(a, "give_all", true) ?? Use(a, "give_all", true)
                ?? Sug(a, "give", 3, "[give give.gold give_all]") ?? Use(a, "give_all", true) ?? Sug(a, "give", 2, "[give_all give]");
        });

        Run("input-arrays-not-shared", () =>
        {
            var names = (string[])Names.Clone();
            var uses = (int[])Uses.Clone();
            var a = new CommandAutocomplete(names, uses);
            for (int i = 0; i < names.Length; i++)
                if (names[i] != Names[i] || uses[i] != Uses[i]) return "생성자가 호출한 쪽 배열을 바꿨다: names[" + i + "] = " + names[i] + ", uses[" + i + "] = " + uses[i];
            names[2] = "zzz"; uses[9] = 100;                 // 나중에 바꿔도 자동 완성은 영향을 받지 않아야 한다
            return Sug(a, "g", 1, "[god]") ?? Sug(a, "", 2, "[god spawn]") ?? Cnt(a, "z", 0);
        });

        Run("random-vs-reference", () =>
        {
            uint s = 8086u;
            System.Func<int, int> rnd = m => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)m); };
            const string alphabet = "ab_.1";
            System.Func<int, string> word = len => { var c = new char[len]; for (int i = 0; i < len; i++) c[i] = alphabet[rnd(alphabet.Length)]; return new string(c); };
            for (int t = 0; t < 300; t++)
            {
                var set = new System.Collections.Generic.HashSet<string>();
                int want = rnd(41);
                while (set.Count < want) set.Add(word(1 + rnd(4)));
                var names = new string[set.Count]; set.CopyTo(names);
                var uses = new int[names.Length];
                for (int i = 0; i < uses.Length; i++) uses[i] = rnd(4);
                var a = new CommandAutocomplete((string[])names.Clone(), (int[])uses.Clone());
                for (int op = 0; op < 60; op++)
                {
                    int kind = rnd(3);
                    string when = "무작위 " + t + "번 " + op + "번째 호출: ";
                    if (kind == 0)
                    {
                        string name = names.Length > 0 && rnd(4) > 0 ? names[rnd(names.Length)] : word(1 + rnd(4));
                        int idx = System.Array.IndexOf(names, name);
                        if (idx >= 0) uses[idx]++;
                        string e = Use(a, name, idx >= 0);
                        if (e != null) return when + e;
                    }
                    else
                    {
                        string prefix = word(rnd(4));
                        int n = rnd(6);
                        string e = kind == 1 ? Sug(a, prefix, n, RefSuggest(names, uses, prefix, n)) : Cnt(a, prefix, RefCount(names, prefix));
                        if (e != null) return when + e;
                    }
                }
            }
            return null;
        });

        Run("large-dictionary", () =>
        {
            uint s = 2026u;
            System.Func<int, int> rnd = m => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)m); };
            const string alphabet = "abcdefgh_.";
            var set = new System.Collections.Generic.HashSet<string>();
            while (set.Count < 60000)
            {
                int len = 3 + rnd(6); var c = new char[len];
                for (int i = 0; i < len; i++) c[i] = alphabet[rnd(alphabet.Length)];
                set.Add(new string(c));
            }
            var names = new string[set.Count]; set.CopyTo(names);
            var uses = new int[names.Length];
            for (int i = 0; i < uses.Length; i++) uses[i] = rnd(1000);
            var a = new CommandAutocomplete((string[])names.Clone(), (int[])uses.Clone());
            string[] prefixes = { "", "a", "h_", "bad", "ce.", "gggg", "zz", "._" };
            for (int round = 0; round < 3; round++)
            {
                foreach (string p in prefixes)
                {
                    string e = Sug(a, p, 10, RefSuggest(names, uses, p, 10)) ?? Cnt(a, p, RefCount(names, p));
                    if (e != null) return "6만 개 사전 " + round + "회차: " + e;
                }
                for (int k = 0; k < 200; k++) { int i = rnd(names.Length); uses[i] += 2; a.RecordUse(names[i]); a.RecordUse(names[i]); }
            }
            return null;
        });
    }
}

