using System;
using System.Collections.Generic;

// 레시피 한 줄: Output 한 개를 만드는 데 필요한 재료와 개수.
public sealed class Recipe
{
    public string Output { get; }
    public IReadOnlyList<(string item, int count)> Ingredients { get; }

    public Recipe(string output, params (string item, int count)[] ingredients)
    {
        Output = output;
        Ingredients = ingredients;
    }
}

// 제작 UI 가 아이템마다 "제작 가능" 표시와 필요 재료 툴팁을 정할 때 쓴다.
// 레시피가 없는 아이템은 기초 재료다. 레시피 데이터는 만든 뒤 바뀌지 않는다.
public sealed class CraftingResolver
{
    private readonly Dictionary<string, Recipe> _recipes = new Dictionary<string, Recipe>();

    // 계산이 끝난 아이템 -> 기초 재료 총량. 순환에 걸린 아이템은 null 로 기억한다(영구 표시).
    // 레시피가 바뀌지 않으므로 호출이 여러 번이어도 아이템마다 한 번만 계산한다.
    private readonly Dictionary<string, Dictionary<string, long>> _memo = new Dictionary<string, Dictionary<string, long>>();

    // 지금 DFS 경로 위에서 계산 중인 아이템(임시 표시). 여기에 다시 들어오면 순환이다.
    private readonly HashSet<string> _inProgress = new HashSet<string>();

    public CraftingResolver(IEnumerable<Recipe> recipes)
    {
        foreach (var r in recipes) _recipes.Add(r.Output, r); // 아이템마다 레시피는 하나뿐이다
    }

    // item 한 개를 기초 재료부터 만들 때 필요한 기초 재료별 총량.
    // 기초 재료 자신은 { item: 1 }. 순환에 걸린 아이템을 거쳐야 하면 null.
    public IReadOnlyDictionary<string, long> BaseCost(string item) => Cost(item);

    // 인벤토리(기초 재료만 들어 있다)로 item 을 count 개 만들 수 있는가. 인벤토리는 바꾸지 않는다.
    public bool CanCraft(string item, long count, IReadOnlyDictionary<string, long> inventory)
    {
        var cost = Cost(item);
        if (cost == null) return false;
        // 같은 기초 재료가 여러 하위 레시피에 쓰여도 cost 에는 합계가 들어 있다: 합계와 한 번 비교한다.
        foreach (var need in cost)
        {
            inventory.TryGetValue(need.Key, out long have);
            if (have < count * need.Value) return false;
        }
        return true;
    }

    // 레시피 깊이는 시나리오가 200 이하로 보장하므로 재귀로 쓴다.
    private Dictionary<string, long> Cost(string item)
    {
        if (_memo.TryGetValue(item, out var known)) return known;   // 끝난 아이템(null 이면 순환)

        if (!_recipes.TryGetValue(item, out var recipe))
        {
            var self = new Dictionary<string, long> { [item] = 1 };  // 기초 재료
            _memo[item] = self;
            return self;
        }

        if (!_inProgress.Add(item)) return null;                     // 경로 위의 아이템을 다시 만남: 순환

        var total = new Dictionary<string, long>();
        foreach (var (ingredient, count) in recipe.Ingredients)
        {
            var sub = Cost(ingredient);
            if (sub == null) { total = null; break; }               // 순환을 거쳐야 하면 이 아이템도 불가
            foreach (var part in sub)                                // 하위 결과(메모)는 고치지 않고 새 사전에 더한다
            {
                total.TryGetValue(part.Key, out long sum);
                total[part.Key] = sum + count * part.Value;
            }
        }

        _inProgress.Remove(item);
        _memo[item] = total;
        return total;
    }
}

