public static class __Judge
{
    // 케이스마다 별도 배경 스레드에서 실행하고, 제한 시간 안에 끝나지 않으면 그 케이스만 실패로 적는다.
    // (끝나지 않는 반복이 있어도 다음 케이스는 계속 실행되고, 배경 스레드는 Main 이 끝날 때 함께 끝난다.)
    static void RunTimed(string id, int ms, System.Func<string> body, string timeoutReason)
    {
        string err = null;
        var t = new System.Threading.Thread(() =>
        {
            try { err = body(); }
            catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        });
        t.IsBackground = true;
        t.Start();
        if (!t.Join(ms)) { System.Console.WriteLine("[FAIL] " + id + " :: " + ms + " ms 안에 끝나지 않음(" + timeoutReason + ")"); return; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static void Run(string id, System.Func<string> body) => RunTimed(id, 1000, body, "끝나지 않는 반복으로 보임");

    static void RunTimed(string id, int ms, System.Func<string> body) => RunTimed(id, ms, body, "같은 하위 레시피를 경로마다 다시 계산하는 것으로 보임");

    static Recipe R(string output, params (string, int)[] ingredients) => new Recipe(output, ingredients);

    // 사전을 "coal:3 iron_ore:6" 처럼 키의 서수 순서로 적는다. null 이면 "null".
    static string D(System.Collections.Generic.IReadOnlyDictionary<string, long> d)
    {
        if (d == null) return "null";
        var keys = new System.Collections.Generic.List<string>(d.Keys);
        keys.Sort(string.CompareOrdinal);
        var sb = new System.Text.StringBuilder();
        foreach (var k in keys) { if (sb.Length > 0) sb.Append(' '); sb.Append(k).Append(':').Append(d[k]); }
        return sb.ToString();
    }

    static System.Collections.Generic.Dictionary<string, long> Inv(params (string, long)[] items)
    {
        var d = new System.Collections.Generic.Dictionary<string, long>();
        foreach (var (k, v) in items) d[k] = v;
        return d;
    }

    static string Cost(CraftingResolver r, string item, string expected)
    {
        string got = D(r.BaseCost(item));
        return got == expected ? null : "BaseCost(" + item + ") 기대 [" + expected + "] / 결과 [" + got + "]";
    }

    static string Can(CraftingResolver r, string item, long count, System.Collections.Generic.Dictionary<string, long> inv, bool expected)
    {
        string before = D(inv);
        bool got = r.CanCraft(item, count, inv);
        if (D(inv) != before) return "CanCraft(" + item + ", " + count + ") 가 인벤토리를 바꿨음: [" + before + "] -> [" + D(inv) + "]";
        return got == expected ? null : "CanCraft(" + item + ", " + count + ", [" + before + "]) 기대 " + expected + " / 결과 " + got;
    }

    // 시나리오의 레시피 표
    static CraftingResolver Book() => new CraftingResolver(new[]
    {
        R("plank", ("log", 2)), R("stick", ("plank", 1)),
        R("iron_ingot", ("iron_ore", 2), ("coal", 1)),
        R("handle", ("stick", 2), ("leather", 1)),
        R("iron_sword", ("iron_ingot", 3), ("handle", 1)),
        R("torch", ("stick", 1), ("coal", 1)),
        R("lantern", ("iron_ingot", 1), ("torch", 1)),
    });

    // 기준 구현: 메모 없이 경로 집합만으로 순환을 찾는 재귀(작은 데이터에서만 쓴다).
    static System.Collections.Generic.Dictionary<string, long> RefCost(System.Collections.Generic.Dictionary<string, (string, int)[]> rec, string item, System.Collections.Generic.HashSet<string> path)
    {
        if (!rec.TryGetValue(item, out var ings)) return new System.Collections.Generic.Dictionary<string, long> { [item] = 1 };
        if (!path.Add(item)) return null;
        var total = new System.Collections.Generic.Dictionary<string, long>();
        foreach (var (ing, c) in ings)
        {
            var sub = RefCost(rec, ing, path);
            if (sub == null) { path.Remove(item); return null; }
            foreach (var kv in sub) { total.TryGetValue(kv.Key, out long s); total[kv.Key] = s + c * kv.Value; }
        }
        path.Remove(item);
        return total;
    }

    public static void Main()
    {
        Run("base-material-and-unknown-item", () =>
        {
            var r = Book();
            return Cost(r, "log", "log:1") ?? Cost(r, "leather", "leather:1") ?? Cost(r, "dragon_scale", "dragon_scale:1")
                ?? Can(r, "log", 3, Inv(("log", 3)), true) ?? Can(r, "log", 4, Inv(("log", 3)), false)
                ?? Can(r, "dragon_scale", 1, Inv(("log", 9)), false);
        });

        Run("nested-quantities-multiply", () =>
        {
            var r = Book();
            return Cost(r, "stick", "log:2") ?? Cost(r, "iron_sword", "coal:3 iron_ore:6 leather:1 log:4")
                ?? Cost(r, "torch", "coal:1 log:2") ?? Cost(r, "handle", "leather:1 log:4")
                ?? Can(r, "iron_sword", 1, Inv(("iron_ore", 6), ("coal", 3), ("log", 4), ("leather", 1)), true)
                ?? Can(r, "iron_sword", 1, Inv(("iron_ore", 6), ("coal", 2), ("log", 4), ("leather", 1)), false)
                ?? Can(r, "iron_sword", 2, Inv(("iron_ore", 12), ("coal", 6), ("log", 7), ("leather", 2)), false);
        });

        Run("shared-base-material-counted-once", () =>
        {
            var r = Book();
            // 랜턴: 철 주괴의 석탄 1 + 횃불의 석탄 1. 가지마다 따로 확인하면 석탄 1개로도 된다고 잘못 답한다.
            return Cost(r, "lantern", "coal:2 iron_ore:2 log:2")
                ?? Can(r, "lantern", 1, Inv(("coal", 1), ("iron_ore", 2), ("log", 2)), false)
                ?? Can(r, "lantern", 1, Inv(("coal", 2), ("iron_ore", 2), ("log", 2)), true)
                ?? Can(r, "lantern", 3, Inv(("coal", 6), ("iron_ore", 6), ("log", 6), ("leather", 5)), true)
                ?? Can(r, "lantern", 3, Inv(("coal", 6), ("iron_ore", 6), ("log", 5)), false);
        });

        Run("diamond-is-not-a-cycle", () =>
        {
            var r = new CraftingResolver(new[]
            {
                R("strip", ("cloth", 1)), R("bandage", ("strip", 2)), R("splint", ("strip", 1), ("stick", 1)),
                R("stick", ("plank", 1)), R("plank", ("log", 2)), R("kit", ("bandage", 1), ("splint", 1)),
                R("strap", ("strip", 1), ("strip", 2)),   // 같은 재료가 두 줄: 합친다
                R("pack", ("kit", 2), ("strap", 1), ("kit", 1)),
            });
            return Cost(r, "kit", "cloth:3 log:2") ?? Cost(r, "bandage", "cloth:2") ?? Cost(r, "splint", "cloth:1 log:2")
                ?? Cost(r, "strap", "cloth:3") ?? Cost(r, "pack", "cloth:12 log:6")
                ?? Can(r, "pack", 1, Inv(("cloth", 12), ("log", 6)), true) ?? Can(r, "pack", 1, Inv(("cloth", 11), ("log", 6)), false);
        });

        Run("repeated-queries-stay-correct", () =>
        {
            // 상위 아이템을 먼저 계산한 뒤 하위 아이템과 그것을 쓰는 다른 아이템을 물어도 값이 그대로여야 한다.
            var r = Book();
            return Cost(r, "lantern", "coal:2 iron_ore:2 log:2") ?? Cost(r, "iron_ingot", "coal:1 iron_ore:2")
                ?? Cost(r, "torch", "coal:1 log:2") ?? Cost(r, "iron_sword", "coal:3 iron_ore:6 leather:1 log:4")
                ?? Cost(r, "handle", "leather:1 log:4") ?? Cost(r, "stick", "log:2") ?? Cost(r, "plank", "log:2")
                ?? Cost(r, "lantern", "coal:2 iron_ore:2 log:2") ?? Cost(r, "log", "log:1")
                ?? Can(r, "iron_ingot", 2, Inv(("iron_ore", 4), ("coal", 2)), true);
        });

        RunTimed("deep-shared-recipes-in-time", 2000, () =>
        {
            // 단계 k: top_k <- left_k + right_k, left_k <- top_(k-1), right_k <- top_(k-1). top_0 <- ore. 40단계면 광석 2^40 개.
            var list = new System.Collections.Generic.List<Recipe> { R("top_0", ("ore", 1)) };
            for (int k = 1; k <= 40; k++)
            {
                list.Add(R("top_" + k, ("left_" + k, 1), ("right_" + k, 1)));
                list.Add(R("left_" + k, ("top_" + (k - 1), 1)));
                list.Add(R("right_" + k, ("top_" + (k - 1), 1)));
            }
            for (int k = 1; k <= 199; k++) list.Add(R("chain_" + k, ("chain_" + (k - 1), 1)));   // chain_199 에서 광석까지 200단계
            list.Add(R("chain_0", ("ore", 3)));
            var r = new CraftingResolver(list);
            long need = 1L << 40;
            return Cost(r, "top_40", "ore:" + need) ?? Cost(r, "top_39", "ore:" + (need / 2))
                ?? Can(r, "top_40", 1, Inv(("ore", need)), true) ?? Can(r, "top_40", 1, Inv(("ore", need - 1)), false)
                ?? Cost(r, "chain_199", "ore:3");
        });

        Run("cycles-are-uncraftable", () =>
        {
            var r = new CraftingResolver(new[]
            {
                R("fine", ("log", 1)), R("a", ("b", 1)), R("b", ("log", 1), ("a", 1)), R("ouroboros", ("ouroboros", 1)),
                R("needs_cycle", ("fine", 1), ("b", 2)), R("cycle_first", ("a", 1), ("late", 1)), R("late", ("log", 4)),
            });
            return Cost(r, "fine", "log:1") ?? Cost(r, "a", "null") ?? Cost(r, "b", "null") ?? Cost(r, "ouroboros", "null")
                ?? Cost(r, "needs_cycle", "null") ?? Cost(r, "cycle_first", "null")
                ?? Can(r, "needs_cycle", 1, Inv(("log", 100)), false) ?? Can(r, "a", 1, Inv(("log", 100)), false)
                ?? Cost(r, "late", "log:4") ?? Cost(r, "fine", "log:1") ?? Can(r, "late", 2, Inv(("log", 8)), true);
        });

        Run("random-vs-reference", () =>
        {
            uint s = 20261122u;
            System.Func<int, int> rnd = m => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)m); };
            for (int t = 0; t < 300; t++)
            {
                int n = 3 + rnd(7);
                var rec = new System.Collections.Generic.Dictionary<string, (string, int)[]>();
                var list = new System.Collections.Generic.List<Recipe>();
                for (int i = 0; i < n; i++)
                {
                    if (rnd(100) < 20) continue;                              // 레시피 없는 아이템 = 기초 재료
                    var ings = new (string, int)[1 + rnd(3)];
                    for (int j = 0; j < ings.Length; j++)
                    {
                        int pick = rnd(100);
                        string ing;
                        if (pick < 35 || (i == 0 && pick < 90)) ing = "b" + rnd(3);   // 기초 재료
                        else if (pick < 90) ing = "i" + rnd(i);                       // 앞쪽 아이템(순환 없음)
                        else ing = "i" + (i + rnd(n - i));                            // 자기 자신이나 뒤쪽 아이템(순환이 생길 수 있음)
                        ings[j] = (ing, 1 + rnd(3));
                    }
                    rec["i" + i] = ings;
                    list.Add(new Recipe("i" + i, ings));
                }
                var r = new CraftingResolver(list);
                for (int q = 0; q < 2 * n; q++)
                {
                    string item = "i" + rnd(n);
                    var want = RefCost(rec, item, new System.Collections.Generic.HashSet<string>());
                    string e = Cost(r, item, D(want));
                    if (e != null) return "무작위 " + t + "회차: " + e;
                    var inv = Inv(("b0", rnd(40)), ("b1", rnd(40)), ("b2", rnd(40)));
                    string other = "i" + rnd(n);
                    if (!rec.ContainsKey(other)) inv[other] = rnd(5);              // 레시피 없는 아이템도 기초 재료다
                    long cnt = 1 + rnd(3);
                    bool ok = want != null;
                    if (ok) foreach (var kv in want) { inv.TryGetValue(kv.Key, out long have); if (have < cnt * kv.Value) ok = false; }
                    e = Can(r, item, cnt, inv, ok);
                    if (e != null) return "무작위 " + t + "회차: " + e;
                }
            }
            return null;
        });
    }
}

