using System;
using System.Collections.Generic;

public sealed class Combatant
{
    public int Id { get; }
    public bool IsAlly { get; }
    public int Slot { get; }          // 진영 안의 자리 번호. (IsAlly, Slot) 조합은 유닛마다 다르다
    public int Speed { get; set; }
    public bool Alive { get; set; } = true;

    public Combatant(int id, bool isAlly, int slot, int speed)
    {
        Id = id; IsAlly = isAlly; Slot = slot; Speed = speed;
    }
}

// 라운드제 턴 순서. 전투 코드는 속도와 생존 상태를 반드시 SetSpeed / Kill 로 바꾼다.
public sealed class InitiativeTracker
{
    private readonly List<Combatant> _all;
    private readonly List<Combatant> _order = new List<Combatant>(); // 이번 라운드의 행동 순서
    private int _cursor;                                             // 다음에 행동할 위치

    public InitiativeTracker(IEnumerable<Combatant> combatants)
    {
        _all = new List<Combatant>(combatants);
    }

    public void BeginRound()
    {
        _order.Clear();
        foreach (var c in _all)
            if (c.Alive) _order.Add(c);
        _order.Sort(CompareInitiative);
        _cursor = 0;
    }

    // 속도가 높은 순, 같으면 아군 먼저, 같은 진영이면 슬롯 번호가 작은 순.
    private static int CompareInitiative(Combatant a, Combatant b)
    {
        if (a.Speed != b.Speed) return b.Speed.CompareTo(a.Speed);
        if (a.IsAlly != b.IsAlly) return a.IsAlly.CompareTo(b.IsAlly);
        return a.Slot.CompareTo(b.Slot);
    }

    // 이번 라운드에 다음으로 행동할 유닛의 Id. 남은 유닛이 없으면 -1.
    public int Next()
    {
        while (_cursor < _order.Count)
        {
            var c = _order[_cursor++];
            if (c.Alive) return c.Id;
        }
        return -1;
    }

    public void SetSpeed(int id, int speed)
    {
        Find(id).Speed = speed;
    }

    public void Kill(int id)
    {
        var c = Find(id);
        c.Alive = false;
        _order.Remove(c);
    }

    private Combatant Find(int id)
    {
        foreach (var c in _all)
            if (c.Id == id) return c;
        throw new ArgumentException("없는 유닛: " + id);
    }
}

