public static class __Judge
{
    // 케이스마다 별도 배경 스레드에서 실행하고, 제한 시간 안에 끝나지 않으면 그 케이스만 실패로 적는다.
    // (끝나지 않는 반복이 있어도 다음 케이스는 계속 실행되고, 배경 스레드는 Main 이 끝날 때 함께 끝난다.)
    static void RunTimed(string id, int ms, System.Func<string> body, string timeoutReason)
    {
        string err = null;
        var t = new System.Threading.Thread(() =>
        {
            try { err = body(); }
            catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        });
        t.IsBackground = true;
        t.Start();
        if (!t.Join(ms)) { System.Console.WriteLine("[FAIL] " + id + " :: " + ms + " ms 안에 끝나지 않음(" + timeoutReason + ")"); return; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static void Run(string id, System.Func<string> body) => RunTimed(id, 1000, body, "끝나지 않는 반복으로 보임");

    // "A0:10 E1:9" 처럼 이름(A=아군, E=적, 숫자=슬롯)과 속도로 전투를 만든다. Id 는 이름과 무관한 값이다.
    sealed class Battle
    {
        public readonly InitiativeTracker T;
        readonly System.Collections.Generic.Dictionary<int, string> _name = new System.Collections.Generic.Dictionary<int, string>();
        readonly System.Collections.Generic.Dictionary<string, int> _id = new System.Collections.Generic.Dictionary<string, int>();
        public readonly System.Text.StringBuilder Log = new System.Text.StringBuilder();

        public Battle(string spec)
        {
            var list = new System.Collections.Generic.List<Combatant>();
            string[] parts = spec.Split(' ');
            for (int i = 0; i < parts.Length; i++)
            {
                string[] kv = parts[i].Split(':');
                int id = 40 - 3 * i;
                _name[id] = kv[0]; _id[kv[0]] = id;
                list.Add(new Combatant(id, kv[0][0] == 'A', kv[0][1] - '0', int.Parse(kv[1], System.Globalization.CultureInfo.InvariantCulture)));
            }
            T = new InitiativeTracker(list);
        }

        public string Next() { int id = T.Next(); return id == -1 ? "-" : (_name.TryGetValue(id, out var n) ? n : "?" + id); }
        public string Take(int k) { var sb = new System.Text.StringBuilder(); for (int i = 0; i < k; i++) { if (i > 0) sb.Append(' '); sb.Append(Next()); } return sb.ToString(); }
        public void Speed(string n, int s) { Log.Append(" 속도(" + n + "→" + s + ")"); T.SetSpeed(_id[n], s); }
        public void Kill(string n) { Log.Append(" 사망(" + n + ")"); T.Kill(_id[n]); }
        public string Expect(string got, string want, string what)
        {
            if (got == want) return null;
            string log = Log.Length > 180 ? "…" + Log.ToString(Log.Length - 180, 180) : Log.ToString();
            return what + (log.Length > 0 ? " (지금까지:" + log + ")" : "") + " 기대 [" + want + "] / 결과 [" + got + "]";
        }
    }

    public static void Main()
    {
        Run("round-order-by-speed", () =>
        {
            var b = new Battle("A0:7 A1:12 A2:3 E0:9 E1:15 E2:1");
            b.T.BeginRound();
            string e = b.Expect(b.Take(8), "E1 A1 E0 A0 A2 E2 - -", "1라운드");
            if (e != null) return e;
            b.T.BeginRound();
            return b.Expect(b.Take(7), "E1 A1 E0 A0 A2 E2 -", "2라운드");
        });

        Run("speed-tie-allies-before-enemies", () =>
        {
            var b = new Battle("E0:10 A2:10 A0:10 E1:12 A1:8 E2:10");
            b.T.BeginRound();
            string e = b.Expect(b.Take(7), "E1 A0 A2 E0 E2 A1 -", "속도 12 / 10 / 8, 속도 10 은 아군 둘과 적 둘");
            if (e != null) return e;
            var c = new Battle("E3:5 A1:5 E0:5 A0:5");
            c.T.BeginRound();
            return c.Expect(c.Take(5), "A0 A1 E0 E3 -", "모두 속도 5");
        });

        Run("haste-and-slow-apply-this-round", () =>
        {
            var b = new Battle("A0:10 A1:8 A2:6 E0:9 E1:7");
            b.T.BeginRound();
            string e = b.Expect(b.Next(), "A0", "첫 행동");
            if (e != null) return e;
            b.Speed("A2", 12);
            b.Speed("E0", 1);
            e = b.Expect(b.Take(5), "A2 A1 E1 E0 -", "A0 행동 후");
            if (e != null) return e;
            b.T.BeginRound();
            return b.Expect(b.Take(6), "A2 A0 A1 E1 E0 -", "다음 라운드(바뀐 속도 유지)");
        });

        Run("acted-unit-does-not-act-again", () =>
        {
            var b = new Battle("A0:10 E0:9 A1:8 E1:7");
            b.T.BeginRound();
            string e = b.Expect(b.Next(), "A0", "첫 행동");
            if (e != null) return e;
            b.Speed("A0", 1);                      // 이미 행동한 유닛을 느리게
            e = b.Expect(b.Take(2), "E0 A1", "A0 행동 후");
            if (e != null) return e;
            b.Speed("A1", 30);                     // 이미 행동한 유닛을 빠르게
            e = b.Expect(b.Take(2), "E1 -", "A0 · E0 · A1 행동 후");
            if (e != null) return e;
            b.T.BeginRound();
            return b.Expect(b.Take(5), "A1 E0 E1 A0 -", "다음 라운드");
        });

        Run("dead-units-do-not-act", () =>
        {
            var b = new Battle("A0:10 E0:9 A1:8 E1:7 E2:2");
            b.T.BeginRound();
            b.Kill("E1");                          // 아직 행동하지 않은 유닛
            string e = b.Expect(b.Next(), "A0", "라운드 시작 직후");
            if (e != null) return e;
            b.Kill("E0");                          // 바로 다음 차례였던 유닛
            b.Kill("E0");                          // 두 번 죽여도 아무 일 없음
            b.Speed("E0", 99);                     // 죽은 유닛의 속도가 바뀌어도 살아나지 않음
            e = b.Expect(b.Take(3), "A1 E2 -", "A0 행동 후");
            if (e != null) return e;
            b.T.BeginRound();
            return b.Expect(b.Take(4), "A0 A1 E2 -", "다음 라운드");
        });

        Run("acted-unit-dies-no-turn-skipped", () =>
        {
            var b = new Battle("A0:10 E0:9 A1:8 E1:7 A2:5");
            b.T.BeginRound();
            string e = b.Expect(b.Next(), "A0", "첫 행동");
            if (e != null) return e;
            b.Kill("A0");                          // 방금 행동한 유닛이 반격으로 사망
            e = b.Expect(b.Take(2), "E0 A1", "A0 행동 후");
            if (e != null) return e;
            b.Kill("E0");                          // 앞서 행동한 유닛이 나중에 사망
            e = b.Expect(b.Take(3), "E1 A2 -", "A0 · E0 · A1 행동 후");
            if (e != null) return e;
            b.T.BeginRound();
            return b.Expect(b.Take(4), "A1 E1 A2 -", "다음 라운드");
        });

        Run("random-vs-reference", () =>
        {
            uint s = 4242u;
            System.Func<int, int> rnd = m => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)m); };
            for (int t = 0; t < 300; t++)
            {
                int allies = 1 + rnd(4), enemies = 1 + rnd(6), n = allies + enemies;
                var speed = new int[n]; var alive = new bool[n]; var acted = new bool[n]; var ally = new bool[n]; var slot = new int[n];
                var sb = new System.Text.StringBuilder();
                for (int i = 0; i < n; i++)
                {
                    ally[i] = i < allies; slot[i] = ally[i] ? i : i - allies; speed[i] = 1 + rnd(6); alive[i] = true;
                    if (i > 0) sb.Append(' ');
                    sb.Append(ally[i] ? 'A' : 'E').Append(slot[i]).Append(':').Append(speed[i]);
                }
                var b = new Battle(sb.ToString());
                System.Func<int, string> nm = i => (ally[i] ? "A" : "E") + slot[i];
                b.T.BeginRound();
                for (int step = 0; step < 40; step++)
                {
                    int op = rnd(10), u = rnd(n);
                    if (op < 6)
                    {
                        int best = -1;   // 기준: 아직 행동하지 않은 살아 있는 유닛 중 (속도↓, 아군 먼저, 슬롯↑) 첫 번째
                        for (int i = 0; i < n; i++)
                            if (alive[i] && !acted[i] && (best < 0 || speed[i] > speed[best] || (speed[i] == speed[best] && (ally[i] && !ally[best] || ally[i] == ally[best] && slot[i] < slot[best])))) best = i;
                        string want = best < 0 ? "-" : nm(best);
                        string e = b.Expect(b.Next(), want, "무작위 " + t + "회차 [" + sb + "]");
                        if (e != null) return e;
                        b.Log.Append(" " + want);
                        if (best >= 0) acted[best] = true;
                        else { b.T.BeginRound(); b.Log.Append(" |새 라운드|"); for (int i = 0; i < n; i++) acted[i] = false; }
                    }
                    else if (op < 9) { speed[u] = 1 + rnd(6); b.Speed(nm(u), speed[u]); }
                    else if (alive[u]) { alive[u] = false; b.Kill(nm(u)); }
                }
            }
            return null;
        });
    }
}

