problems.solutionCode:
using System;
using System.Collections.Generic;

// 최근 windowMs 밀리초 동안 들어온 피해량으로 DPS 를 보여 주는 미터.
public sealed class DpsMeter
{
    private readonly long _windowMs;

    // 창 안의 기록을 시각 순서대로 든다. 시각이 줄지 않으므로 가장 오래된 기록이 언제나 맨 앞이다.
    private readonly Queue<(long time, int damage)> _events = new Queue<(long time, int damage)>();

    // 큐에 든 피해의 합. 정수로 들어 더하고 빼도 오차가 없다(int.MaxValue 피해를 약 42억 번 더해도 long 은 넘치지 않는다).
    private long _sum;

    public DpsMeter(long windowMs)
    {
        if (windowMs <= 0) throw new ArgumentOutOfRangeException(nameof(windowMs));
        _windowMs = windowMs;
    }

    // 피해 한 번을 기록한다. timeMs 는 앞선 모든 호출(Record, DamageInWindow, Dps)의 시각 이상이고, damage 는 0 이상이다.
    public void Record(long timeMs, int damage)
    {
        _events.Enqueue((timeMs, damage));
        _sum += damage;
        Evict(timeMs); // 질의가 없어도 창 밖 기록을 버려 메모리를 창 크기로 묶는다
    }

    // 시각이 (nowMs - windowMs, nowMs] 에 드는 피해의 합. nowMs 도 앞선 모든 호출의 시각 이상이다.
    public long DamageInWindow(long nowMs)
    {
        Evict(nowMs); // 마지막 타격 뒤에 시간만 흐른 경우에도 값이 떨어져야 한다
        return _sum;
    }

    // DamageInWindow(nowMs) 를 창 길이(초)로 나눈 값.
    public double Dps(long nowMs) => DamageInWindow(nowMs) * 1000.0 / _windowMs;

    // 지금 들고 있는 기록 항목 수. 같은 시각의 기록을 하나로 합쳐 들어도 된다.
    public int BufferedCount => _events.Count;

    // 시각이 nowMs - windowMs 이하인 기록은 창 밖이다. 기록마다 한 번 들어오고 한 번 나가므로 분할 상환 O(1).
    private void Evict(long nowMs)
    {
        long cutoff = nowMs - _windowMs;
        while (_events.TryPeek(out var oldest) && oldest.time <= cutoff)
        {
            _events.Dequeue();
            _sum -= oldest.damage;
        }
    }
}

