public static class __Judge
{
    // 케이스마다 별도 배경 스레드에서 실행하고, 제한 시간 안에 끝나지 않으면 그 케이스만 실패로 적는다.
    // (끝나지 않는 반복이 있어도 다음 케이스는 계속 실행되고, 배경 스레드는 Main 이 끝날 때 함께 끝난다.)
    static void RunTimed(string id, int ms, System.Func<string> body, string timeoutReason)
    {
        string err = null;
        var t = new System.Threading.Thread(() =>
        {
            try { err = body(); }
            catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        });
        t.IsBackground = true;
        t.Start();
        if (!t.Join(ms)) { System.Console.WriteLine("[FAIL] " + id + " :: " + ms + " ms 안에 끝나지 않음(" + timeoutReason + ")"); return; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static void Run(string id, System.Func<string> body) => RunTimed(id, 1000, body, "끝나지 않는 반복으로 보임");

    static void RunTimed(string id, int ms, System.Func<string> body) => RunTimed(id, ms, body, "질의마다 창 전체를 훑거나 앞에서 지우는 데 O(창 크기)가 드는 것으로 보임");

    static string Sum(DpsMeter m, long now, long expected)
    {
        long got = m.DamageInWindow(now);
        return got == expected ? null : "DamageInWindow(" + now + ") 기대 " + expected + " / 결과 " + got;
    }

    static string Dps(DpsMeter m, long now, double expected)
    {
        double got = m.Dps(now);
        return System.Math.Abs(got - expected) <= 1e-9 * System.Math.Max(1.0, System.Math.Abs(expected)) ? null
            : "Dps(" + now + ") 기대 " + expected.ToString("R", System.Globalization.CultureInfo.InvariantCulture) + " / 결과 " + got.ToString("R", System.Globalization.CultureInfo.InvariantCulture);
    }

    static string Buffered(DpsMeter m, int atMost, string when)
    {
        int got = m.BufferedCount;
        return got <= atMost ? null : when + ": BufferedCount 는 창 안의 기록 수 " + atMost + " 이하여야 함 / 결과 " + got;
    }

    public static void Main()
    {
        Run("window-boundary", () =>
        {
            var m = new DpsMeter(5000);
            m.Record(1000, 100); m.Record(3000, 50); m.Record(5999, 10);
            return Sum(m, 5999, 160) ?? Dps(m, 5999, 32.0)
                ?? Sum(m, 6000, 60)     // 1000 은 6000 - 5000 이하라 창 밖
                ?? Sum(m, 7999, 60) ?? Sum(m, 8000, 10) ?? Sum(m, 10998, 10) ?? Sum(m, 10999, 0) ?? Dps(m, 10999, 0.0);
        });

        Run("drops-after-combat-without-new-hits", () =>
        {
            var m = new DpsMeter(3000);
            for (long t = 0; t < 1000; t += 100) m.Record(t, 30);   // 0 ~ 900ms 에 10번
            return Sum(m, 900, 300) ?? Dps(m, 900, 100.0)
                ?? Sum(m, 3000, 270) ?? Sum(m, 3450, 150) ?? Dps(m, 3450, 50.0)
                ?? Sum(m, 3900, 0) ?? Buffered(m, 0, "마지막 타격 3초 뒤") ?? Sum(m, 60000, 0);
        });

        Run("same-timestamp-hits", () =>
        {
            var m = new DpsMeter(1000);
            m.Record(2000, 5); m.Record(2000, 5); m.Record(2000, 5); m.Record(2000, 7);  // 다단 히트
            string e = Sum(m, 2000, 22) ?? Sum(m, 2999, 22) ?? Buffered(m, 4, "2999ms");
            if (e != null) return e;
            m.Record(2999, 0);                                                         // 빗나감(0 피해)도 기록이다
            return Sum(m, 2999, 22) ?? Sum(m, 3000, 0) ?? Buffered(m, 1, "3000ms");
        });

        Run("units-and-large-totals", () =>
        {
            var a = new DpsMeter(2500);
            a.Record(0, 1000);
            string e = Dps(a, 0, 400.0) ?? Dps(a, 2499, 400.0) ?? Dps(a, 2500, 0.0);
            if (e != null) return e;
            var b = new DpsMeter(60000);
            for (int i = 0; i < 4; i++) b.Record(10 + i, int.MaxValue);              // 합이 int 범위를 넘는다
            return Sum(b, 20, 4L * int.MaxValue) ?? Dps(b, 20, 4.0 * int.MaxValue / 60.0);
        });

        Run("buffer-stays-window-sized", () =>
        {
            var m = new DpsMeter(1000);
            for (long t = 0; t < 1000000; t += 10)
            {
                m.Record(t, 1);
                if (t % 50000 == 0)
                {
                    long inWindow = System.Math.Min(t / 10 + 1, 100);
                    string e = Sum(m, t, inWindow) ?? Buffered(m, (int)inWindow, t + "ms");
                    if (e != null) return e;
                }
            }
            return Buffered(m, 100, "100,000번 기록 뒤");
        });

        Run("random-vs-reference", () =>
        {
            uint s = 77777u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            for (int run = 0; run < 300; run++)
            {
                long window = 1 + rnd(2000);
                var m = new DpsMeter(window);
                var all = new System.Collections.Generic.List<(long t, int d)>();
                long now = rnd(100);
                for (int step = 0; step < 80; step++)
                {
                    now += rnd(4) == 0 ? rnd(3000) : rnd(40);
                    if (rnd(3) != 0) { int d = rnd(1000); m.Record(now, d); all.Add((now, d)); }
                    else
                    {
                        long want = 0; int inWin = 0;
                        foreach (var x in all) if (x.t > now - window && x.t <= now) { want += x.d; inWin++; }
                        string e = Sum(m, now, want) ?? Dps(m, now, want * 1000.0 / window) ?? Buffered(m, inWin, "창 " + window + "ms, " + now + "ms");
                        if (e != null) return "무작위 " + run + "회차: " + e;
                    }
                }
            }
            return null;
        });

        RunTimed("two-million-hits-in-time", 2000, () =>
        {
            var m = new DpsMeter(1000000);                 // 창 1,000초: 창 안에 기록이 100만 개까지 쌓인다
            long want = 0;
            for (long t = 0; t < 2000000; t++)
            {
                m.Record(t, 3);
                want += 3;
                if (t >= 1000000) want -= 3;               // t - 1,000,000 의 기록이 창 밖으로
                if (m.DamageInWindow(t) != want) return "DamageInWindow(" + t + ") 기대 " + want + " / 결과 " + m.DamageInWindow(t);
            }
            return null;
        });
    }
}

