using System;
using System.Collections.Generic;

// 32비트 xorshift(시프트 13, 17, 5). 이 문제의 난수는 모두 이 생성기에서 나온다. 고치지 않는다.
public sealed class XorShift32
{
    private uint _state;

    public XorShift32(uint seed) { _state = seed == 0 ? 1u : seed; } // 상태 0 에서는 0 만 나오므로 1 로 바꾼다

    public uint NextUInt()
    {
        uint x = _state;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        _state = x;
        return x;
    }

    // 0 이상 n 미만. 나머지 연산이라 아주 약간 치우치지만, 이 문제에서는 이 식 자체가 명세다.
    public int NextInt(int n) => (int)(NextUInt() % (uint)n);
}

// 동굴 층 생성기. walls[r, c] == true 는 벽, false 는 바닥. r = 0 이 맨 위 행이다.
public static class CaveGenerator
{
    // current 에 4-5 규칙을 한 번 적용한 결과를 next 에 쓴다. current 는 바꾸지 않는다. 두 배열의 크기는 같다.
    public static void Step(bool[,] current, bool[,] next)
    {
        int rows = current.GetLength(0), cols = current.GetLength(1);
        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                int walls = 0;
                for (int dr = -1; dr <= 1; dr++)
                {
                    for (int dc = -1; dc <= 1; dc++)
                    {
                        if (dr == 0 && dc == 0) continue;
                        int nr = r + dr, nc = c + dc;
                        // 격자 밖은 벽으로 센다
                        if (nr < 0 || nc < 0 || nr >= rows || nc >= cols || current[nr, nc]) walls++;
                    }
                }
                // 읽기는 current, 쓰기는 next: 모든 칸이 같은 세대를 보고 동시에 바뀐다
                next[r, c] = current[r, c] ? walls >= 4 : walls >= 5;
            }
        }
    }

    // 상하좌우로 이어진 바닥 영역 중 가장 큰 것만 남기고, 나머지 바닥은 벽으로 메운다. 남은 바닥 칸 수를 반환한다.
    public static int KeepLargestRegion(bool[,] walls)
    {
        int rows = walls.GetLength(0), cols = walls.GetLength(1);
        var label = new int[rows, cols];          // 0 = 아직 안 봄, 1 이상 = 영역 번호
        var stack = new Stack<int>();             // 재귀 대신 명시적 스택: 영역이 칸 수만큼 깊어져도 콜 스택을 쓰지 않는다
        int bestLabel = 0, bestSize = 0, next = 0;

        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                if (walls[r, c] || label[r, c] != 0) continue;
                int id = ++next, size = 0;
                label[r, c] = id;                 // 넣을 때 표시해서 같은 칸을 두 번 넣지 않는다
                stack.Push(r * cols + c);
                while (stack.Count > 0)
                {
                    int cell = stack.Pop(), cr = cell / cols, cc = cell % cols;
                    size++;
                    if (cr > 0 && !walls[cr - 1, cc] && label[cr - 1, cc] == 0) { label[cr - 1, cc] = id; stack.Push(cell - cols); }
                    if (cr < rows - 1 && !walls[cr + 1, cc] && label[cr + 1, cc] == 0) { label[cr + 1, cc] = id; stack.Push(cell + cols); }
                    if (cc > 0 && !walls[cr, cc - 1] && label[cr, cc - 1] == 0) { label[cr, cc - 1] = id; stack.Push(cell - 1); }
                    if (cc < cols - 1 && !walls[cr, cc + 1] && label[cr, cc + 1] == 0) { label[cr, cc + 1] = id; stack.Push(cell + 1); }
                }
                // 영역은 첫 칸의 행 우선 순서대로 발견된다. "더 클 때만" 바꾸므로 동률이면 먼저 발견한 영역이 남는다.
                if (size > bestSize) { bestSize = size; bestLabel = id; }
            }
        }

        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (!walls[r, c] && label[r, c] != bestLabel) walls[r, c] = true;
        return bestSize;
    }

    // 무작위 채움 → Step 을 steps 번 → KeepLargestRegion 을 거친 rows × cols 맵을 반환한다.
    public static bool[,] Generate(int rows, int cols, uint seed, int fillPercent, int steps)
    {
        var rng = new XorShift32(seed);
        var current = new bool[rows, cols];
        var next = new bool[rows, cols];          // 두 배열을 한 번만 만들고 단계마다 역할을 바꾼다

        for (int r = 0; r < rows; r++)            // 행 우선, 칸마다 NextInt(100) 한 번
            for (int c = 0; c < cols; c++)
                current[r, c] = rng.NextInt(100) < fillPercent;

        for (int i = 0; i < steps; i++)
        {
            Step(current, next);
            (current, next) = (next, current);    // 방금 쓴 쪽이 최신 세대
        }

        KeepLargestRegion(current);
        return current;
    }
}

