public static class __Judge
{
    // 케이스마다 별도 배경 스레드에서 실행하고, 제한 시간 안에 끝나지 않으면 그 케이스만 실패로 적는다.
    // (끝나지 않는 반복이 있어도 다음 케이스는 계속 실행되고, 배경 스레드는 Main 이 끝날 때 함께 끝난다.)
    static void RunTimed(string id, int ms, System.Func<string> body, string timeoutReason)
    {
        string err = null;
        var t = new System.Threading.Thread(() =>
        {
            try { err = body(); }
            catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        });
        t.IsBackground = true;
        t.Start();
        if (!t.Join(ms)) { System.Console.WriteLine("[FAIL] " + id + " :: " + ms + " ms 안에 끝나지 않음(" + timeoutReason + ")"); return; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static void Run(string id, System.Func<string> body) => RunTimed(id, 1000, body, "끝나지 않는 반복으로 보임");

    // "#.#/..." 처럼 행을 '/' 로 나눈 문자열. '#' = 벽, '.' = 바닥. 맨 앞 행이 r = 0.
    static bool[,] G(string s)
    {
        string[] rows = s.Split('/');
        var g = new bool[rows.Length, rows[0].Length];
        for (int r = 0; r < rows.Length; r++)
            for (int c = 0; c < rows[0].Length; c++) g[r, c] = rows[r][c] == '#';
        return g;
    }

    static string S(bool[,] g)
    {
        var sb = new System.Text.StringBuilder();
        for (int r = 0; r < g.GetLength(0); r++)
        {
            if (r > 0) sb.Append('/');
            for (int c = 0; c < g.GetLength(1); c++) sb.Append(g[r, c] ? '#' : '.');
        }
        return sb.ToString();
    }

    // 두 맵 문자열이 처음 달라지는 칸과 그 행을 짧게 보여 준다.
    static string Diff(string want, string got)
    {
        string[] w = want.Split('/'), g = got.Split('/');
        for (int r = 0; r < w.Length && r < g.Length; r++)
            if (w[r] != g[r])
            {
                int c = 0;
                while (c < w[r].Length && c < g[r].Length && w[r][c] == g[r][c]) c++;
                string Cut(string row) => row.Length <= 60 ? row : row.Substring(System.Math.Max(0, System.Math.Min(c - 20, row.Length - 60)), 60);
                return "(" + r + ", " + c + ") 칸부터 다름. " + r + "행 기대 " + Cut(w[r]) + " / 결과 " + Cut(g[r]);
            }
        return "행 수가 다름";
    }

    // 기준 구현: 칸마다 8 이웃을 직접 센다(격자 밖은 벽).
    static bool[,] RefStep(bool[,] cur)
    {
        int rows = cur.GetLength(0), cols = cur.GetLength(1);
        var nx = new bool[rows, cols];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
            {
                int w = 0;
                for (int dr = -1; dr <= 1; dr++)
                    for (int dc = -1; dc <= 1; dc++)
                        if ((dr != 0 || dc != 0) && (r + dr < 0 || c + dc < 0 || r + dr >= rows || c + dc >= cols || cur[r + dr, c + dc])) w++;
                nx[r, c] = cur[r, c] ? w >= 4 : w >= 5;
            }
        return nx;
    }

    // 기준 구현: 행 우선으로 훑으며 큐 BFS 로 4방향 영역을 찾고, 더 클 때만 바꾼다.
    static int RefKeep(bool[,] g)
    {
        int rows = g.GetLength(0), cols = g.GetLength(1), best = 0, bestId = 0, id = 0;
        var lab = new int[rows, cols];
        var q = new System.Collections.Generic.Queue<(int, int)>();
        int[] dr = { -1, 1, 0, 0 }, dc = { 0, 0, -1, 1 };
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
            {
                if (g[r, c] || lab[r, c] != 0) continue;
                id++; int size = 0; lab[r, c] = id; q.Enqueue((r, c));
                while (q.Count > 0)
                {
                    var (a, b) = q.Dequeue(); size++;
                    for (int k = 0; k < 4; k++)
                    {
                        int na = a + dr[k], nb = b + dc[k];
                        if (na >= 0 && nb >= 0 && na < rows && nb < cols && !g[na, nb] && lab[na, nb] == 0) { lab[na, nb] = id; q.Enqueue((na, nb)); }
                    }
                }
                if (size > best) { best = size; bestId = id; }
            }
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (!g[r, c] && lab[r, c] != bestId) g[r, c] = true;
        return best;
    }

    static bool[,] RefGenerate(int rows, int cols, uint seed, int fill, int steps)
    {
        uint s = seed == 0 ? 1u : seed;
        var g = new bool[rows, cols];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) { s ^= s << 13; s ^= s >> 17; s ^= s << 5; g[r, c] = (int)(s % 100u) < fill; }
        for (int i = 0; i < steps; i++) g = RefStep(g);
        RefKeep(g);
        return g;
    }

    static string StepCase(string before, string expected)
    {
        var cur = G(before);
        var next = new bool[cur.GetLength(0), cur.GetLength(1)];
        CaveGenerator.Step(cur, next);
        if (S(cur) != before) return "Step 이 current 를 바꿨음: " + before + " -> " + S(cur);
        return S(next) == expected ? null : "Step(" + before + ") 기대 " + expected + " / 결과 " + S(next);
    }

    static string CenterCase(string before, bool expectedWall, string why)
    {
        var cur = G(before);
        var next = new bool[5, 5];
        CaveGenerator.Step(cur, next);
        return next[2, 2] == expectedWall ? null : why + ": Step(" + before + ") 뒤 가운데 칸 기대 " + (expectedWall ? "벽" : "바닥") + " / 결과 " + (next[2, 2] ? "벽" : "바닥");
    }

    static string KeepCase(string before, int expectedCount, string expectedAfter)
    {
        var g = G(before);
        int got = CaveGenerator.KeepLargestRegion(g);
        if (got != expectedCount) return "KeepLargestRegion(" + before + ") 반환값 기대 " + expectedCount + " / 결과 " + got;
        return S(g) == expectedAfter ? null : "KeepLargestRegion(" + before + ") 뒤 기대 " + expectedAfter + " / 결과 " + S(g);
    }

    static string GenCase(int rows, int cols, uint seed, int fill, int steps)
    {
        var got = CaveGenerator.Generate(rows, cols, seed, fill, steps);
        string what = "Generate(" + rows + ", " + cols + ", " + seed + ", " + fill + ", " + steps + ")";
        if (got == null || got.GetLength(0) != rows || got.GetLength(1) != cols) return what + " 의 크기가 " + rows + " × " + cols + " 이 아님";
        string want = S(RefGenerate(rows, cols, seed, fill, steps)), g = S(got);
        if (g != want) return what + " 가 기준 구현과 다름: " + Diff(want, g);
        return S(CaveGenerator.Generate(rows, cols, seed, fill, steps)) == g ? null : what + " 을 두 번 부르면 결과가 다름";
    }

    public static void Main()
    {
        Run("step-thresholds-and-out-of-bounds", () =>
            StepCase(".", "#") ?? StepCase("#", "#") ?? StepCase("...", "###")
            ?? StepCase(".../.../...", "#.#/.../#.#")                       // 모서리는 격자 밖 5칸이 벽
            ?? CenterCase("...../.##../.###./...../.....", true, "벽 칸, 이웃 벽 4개(남는다)")
            ?? CenterCase("...../.##../.##../...../.....", false, "벽 칸, 이웃 벽 3개(바닥이 된다)")
            ?? CenterCase("...../.###./.#.#./...../.....", true, "바닥 칸, 이웃 벽 5개(벽이 된다)")
            ?? CenterCase("...../.###./.#.../...../.....", false, "바닥 칸, 이웃 벽 4개(바닥으로 남는다)"));

        Run("step-is-simultaneous-and-overwrites-next", () =>
        {
            string before = "#..#..##/.#.##..#/..#..#../##..#.#./.#.#...#/#...##../..#.#.#./.##...##";
            string want = S(RefStep(G(before)));
            foreach (bool fillNext in new[] { false, true })              // next 에 이전 내용이 남아 있어도 모든 칸을 써야 한다
            {
                var cur = G(before);
                var next = new bool[8, 8];
                for (int r = 0; r < 8; r++) for (int c = 0; c < 8; c++) next[r, c] = fillNext;
                CaveGenerator.Step(cur, next);
                if (S(cur) != before) return "Step 이 current 를 바꿨음";
                if (S(next) != want) return "next 를 모두 " + (fillNext ? "벽" : "바닥") + "으로 채워 두고 Step(" + before + ") 기대 " + want + " / 결과 " + S(next);
            }
            return null;
        });

        Run("largest-region-is-4-connected", () =>
            KeepCase("....#/###.#/#...#/#.###/#..#.", 11, "....#/###.#/#...#/#.###/#..##")
            ?? KeepCase("..#../..#../##.##/#...#", 4, "..###/..###/#####/#####"));   // 대각선으로만 닿은 세 영역(각 4칸)

        Run("largest-tie-keeps-first-in-row-major", () =>
            KeepCase("##..#/#####/..###", 2, "##..#/#####/#####")
            ?? KeepCase("###.#/#.#.#/#.###/#.#..", 3, "#####/#.###/#.###/#.###")   // (0,3) 영역 2칸, (1,1) 영역 3칸, (3,3) 영역 2칸: 늦게 시작해도 큰 영역
            ?? KeepCase("#.#./#.#./###./....", 7, "###./###./###./...."));

        Run("no-floor-single-floor-all-floor", () =>
            KeepCase("###/###", 0, "###/###") ?? KeepCase("#.#/###", 1, "#.#/###") ?? KeepCase("..../..../....", 12, "..../..../....")
            ?? KeepCase(".", 1, "."));

        Run("generate-matches-spec", () =>
            GenCase(20, 30, 12345u, 45, 5) ?? GenCase(15, 15, 7u, 45, 0) ?? GenCase(15, 15, 7u, 45, 1)
            ?? GenCase(16, 9, 99u, 40, 2) ?? GenCase(16, 9, 99u, 40, 3) ?? GenCase(1, 10, 5u, 30, 2) ?? GenCase(10, 1, 6u, 30, 2)
            ?? GenCase(8, 8, 0u, 45, 4) ?? GenCase(12, 12, 42u, 0, 3) ?? GenCase(12, 12, 42u, 100, 3) ?? GenCase(40, 60, 2026u, 45, 7));

        Run("random-vs-reference", () =>
        {
            uint s = 31337u;
            System.Func<int, int> rnd = m => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)m); };
            for (int t = 0; t < 2000; t++)
            {
                int rows = 1 + rnd(12), cols = 1 + rnd(12), fill = rnd(101);
                var g = new bool[rows, cols];
                for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) g[r, c] = rnd(100) < fill;
                string before = S(g);
                var next = new bool[rows, cols];
                CaveGenerator.Step(g, next);
                string want = S(RefStep(g));
                if (S(next) != want) return "Step(" + before + ") 기대 " + want + " / 결과 " + S(next);
                var a = G(before); var b = G(before);
                int wa = RefKeep(a), ga = CaveGenerator.KeepLargestRegion(b);
                if (wa != ga || S(a) != S(b)) return "KeepLargestRegion(" + before + ") 기대 " + wa + ", " + S(a) + " / 결과 " + ga + ", " + S(b);
            }
            return null;
        });

        // 마지막 케이스: 콜 스택 1MB 스레드에서 실행한다. 재귀로 영역을 채우는 구현은 여기서 스택 오버플로로 프로세스가 끝난다.
        {
            const int N = 512;
            var snake = new bool[N, N];                                     // 홀수 행은 벽, 끝 칸만 번갈아 열린 구불구불한 한 줄 길
            for (int r = 1; r < N; r += 2) for (int c = 0; c < N; c++) snake[r, c] = !(c == ((r / 2) % 2 == 0 ? N - 1 : 0));
            var refSnake = (bool[,])snake.Clone();
            int wantSnake = RefKeep(refSnake);
            string wantBig = S(RefGenerate(N, N, 2026u, 45, 5));
            string err = "3000 ms 안에 끝나지 않음";
            var th = new System.Threading.Thread(() =>
            {
                try
                {
                    int got = CaveGenerator.KeepLargestRegion(snake);
                    if (got != wantSnake) { err = "512 × 512 한 줄 길 KeepLargestRegion 기대 " + wantSnake + " / 결과 " + got; return; }
                    var big = CaveGenerator.Generate(N, N, 2026u, 45, 5);
                    string gotBig = S(big);
                    err = gotBig == wantBig ? null : "Generate(512, 512, 2026, 45, 5) 가 기준 구현과 다름: " + Diff(wantBig, gotBig);
                }
                catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
            }, 1024 * 1024);
            th.IsBackground = true;
            th.Start();
            bool done = th.Join(3000);
            System.Console.WriteLine(done && err == null ? "[PASS] large-map-iterative-in-time" : "[FAIL] large-map-iterative-in-time :: " + (done ? err : "3000 ms 안에 끝나지 않음"));
        }
    }
}
